select ac_cargar_unidad($ac${"slug":"comunidad-1","rama":"comunidad","orden":1,"nivel":1,"titulo_es":"Del yo al nosotros","bajada_es":"Lo que hacés vos importa, y lo que hacemos juntos importa todavía más. Cómo se contagian los hábitos, cómo se organiza un barrio y cómo sostener la esperanza.","objetivos_es":["Distinguir los problemas que se resuelven individualmente de los que requieren acción colectiva","Explicar cómo las normas sociales y el ejemplo contagian comportamientos","Planificar un proyecto ambiental comunitario paso a paso","Aplicar estrategias de comunicación que suman personas","Reconocer la ecoansiedad y formas saludables de afrontarla"],"repasa":["tronco-3"],"requiere_tronco":1,"fuentes":["bit-east","lally-2010-habitos","ecoansiedad-review","onu-ods","naaee-guidelines"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"comunidad-1.s1","orden":1,"tipo":"leccion","titulo_es":"Lo que puedo solo y lo que hacemos juntos","bajada_es":"La tragedia de los comunes, los bienes compartidos y por qué algunos problemas no tienen solución individual.","minutos":11,"pasos":[{"slug":"comunidad-1.s1.p1","orden":1,"grupo":"comunidad-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los bienes comunes","cuerpo":["Hay recursos que son de todos y de nadie a la vez: el aire, un río, un banco de peces, una plaza. Si cada persona usa un poco más de lo que le corresponde, pensando que su parte no cambia nada, entre todos el recurso se agota. A eso se lo llamó \"la tragedia de los comunes\".","Pero la historia muestra que muchas comunidades lograron cuidar sus bienes comunes durante siglos, con reglas acordadas, control mutuo y sanciones justas. La politóloga Elinor Ostrom ganó el Premio Nobel de Economía en 2009 por estudiar cómo lo hacen."]},"solucion":{}},{"slug":"comunidad-1.s1.p2","orden":2,"grupo":"comunidad-1.s1.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una tragedia de los comunes en una laguna de pesca.","items":[{"id":"i1","texto":"Cada pescador piensa que sacar un poco más no cambia nada"},{"id":"i2","texto":"Todos sacan un poco más"},{"id":"i3","texto":"Los peces no alcanzan a reproducirse"},{"id":"i4","texto":"La población de peces se derrumba"},{"id":"i5","texto":"Todos los pescadores pierden"},{"id":"i6","texto":"Los peces se multiplican más cuanto más se pesca"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo que tiene sentido para cada uno por separado termina mal para todos. Por eso los bienes comunes necesitan acuerdos."}},{"slug":"comunidad-1.s1.p3","orden":3,"grupo":"comunidad-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se cuidan los comunes","cuerpo":["Ostrom encontró que las comunidades que cuidan bien sus bienes comunes suelen tener algunas cosas en común: límites claros de quién usa el recurso, reglas adaptadas al lugar, participación de los usuarios en fijar las reglas, vigilancia, sanciones graduales y formas baratas de resolver conflictos."]},"solucion":{}},{"slug":"comunidad-1.s1.p4","orden":4,"grupo":"comunidad-1.s1.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a una comunidad a cuidar un bien común? Marcá todo.","opciones":[{"id":"o1","texto":"Reglas acordadas por quienes usan el recurso"},{"id":"o2","texto":"Vigilar que se cumplan"},{"id":"o3","texto":"Sanciones graduales y justas"},{"id":"o4","texto":"Formas de resolver conflictos"},{"id":"o5","texto":"Que cada uno haga lo que quiera sin hablar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Acuerdos, control y justicia: la receta que Ostrom encontró en comunidades de todo el mundo."}},{"slug":"comunidad-1.s1.p5","orden":5,"grupo":"comunidad-1.s1.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este problema se resuelve sobre todo con acción individual o necesita acción colectiva?","grupos":[{"id":"g1","nombre":"Sobre todo individual"},{"id":"g2","nombre":"Necesita acción colectiva"}],"items":[{"id":"i1","texto":"Apagar las luces de tu cuarto"},{"id":"i2","texto":"Que haya recolección diferenciada en el barrio"},{"id":"i3","texto":"Llevar tu bolsa a las compras"},{"id":"i4","texto":"Limpiar y proteger un arroyo"},{"id":"i5","texto":"Reparar tu bicicleta"},{"id":"i6","texto":"Que la ciudad tenga ciclovías conectadas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas soluciones necesitan las dos cosas: tu hábito y un sistema que lo haga posible. Es lo tuyo y lo de todos del tronco."}},{"slug":"comunidad-1.s1.p6","orden":6,"grupo":"comunidad-1.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un problema es colectivo, lo que hace cada persona no importa.","razones":[{"id":"r1","texto":"Porque lo individual suma, contagia y empuja cambios colectivos"},{"id":"r2","texto":"Porque las personas no forman parte de la sociedad"},{"id":"r3","texto":"Porque los problemas colectivos se resuelven solos"}]},"solucion":{"valor":false,"explicacion":"Lo individual suma, da el ejemplo y genera presión para cambiar el sistema. Y los cambios colectivos empiezan por personas que se organizan.","clave":["r1"]}},{"slug":"comunidad-1.s1.p7","orden":7,"grupo":"comunidad-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La trampa del \"no cambia nada\"","cuerpo":["Frente a problemas enormes como el cambio climático, es común pensar \"lo mío no cambia nada\". Pero ese razonamiento, repetido por millones, es justamente lo que produce el problema. Y al revés: los cambios grandes empiezan con grupos chicos que se organizan y convencen a otros."]},"solucion":{}},{"slug":"comunidad-1.s1.p8","orden":8,"grupo":"comunidad-1.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un vecino dice: \"Si yo separo la basura, no cambia nada; somos millones\". ¿Qué respuesta es más acertada?","opciones":[{"id":"o1","texto":"Lo que hace cada uno suma, y además contagia"},{"id":"o2","texto":"Tiene razón, no tiene sentido hacer nada"},{"id":"o3","texto":"Solo importa lo que hace el gobierno"},{"id":"o4","texto":"Hay que separar solo si todos los demás separan primero"}]},"solucion":{"clave":["o1"],"explicacion":"El \"no cambia nada\" repetido por millones es el problema. Lo mismo al revés es la solución.","por_opcion":{"o3":"El gobierno importa mucho, pero los cambios de hábito también suman y empujan las políticas."}}},{"slug":"comunidad-1.s1.p9","orden":9,"grupo":"comunidad-1.s1.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada bien común con una regla que ayuda a cuidarlo.","izquierda":[{"id":"a1","texto":"Laguna de pesca"},{"id":"a2","texto":"Plaza del barrio"},{"id":"a3","texto":"Aire de la ciudad"},{"id":"a4","texto":"Acuífero de un pueblo"}],"derecha":[{"id":"b1","texto":"Talla mínima y temporada de veda"},{"id":"b2","texto":"Turnos para el mantenimiento entre vecinos"},{"id":"b3","texto":"Límites de emisiones para industrias y vehículos"},{"id":"b4","texto":"Registro de pozos y límites de extracción"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada bien común tiene su regla. Las mejores se acuerdan con quienes lo usan."}},{"slug":"comunidad-1.s1.p10","orden":10,"grupo":"comunidad-1.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna pescan 20 personas. Si cada una saca 5 kg más por temporada de lo sustentable, ¿cuántos kg de más se sacan entre todos?","unidad":"kg","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"20 × 5 = 100 kg de más. Poco para cada uno, mucho para la laguna: la lógica de la tragedia de los comunes."}},{"slug":"comunidad-1.s1.p10.v2","orden":10,"grupo":"comunidad-1.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna pescan 30 personas. Si cada una saca 3 kg más por temporada de lo sustentable, ¿cuántos kg de más se sacan entre todos?","unidad":"kg","decimales":0},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"30 × 3 = 90 kg de más. Poco para cada uno, mucho para la laguna: la lógica de la tragedia de los comunes."}},{"slug":"comunidad-1.s1.p10.v3","orden":10,"grupo":"comunidad-1.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna pescan 10 personas. Si cada una saca 10 kg más por temporada de lo sustentable, ¿cuántos kg de más se sacan entre todos?","unidad":"kg","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"10 × 10 = 100 kg de más. Poco para cada uno, mucho para la laguna: la lógica de la tragedia de los comunes."}},{"slug":"comunidad-1.s1.p11","orden":11,"grupo":"comunidad-1.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un pueblo de pescadores, ¿qué medida se parece más a lo que Ostrom encontró que funciona?","opciones":[{"id":"o1","texto":"Que los pescadores acuerden y controlen sus reglas"},{"id":"o2","texto":"Que cada pescador saque todo lo que pueda"},{"id":"o3","texto":"Que alguien de afuera prohíba pescar sin consultar"},{"id":"o4","texto":"Que no haya ninguna regla ni vigilancia"}]},"solucion":{"clave":["o1"],"explicacion":"Cuando quienes usan el recurso participan en fijar y controlar las reglas, las respetan más.","por_opcion":{"o3":"Las reglas impuestas sin participación suelen cumplirse peor; la participación es clave."}}},{"slug":"comunidad-1.s1.p12","orden":12,"grupo":"comunidad-1.s1.p12","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para acordar el cuidado de un bien común.","items":[{"id":"i1","texto":"Reunir a quienes usan el recurso"},{"id":"i2","texto":"Medir cuánto hay y cuánto se usa"},{"id":"i3","texto":"Acordar reglas y límites"},{"id":"i4","texto":"Vigilar que se cumplan"},{"id":"i5","texto":"Revisar las reglas según los resultados"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Reunir, medir, acordar, controlar y ajustar: el ciclo de un bien común bien cuidado."}},{"slug":"comunidad-1.s1.p13","orden":13,"grupo":"comunidad-1.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta discusión vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La plaza es de todos, así que tenemos que acordar cómo cuidarla."},{"id":"s2","texto":"Como la plaza es de todos, a nadie le toca cuidarla."},{"id":"s3","texto":"Podemos organizar turnos para regar los canteros."},{"id":"s4","texto":"Las comunidades nunca logran cuidar sus bienes comunes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo común necesita acuerdos, no abandono.","por_opcion":{"s2":"Es justamente lo que lleva a la tragedia de los comunes.","s4":"Muchas lo lograron durante siglos, como mostró Elinor Ostrom."}}},{"slug":"comunidad-1.s1.p14","orden":14,"grupo":"comunidad-1.s1.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando cada uno usa de más un recurso compartido y se agota, se habla de la tragedia de los {{0}}; Elinor {{1}} estudió cómo las comunidades los cuidan.","banco":[{"id":"w1","texto":"comunes"},{"id":"w2","texto":"Ostrom"},{"id":"w3","texto":"privados"},{"id":"w4","texto":"Montreal"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Un problema clásico de los bienes compartidos y su respuesta."}}]},{"slug":"comunidad-1.s2","orden":2,"tipo":"leccion","titulo_es":"Los hábitos se contagian","bajada_es":"Normas sociales, ejemplo y visibilidad: por qué hacemos lo que vemos hacer.","minutos":11,"pasos":[{"slug":"comunidad-1.s2.p1","orden":1,"grupo":"comunidad-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Normas sociales","cuerpo":["Las personas se guían mucho por lo que hacen los demás. Una norma social descriptiva es lo que la gente efectivamente hace (\"en este barrio casi todos separan la basura\"). Una norma prescriptiva es lo que se considera correcto (\"hay que separar la basura\").","Las investigaciones sobre comportamiento muestran que saber que otros ya hacen algo aumenta la probabilidad de hacerlo. Por eso, un mensaje como \"la mayoría de tus vecinos ya ahorra agua\" suele funcionar mejor que \"hay que ahorrar agua\"."]},"solucion":{}},{"slug":"comunidad-1.s2.p2","orden":2,"grupo":"comunidad-1.s2.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué mensaje tiene más probabilidades de que los vecinos separen la basura?","opciones":[{"id":"o1","texto":"\"7 de cada 10 vecinos de esta cuadra ya separan\""},{"id":"o2","texto":"\"Muy pocos vecinos separan la basura\""},{"id":"o3","texto":"\"Separar es obligatorio por ordenanza\""},{"id":"o4","texto":"\"La basura es un desastre en este barrio\""}]},"solucion":{"clave":["o1"],"explicacion":"Mostrar que la mayoría ya lo hace invita a sumarse. Decir que \"casi nadie lo hace\" puede tener el efecto contrario.","por_opcion":{"o3":"Las reglas importan, pero mostrar que otros ya lo hacen suele motivar más."}}},{"slug":"comunidad-1.s2.p3","orden":3,"grupo":"comunidad-1.s2.p3","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un mensaje que dice \"casi nadie recicla en este barrio\" motiva a reciclar más.","razones":[{"id":"r1","texto":"Porque muestra que lo normal es no hacerlo"},{"id":"r2","texto":"Porque las personas nunca se fijan en los demás"},{"id":"r3","texto":"Porque los mensajes negativos siempre funcionan mejor"}]},"solucion":{"valor":false,"explicacion":"Puede tener el efecto contrario: muestra que lo normal es no reciclar. Es mejor destacar a quienes sí lo hacen.","clave":["r1"]}},{"slug":"comunidad-1.s2.p4","orden":4,"grupo":"comunidad-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo visible se contagia","cuerpo":["Los comportamientos que se ven se contagian más. Estudios en distintos países encontraron que cuando una casa instala paneles solares, aumenta la probabilidad de que los vecinos cercanos también los instalen. Lo mismo pasa con las huertas, las bicis o las composteras visibles.","Por eso, hacer visible lo que ya se hace —un cartel en la compostera, una huerta en el frente— es una forma de sumar."]},"solucion":{}},{"slug":"comunidad-1.s2.p5","orden":5,"grupo":"comunidad-1.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una huerta en el frente de una casa puede contagiar a la cuadra.","items":[{"id":"i1","texto":"Una familia arma una huerta en el frente"},{"id":"i2","texto":"Los vecinos la ven todos los días"},{"id":"i3","texto":"Algunos preguntan cómo hacerla"},{"id":"i4","texto":"La familia comparte semillas y consejos"},{"id":"i5","texto":"Aparecen más huertas en la cuadra"},{"id":"i6","texto":"La huerta obliga a los vecinos a plantar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ejemplo visible y la ayuda concreta son una combinación poderosa."}},{"slug":"comunidad-1.s2.p6","orden":6,"grupo":"comunidad-1.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hacerlo fácil, atractivo, social y oportuno","cuerpo":["Un marco muy usado para diseñar cambios de comportamiento, del equipo británico de ciencias del comportamiento, se resume en cuatro palabras: fácil, atractivo, social y oportuno. Si algo es fácil de hacer, llama la atención, otros lo hacen y se propone en el momento justo, es mucho más probable que ocurra."],"lista":["Fácil: sacar obstáculos","Atractivo: que llame la atención","Social: mostrar que otros lo hacen","Oportuno: en el momento justo"]},"solucion":{}},{"slug":"comunidad-1.s2.p7","orden":7,"grupo":"comunidad-1.s2.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada principio con un ejemplo.","izquierda":[{"id":"a1","texto":"Fácil"},{"id":"a2","texto":"Atractivo"},{"id":"a3","texto":"Social"},{"id":"a4","texto":"Oportuno"}],"derecha":[{"id":"b1","texto":"Poner el tacho de reciclables al lado del de basura"},{"id":"b2","texto":"Un cartel colorido con un dibujo claro"},{"id":"b3","texto":"Mostrar cuántos vecinos ya participan"},{"id":"b4","texto":"Invitar a compostar justo cuando llega la primavera"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palancas que cualquier proyecto comunitario puede usar."}},{"slug":"comunidad-1.s2.p8","orden":8,"grupo":"comunidad-1.s2.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida hace más fácil el comportamiento buscado o más difícil?","grupos":[{"id":"g1","nombre":"Más fácil"},{"id":"g2","nombre":"Más difícil"}],"items":[{"id":"i1","texto":"Bicicletero en la puerta de la escuela"},{"id":"i2","texto":"Tacho de reciclables en el sótano sin luz"},{"id":"i3","texto":"Bebedero junto al kiosco"},{"id":"i4","texto":"Formulario de diez páginas para sumarse a la huerta"},{"id":"i5","texto":"Punto verde en la entrada del súper"},{"id":"i6","texto":"Bicicletero a tres cuadras de la entrada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas veces el obstáculo no es la voluntad sino la fricción. Sacarla es la primera palanca."}},{"slug":"comunidad-1.s2.p9","orden":9,"grupo":"comunidad-1.s2.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un comportamiento se contagie en un barrio? Marcá todo.","opciones":[{"id":"o1","texto":"Que sea visible"},{"id":"o2","texto":"Que alguien cercano lo haga primero"},{"id":"o3","texto":"Que sea fácil de copiar"},{"id":"o4","texto":"Que haya ayuda para empezar"},{"id":"o5","texto":"Que se haga en secreto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Visibilidad, cercanía, facilidad y ayuda: así se contagian los hábitos."}},{"slug":"comunidad-1.s2.p10","orden":10,"grupo":"comunidad-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuadra de 40 casas, el 25 % ya composta. ¿Cuántas casas compostan?","unidad":"casas","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"40 × 25 ÷ 100 = 10 casas. Contarlo en voz alta (\"10 familias de la cuadra ya compostan\") es una norma social que invita a sumarse."}},{"slug":"comunidad-1.s2.p10.v2","orden":10,"grupo":"comunidad-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuadra de 60 casas, el 20 % ya composta. ¿Cuántas casas compostan?","unidad":"casas","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"60 × 20 ÷ 100 = 12 casas. Contarlo en voz alta (\"12 familias de la cuadra ya compostan\") es una norma social que invita a sumarse."}},{"slug":"comunidad-1.s2.p10.v3","orden":10,"grupo":"comunidad-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuadra de 30 casas, el 30 % ya composta. ¿Cuántas casas compostan?","unidad":"casas","decimales":0},"solucion":{"valor":9,"tolerancia":0.5,"explicacion":"30 × 30 ÷ 100 = 9 casas. Contarlo en voz alta (\"9 familias de la cuadra ya compostan\") es una norma social que invita a sumarse."}},{"slug":"comunidad-1.s2.p11","orden":11,"grupo":"comunidad-1.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si algo es fácil de hacer, es más probable que la gente lo haga.","razones":[{"id":"r1","texto":"Porque sacar obstáculos reduce la fricción para actuar"},{"id":"r2","texto":"Porque la gente prefiere siempre lo difícil"},{"id":"r3","texto":"Porque la facilidad no influye en lo que hacemos"}]},"solucion":{"valor":true,"explicacion":"Sacar obstáculos es una de las palancas más efectivas para cambiar comportamientos: muchas veces el problema no es la voluntad, sino la fricción.","clave":["r1"]}},{"slug":"comunidad-1.s2.p12","orden":12,"grupo":"comunidad-1.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una escuela quiere que más chicos traigan su botella reutilizable. ¿Qué medida la hace más fácil?","opciones":[{"id":"o1","texto":"Instalar bebederos para rellenarla"},{"id":"o2","texto":"Dar una charla una vez por año"},{"id":"o3","texto":"Prohibir las botellas descartables sin alternativa"},{"id":"o4","texto":"Pegar un cartel en la dirección"}]},"solucion":{"clave":["o1"],"explicacion":"Si rellenar es fácil, traer la botella se vuelve lo más cómodo.","por_opcion":{"o3":"Sin un lugar para rellenar, la prohibición sola genera rechazo."}}},{"slug":"comunidad-1.s2.p13","orden":13,"grupo":"comunidad-1.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta campaña escolar y marcá lo que puede funcionar mal.","segmentos":[{"id":"s1","texto":"Pondremos tachos de reciclables al lado de cada tacho común."},{"id":"s2","texto":"El afiche dirá: \"Casi nadie en esta escuela recicla\"."},{"id":"s3","texto":"Mostraremos cada mes cuántos kilos se reciclaron."},{"id":"s4","texto":"Los tachos de reciclables estarán solo en la dirección."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Fácil, atractivo, social y oportuno: y cuidado con los mensajes que muestran lo contrario.","por_opcion":{"s2":"Muestra que lo normal es no reciclar; mejor destacar a quienes sí lo hacen.","s4":"Si es difícil, casi nadie lo va a hacer."}}},{"slug":"comunidad-1.s2.p14","orden":14,"grupo":"comunidad-1.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que la gente efectivamente hace es una norma social {{0}}; para que un hábito se contagie conviene que sea {{1}} y fácil.","banco":[{"id":"w1","texto":"descriptiva"},{"id":"w2","texto":"visible"},{"id":"w3","texto":"secreta"},{"id":"w4","texto":"oculto"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para que un comportamiento se contagie."}}]},{"slug":"comunidad-1.s3","orden":3,"tipo":"leccion","titulo_es":"Organizarse en el barrio","bajada_es":"Del problema al proyecto: diagnóstico, objetivo, aliados, plan, acción y evaluación.","minutos":11,"pasos":[{"slug":"comunidad-1.s3.p1","orden":1,"grupo":"comunidad-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De la queja al proyecto","cuerpo":["Muchos problemas ambientales del barrio —un basural en un terreno, una plaza abandonada, un arroyo sucio, falta de árboles— se pueden mejorar con un proyecto comunitario. El camino suele tener varios pasos: entender bien el problema (diagnóstico), elegir un objetivo concreto, sumar aliados, armar un plan, actuar y evaluar lo logrado."]},"solucion":{}},{"slug":"comunidad-1.s3.p2","orden":2,"grupo":"comunidad-1.s3.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de un proyecto comunitario.","items":[{"id":"i1","texto":"Hacer un diagnóstico del problema"},{"id":"i2","texto":"Elegir un objetivo concreto y medible"},{"id":"i3","texto":"Sumar aliados"},{"id":"i4","texto":"Armar un plan con tareas y fechas"},{"id":"i5","texto":"Actuar"},{"id":"i6","texto":"Evaluar y contar los resultados"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Seis pasos que ordenan cualquier proyecto, grande o chico."}},{"slug":"comunidad-1.s3.p3","orden":3,"grupo":"comunidad-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un objetivo concreto","cuerpo":["Un objetivo como \"mejorar el ambiente del barrio\" es demasiado general. Uno concreto dice qué, cuánto, dónde y para cuándo: \"plantar 30 árboles nativos en las veredas de las cuatro cuadras alrededor de la escuela antes de fin de año\".","Los objetivos concretos permiten saber si se logró, organizar las tareas y contar los resultados."]},"solucion":{}},{"slug":"comunidad-1.s3.p4","orden":4,"grupo":"comunidad-1.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estos es el objetivo más concreto?","opciones":[{"id":"o1","texto":"Instalar 3 composteras en la plaza antes de octubre"},{"id":"o2","texto":"Hacer del barrio un lugar más verde y lindo"},{"id":"o3","texto":"Concientizar a todos sobre el ambiente"},{"id":"o4","texto":"Cambiar la forma de pensar de los vecinos"}]},"solucion":{"clave":["o1"],"explicacion":"Qué, cuánto, dónde y para cuándo. Así se puede planificar y evaluar.","por_opcion":{"o3":"Es importante, pero así planteado no se puede medir ni saber cuándo se logró."}}},{"slug":"comunidad-1.s3.p5","orden":5,"grupo":"comunidad-1.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aliados","cuerpo":["Casi ningún proyecto se hace solo. Los aliados pueden ser vecinos, escuelas, clubes, iglesias, comercios, cooperativas, organizaciones ambientales, universidades y el municipio. Cada uno aporta algo: personas, lugar, herramientas, conocimiento, permisos, difusión.","Un buen mapa de aliados pregunta: ¿a quién le importa este problema?, ¿quién puede ayudar?, ¿quién tiene que autorizar?"]},"solucion":{}},{"slug":"comunidad-1.s3.p6","orden":6,"grupo":"comunidad-1.s3.p6","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada aliado con lo que puede aportar a un proyecto de arbolado.","izquierda":[{"id":"a1","texto":"Vivero municipal"},{"id":"a2","texto":"Escuela"},{"id":"a3","texto":"Municipio"},{"id":"a4","texto":"Ferretería del barrio"}],"derecha":[{"id":"b1","texto":"Plantines de nativas"},{"id":"b2","texto":"Estudiantes y un espacio para aprender"},{"id":"b3","texto":"Permisos para plantar en las veredas"},{"id":"b4","texto":"Herramientas prestadas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada aliado suma una pieza distinta. Juntos hacen posible lo que nadie podría solo."}},{"slug":"comunidad-1.s3.p7","orden":7,"grupo":"comunidad-1.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué paso del proyecto es cada acción?","grupos":[{"id":"g1","nombre":"Diagnóstico"},{"id":"g2","nombre":"Plan"},{"id":"g3","nombre":"Evaluación"}],"items":[{"id":"i1","texto":"Contar cuántos árboles faltan en cada cuadra"},{"id":"i2","texto":"Hacer un calendario de plantación"},{"id":"i3","texto":"Contar cuántos árboles sobrevivieron al año"},{"id":"i4","texto":"Preguntar a los vecinos qué problemas ven"},{"id":"i5","texto":"Repartir tareas entre los grupos"},{"id":"i6","texto":"Hacer una encuesta después de la plantación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada etapa tiene sus tareas. Saltarse el diagnóstico o la evaluación es un error común."}},{"slug":"comunidad-1.s3.p8","orden":8,"grupo":"comunidad-1.s3.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Evaluar un proyecto al final es una pérdida de tiempo si ya se hizo la acción.","razones":[{"id":"r1","texto":"Porque muestra qué funcionó y ayuda a sumar apoyo"},{"id":"r2","texto":"Porque los proyectos nunca tienen resultados"},{"id":"r3","texto":"Porque evaluar arruina lo que se hizo"}]},"solucion":{"valor":false,"explicacion":"La evaluación muestra qué funcionó, qué no y qué mejorar. Además, contar los resultados ayuda a sumar más gente y apoyo para el próximo paso.","clave":["r1"]}},{"slug":"comunidad-1.s3.p9","orden":9,"grupo":"comunidad-1.s3.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un proyecto chico puede crecer.","items":[{"id":"i1","texto":"Un grupo de vecinos limpia un terreno y arma una huerta"},{"id":"i2","texto":"Miden y cuentan lo que lograron"},{"id":"i3","texto":"Otros vecinos y la escuela se suman"},{"id":"i4","texto":"El municipio apoya con herramientas y agua"},{"id":"i5","texto":"La huerta se convierte en un espacio comunitario estable"},{"id":"i6","texto":"El proyecto crece solo sin que nadie lo cuente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Empezar chico, mostrar resultados y sumar aliados: el camino de muchos proyectos exitosos."}},{"slug":"comunidad-1.s3.p10","orden":10,"grupo":"comunidad-1.s3.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que un proyecto comunitario dure en el tiempo? Marcá todo.","opciones":[{"id":"o1","texto":"Repartir las tareas entre varias personas"},{"id":"o2","texto":"Tener reuniones periódicas cortas"},{"id":"o3","texto":"Celebrar los logros"},{"id":"o4","texto":"Sumar nuevas personas cada tanto"},{"id":"o5","texto":"Que una sola persona haga todo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Si todo depende de una persona, el proyecto se apaga cuando esa persona se cansa."}},{"slug":"comunidad-1.s3.p11","orden":11,"grupo":"comunidad-1.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto plantó 30 árboles y al año sobrevivieron 24. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"24 ÷ 30 × 100 = 80 %. Medir la supervivencia permite aprender: ¿faltó riego?, ¿se eligieron bien las especies?"}},{"slug":"comunidad-1.s3.p11.v2","orden":11,"grupo":"comunidad-1.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto plantó 50 árboles y al año sobrevivieron 40. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"40 ÷ 50 × 100 = 80 %. Medir la supervivencia permite aprender: ¿faltó riego?, ¿se eligieron bien las especies?"}},{"slug":"comunidad-1.s3.p11.v3","orden":11,"grupo":"comunidad-1.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto plantó 20 árboles y al año sobrevivieron 17. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1.7,"explicacion":"17 ÷ 20 × 100 = 85 %. Medir la supervivencia permite aprender: ¿faltó riego?, ¿se eligieron bien las especies?"}},{"slug":"comunidad-1.s3.p12","orden":12,"grupo":"comunidad-1.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de un grupo de vecinos y marcá los problemas.","segmentos":[{"id":"s1","texto":"Contamos los árboles que faltan en cada cuadra."},{"id":"s2","texto":"Nuestro objetivo es \"salvar el planeta\"."},{"id":"s3","texto":"Pedimos permiso al municipio y plantines al vivero."},{"id":"s4","texto":"Juan va a hacer todas las tareas porque tiene tiempo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proyecto tiene un objetivo concreto y tareas compartidas.","por_opcion":{"s2":"Es demasiado general: conviene un objetivo concreto y medible.","s4":"Si todo depende de una persona, el proyecto es frágil."}}},{"slug":"comunidad-1.s3.p13","orden":13,"grupo":"comunidad-1.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Todo proyecto empieza con un {{0}}; necesita un objetivo {{1}}; y termina con una {{2}}.","banco":[{"id":"w1","texto":"diagnóstico"},{"id":"w2","texto":"concreto"},{"id":"w3","texto":"evaluación"},{"id":"w4","texto":"festejo"},{"id":"w5","texto":"general"},{"id":"w6","texto":"queja"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La estructura de cualquier proyecto comunitario."}}]},{"slug":"comunidad-1.s4","orden":4,"tipo":"leccion","titulo_es":"Hablar para sumar","bajada_es":"Escuchar, partir de lo que le importa al otro y contar historias cercanas: cómo conversar de ambiente para que la gente se acerque.","minutos":11,"pasos":[{"slug":"comunidad-1.s4.p1","orden":1,"grupo":"comunidad-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Empezar por lo que le importa al otro","cuerpo":["Las personas se interesan por el ambiente por razones distintas: la salud de sus hijos, el ahorro de plata, el amor por un lugar, la fe, la justicia, el trabajo. Una conversación funciona mejor cuando parte de lo que le importa a la otra persona, en lugar de lo que le importa a quien habla.","Por ejemplo, a alguien preocupado por la plata le puede interesar más el ahorro de la eficiencia energética que las toneladas de CO₂."]},"solucion":{}},{"slug":"comunidad-1.s4.p2","orden":2,"grupo":"comunidad-1.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada interés con una forma de hablar de ambiente que conecta con él.","izquierda":[{"id":"a1","texto":"Ahorro de plata"},{"id":"a2","texto":"Salud de los chicos"},{"id":"a3","texto":"Amor por un lugar"},{"id":"a4","texto":"Justicia"}],"derecha":[{"id":"b1","texto":"Cuánto se ahorra en la factura con eficiencia"},{"id":"b2","texto":"Aire limpio y calles seguras para ir a la escuela"},{"id":"b3","texto":"Cuidar el río o la sierra donde creciste"},{"id":"b4","texto":"Quiénes sufren más la contaminación y los extremos del clima"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El mismo tema puede contarse de muchas formas. La mejor es la que conecta con el otro."}},{"slug":"comunidad-1.s4.p3","orden":3,"grupo":"comunidad-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Escuchar primero","cuerpo":["En una conversación difícil, escuchar primero y hacer preguntas abiertas (\"¿qué te preocupa?\", \"¿cómo lo ves vos?\") genera más confianza que dar datos de entrada. Cuando alguien se siente escuchado, está más dispuesto a escuchar.","Los datos siguen siendo importantes, pero funcionan mejor dentro de una historia cercana que en una lista de números."]},"solucion":{}},{"slug":"comunidad-1.s4.p4","orden":4,"grupo":"comunidad-1.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu tía dice que \"eso del cambio climático es exagerado\". ¿Qué conviene hacer primero?","opciones":[{"id":"o1","texto":"Preguntarle qué la hace pensar eso y escucharla"},{"id":"o2","texto":"Mostrarle diez gráficos de temperatura seguidos"},{"id":"o3","texto":"Decirle que está equivocada y cambiar de tema"},{"id":"o4","texto":"Mandarle un video largo sin comentarios"}]},"solucion":{"clave":["o1"],"explicacion":"Escuchar primero no es darle la razón: es entender desde dónde habla, para poder conversar de verdad.","por_opcion":{"o3":"Cortar la conversación cierra la puerta; escuchar la abre."}}},{"slug":"comunidad-1.s4.p5","orden":5,"grupo":"comunidad-1.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para convencer a alguien, lo mejor es darle la mayor cantidad posible de datos de una sola vez.","razones":[{"id":"r1","texto":"Porque una avalancha de datos suele generar rechazo"},{"id":"r2","texto":"Porque los datos no sirven nunca"},{"id":"r3","texto":"Porque las personas no entienden los números"}]},"solucion":{"valor":false,"explicacion":"Una avalancha de datos suele generar rechazo. Conecta mejor partir de lo que le importa, escuchar y usar pocos datos bien elegidos dentro de una historia.","clave":["r1"]}},{"slug":"comunidad-1.s4.p6","orden":6,"grupo":"comunidad-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Historias cercanas y soluciones","cuerpo":["Los problemas lejanos y enormes —los polos, el planeta entero— pueden generar distancia o angustia. Las historias cercanas —el arroyo del barrio, la ola de calor del último verano, la cooperativa que recicla en tu ciudad— conectan más.","Y hablar de soluciones que ya están funcionando genera más ganas de actuar que hablar solo de catástrofes."]},"solucion":{}},{"slug":"comunidad-1.s4.p7","orden":7,"grupo":"comunidad-1.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta forma de contar suele acercar o alejar a la gente?","grupos":[{"id":"g1","nombre":"Acerca"},{"id":"g2","nombre":"Aleja"}],"items":[{"id":"i1","texto":"La historia de una cooperativa de recicladores del barrio"},{"id":"i2","texto":"Solo imágenes de catástrofes sin salida"},{"id":"i3","texto":"Cuánto ahorró una familia con burletes"},{"id":"i4","texto":"Culpar a quien escucha de todos los problemas"},{"id":"i5","texto":"Cómo volvieron los pájaros a la plaza con nativas"},{"id":"i6","texto":"Una lista de veinte datos sin contexto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cercanía y soluciones acercan. Culpa y catástrofe sin salida alejan."}},{"slug":"comunidad-1.s4.p8","orden":8,"grupo":"comunidad-1.s4.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una conversación que suma.","items":[{"id":"i1","texto":"Preguntar qué le preocupa a la otra persona"},{"id":"i2","texto":"Escuchar sin interrumpir"},{"id":"i3","texto":"Encontrar algo en común"},{"id":"i4","texto":"Contar una historia cercana con una solución"},{"id":"i5","texto":"Invitar a una acción concreta y fácil"},{"id":"i6","texto":"Empezar diciendo que está todo perdido"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Escuchar, conectar, contar y proponer: una conversación que abre puertas."}},{"slug":"comunidad-1.s4.p9","orden":9,"grupo":"comunidad-1.s4.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene evitar al hablar de ambiente con alguien que piensa distinto? Marcá todo.","opciones":[{"id":"o1","texto":"Burlarse de lo que piensa"},{"id":"o2","texto":"Culparlo de todo"},{"id":"o3","texto":"Dar una catarata de datos sin escuchar"},{"id":"o4","texto":"Hablar solo de catástrofes sin soluciones"},{"id":"o5","texto":"Hacer preguntas abiertas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las preguntas abiertas son justamente lo que conviene hacer."}},{"slug":"comunidad-1.s4.p10","orden":10,"grupo":"comunidad-1.s4.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas invitaciones de la más fácil de aceptar a la más difícil, para alguien que recién empieza.","items":[{"id":"i1","texto":"\"¿Venís el sábado un rato a la plantación de la plaza?\""},{"id":"i2","texto":"\"¿Te sumás a separar los reciclables en casa?\""},{"id":"i3","texto":"\"¿Querés organizar vos la próxima jornada?\""},{"id":"i4","texto":"\"Tenés que cambiar toda tu forma de vivir\""}],"extremos":["Más fácil","Más difícil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Empezar con algo fácil y concreto permite que las personas se sumen de a poco.","valores":{"i1":"muy fácil","i2":"fácil","i3":"difícil","i4":"muy difícil"}}},{"slug":"comunidad-1.s4.p11","orden":11,"grupo":"comunidad-1.s4.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estas es una pregunta abierta, que invita a conversar?","opciones":[{"id":"o1","texto":"¿Qué es lo que más te preocupa del barrio?"},{"id":"o2","texto":"¿No te importa el planeta, no?"},{"id":"o3","texto":"¿Estás de acuerdo conmigo, sí o no?"},{"id":"o4","texto":"¿Viste que yo tenía razón?"}]},"solucion":{"clave":["o1"],"explicacion":"Las preguntas abiertas invitan a la otra persona a contar lo que piensa.","por_opcion":{"o3":"Las preguntas de sí o no cierran la conversación; las abiertas la abren."}}},{"slug":"comunidad-1.s4.p12","orden":12,"grupo":"comunidad-1.s4.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Hablar de soluciones que ya funcionan suele generar más ganas de actuar que hablar solo de catástrofes.","razones":[{"id":"r1","texto":"Porque muestran que actuar sirve"},{"id":"r2","texto":"Porque las catástrofes no existen"},{"id":"r3","texto":"Porque a nadie le interesan las soluciones"}]},"solucion":{"valor":true,"explicacion":"Las soluciones muestran que se puede hacer algo; las catástrofes sin salida suelen generar impotencia y rechazo.","clave":["r1"]}},{"slug":"comunidad-1.s4.p13","orden":13,"grupo":"comunidad-1.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje que alguien quiere mandar al grupo de la familia y marcá lo que puede alejar.","segmentos":[{"id":"s1","texto":"Este finde plantamos árboles en la plaza, ¿alguien se suma?"},{"id":"s2","texto":"Si no venís es porque no te importa el planeta."},{"id":"s3","texto":"Llevamos mate y facturas."},{"id":"s4","texto":"Igual ya es tarde, el mundo se termina."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Invitar sin culpa y con esperanza suma mucho más.","por_opcion":{"s2":"Culpar aleja; mejor invitar sin juzgar.","s4":"El mensaje de catástrofe sin salida desanima a actuar."}}},{"slug":"comunidad-1.s4.p14","orden":14,"grupo":"comunidad-1.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para hablar de ambiente conviene {{0}} primero, partir de lo que le {{1}} al otro y contar historias con {{2}}.","banco":[{"id":"w1","texto":"escuchar"},{"id":"w2","texto":"importa"},{"id":"w3","texto":"soluciones"},{"id":"w4","texto":"gritar"},{"id":"w5","texto":"molesta"},{"id":"w6","texto":"culpas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para conversaciones que suman."}}]},{"slug":"comunidad-1.s5","orden":5,"tipo":"leccion","titulo_es":"Ecoansiedad y esperanza activa","bajada_es":"La preocupación por el ambiente es comprensible. Cómo reconocerla, cuidarse y convertirla en acción.","minutos":11,"pasos":[{"slug":"comunidad-1.s5.p1","orden":1,"grupo":"comunidad-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es la ecoansiedad","cuerpo":["La ecoansiedad es la preocupación, el miedo o la angustia que siente mucha gente frente a los problemas ambientales, sobre todo el cambio climático. No es una enfermedad: es una reacción comprensible frente a un problema real. Estudios con niños y jóvenes de distintos países encontraron que muchos sienten preocupación, tristeza o enojo por el futuro del planeta.","Se vuelve un problema cuando paraliza, afecta el sueño o la vida cotidiana, o lleva a la desesperanza."]},"solucion":{}},{"slug":"comunidad-1.s5.p2","orden":2,"grupo":"comunidad-1.s5.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Sentir preocupación por el cambio climático es un trastorno mental.","razones":[{"id":"r1","texto":"Porque es una reacción comprensible frente a un problema real"},{"id":"r2","texto":"Porque nadie se preocupa por el ambiente"},{"id":"r3","texto":"Porque preocuparse cura el problema"}]},"solucion":{"valor":false,"explicacion":"Es una reacción comprensible frente a un problema real. Solo se vuelve un problema de salud cuando paraliza o afecta mucho la vida cotidiana; en ese caso, conviene pedir ayuda.","clave":["r1"]}},{"slug":"comunidad-1.s5.p3","orden":3,"grupo":"comunidad-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué ayuda","cuerpo":["Varias cosas ayudan a transformar la angustia en algo más llevadero: hablar de lo que se siente con otras personas, informarse con fuentes confiables sin sobreexponerse a noticias catastróficas, hacer algo concreto (la acción reduce la sensación de impotencia), participar con otros y conectar con la naturaleza.","Si la angustia es muy fuerte o dura mucho, es importante hablar con alguien de confianza o con un profesional de la salud mental."]},"solucion":{}},{"slug":"comunidad-1.s5.p4","orden":4,"grupo":"comunidad-1.s5.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a manejar la ecoansiedad? Marcá todo.","opciones":[{"id":"o1","texto":"Hablar de lo que se siente"},{"id":"o2","texto":"Hacer algo concreto con otros"},{"id":"o3","texto":"Informarse con fuentes confiables sin sobreexponerse"},{"id":"o4","texto":"Pasar tiempo en la naturaleza"},{"id":"o5","texto":"Mirar noticias catastróficas todo el día"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La sobreexposición a noticias angustiantes aumenta la ansiedad. Actuar con otros y conectar con la naturaleza, en cambio, ayudan."}},{"slug":"comunidad-1.s5.p5","orden":5,"grupo":"comunidad-1.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Esperanza activa","cuerpo":["La esperanza activa no es pensar que todo va a salir bien solo: es actuar para que salga mejor, aunque no haya garantías. Se apoya en hechos reales: la capa de ozono se está recuperando, las energías renovables crecieron muchísimo, especies que estaban al borde de desaparecer se recuperaron, ríos contaminados se limpiaron.","Cada décima de grado de calentamiento que se evita importa. No es \"todo o nada\": cuanto más se haga, mejor."]},"solucion":{}},{"slug":"comunidad-1.s5.p6","orden":6,"grupo":"comunidad-1.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la acción puede reducir la angustia.","items":[{"id":"i1","texto":"Una persona siente angustia por el ambiente"},{"id":"i2","texto":"Se suma a un grupo que planta árboles en su barrio"},{"id":"i3","texto":"Conoce gente con las mismas preocupaciones"},{"id":"i4","texto":"Ve resultados concretos de lo que hacen"},{"id":"i5","texto":"Siente menos impotencia y más esperanza"},{"id":"i6","texto":"La acción hace que el problema desaparezca del todo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La acción colectiva no resuelve todo, pero cambia cómo se vive la preocupación."}},{"slug":"comunidad-1.s5.p7","orden":7,"grupo":"comunidad-1.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un hecho que alimenta la esperanza activa o un pensamiento que paraliza?","grupos":[{"id":"g1","nombre":"Alimenta la esperanza"},{"id":"g2","nombre":"Paraliza"}],"items":[{"id":"i1","texto":"La capa de ozono se está recuperando"},{"id":"i2","texto":"Ya es tarde, no hay nada que hacer"},{"id":"i3","texto":"Las renovables crecieron muchísimo en diez años"},{"id":"i4","texto":"Lo que yo haga no importa"},{"id":"i5","texto":"El yaguareté volvió a nacer en los Esteros del Iberá"},{"id":"i6","texto":"Si no se resuelve todo, no sirve nada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La esperanza activa se apoya en hechos y en que cada avance cuenta."}},{"slug":"comunidad-1.s5.p8","orden":8,"grupo":"comunidad-1.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una compañera dice que está muy angustiada por el clima y no puede dormir. ¿Qué es lo más adecuado?","opciones":[{"id":"o1","texto":"Escucharla y sugerir pedir ayuda"},{"id":"o2","texto":"Decirle que exagera y que no piense en eso"},{"id":"o3","texto":"Mostrarle más noticias sobre el tema para que se informe"},{"id":"o4","texto":"Decirle que tiene razón y que todo está perdido"}]},"solucion":{"clave":["o1"],"explicacion":"Escuchar sin minimizar y, si afecta el sueño o la vida diaria, buscar ayuda.","por_opcion":{"o3":"Si ya está angustiada, más noticias pueden empeorarlo."}}},{"slug":"comunidad-1.s5.p9","orden":9,"grupo":"comunidad-1.s5.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada estrategia con cómo ayuda.","izquierda":[{"id":"a1","texto":"Hablar con otros"},{"id":"a2","texto":"Actuar en grupo"},{"id":"a3","texto":"Limitar las noticias"},{"id":"a4","texto":"Contacto con la naturaleza"}],"derecha":[{"id":"b1","texto":"Saber que no estás solo"},{"id":"b2","texto":"Reduce la sensación de impotencia"},{"id":"b3","texto":"Evita la sobreexposición"},{"id":"b4","texto":"Descansa y reconecta con lo que se quiere cuidar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Estrategias simples que ayudan a sostener el compromiso sin quemarse."}},{"slug":"comunidad-1.s5.p10","orden":10,"grupo":"comunidad-1.s5.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas frases de la más útil a la menos útil para alguien con ecoansiedad.","items":[{"id":"i1","texto":"\"Es entendible lo que sentís; ¿querés que hagamos algo juntos?\""},{"id":"i2","texto":"\"Hay avances reales, como la capa de ozono\""},{"id":"i3","texto":"\"No pienses en eso\""},{"id":"i4","texto":"\"Ya es tarde, no hay nada que hacer\""}],"extremos":["Más útil","Menos útil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Validar, acompañar y mostrar caminos: eso ayuda. Minimizar o dramatizar, no.","valores":{"i1":"escucha e invita","i2":"da esperanza con hechos","i3":"minimiza","i4":"paraliza"}}},{"slug":"comunidad-1.s5.p11","orden":11,"grupo":"comunidad-1.s5.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo en redes y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Si te angustia el clima, hablalo con alguien."},{"id":"s2","texto":"Leé todas las noticias de catástrofes que encuentres para estar informado."},{"id":"s3","texto":"Sumarte a un grupo que actúa ayuda a sentirte menos solo."},{"id":"s4","texto":"Si no se puede resolver todo, no vale la pena hacer nada."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cuidarse también es parte de cuidar el ambiente a largo plazo.","por_opcion":{"s2":"La sobreexposición a noticias catastróficas aumenta la angustia.","s4":"Cada avance importa: no es todo o nada."}}},{"slug":"comunidad-1.s5.p12","orden":12,"grupo":"comunidad-1.s5.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La preocupación por los problemas ambientales se llama {{0}}; actuar sin garantías pero con compromiso es esperanza {{1}}.","banco":[{"id":"w1","texto":"ecoansiedad"},{"id":"w2","texto":"activa"},{"id":"w3","texto":"nostalgia"},{"id":"w4","texto":"pasiva"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para sostener el compromiso sin paralizarse."}},{"slug":"comunidad-1.s5.p13","orden":13,"grupo":"comunidad-1.s5.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Frente al cambio climático, ¿qué significa decir que \"no es todo o nada\"?","opciones":[{"id":"o1","texto":"Que cada décima de grado evitada reduce daños"},{"id":"o2","texto":"Que si no se evita todo, no sirve de nada"},{"id":"o3","texto":"Que ya no se puede hacer nada útil"},{"id":"o4","texto":"Que solo importa lo que hagan los demás países"}]},"solucion":{"clave":["o1"],"explicacion":"No hay un umbral mágico después del cual todo da igual: cuanto menos calentamiento, menos impactos. Por eso ninguna acción es inútil si suma en la dirección correcta.","por_opcion":{"o3":"Es al revés: siempre hay daños que se pueden evitar."}}}]},{"slug":"comunidad-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: del yo al nosotros","bajada_es":"Bienes comunes, contagio social, proyectos, comunicación y esperanza, mezclados.","minutos":8,"pasos":[{"slug":"comunidad-1.s6.p1","orden":1,"grupo":"comunidad-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Del yo al nosotros». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"comunidad-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la plaza abandonada","bajada_es":"Un grupo de vecinos quiere recuperar la plaza de la cuadra. Armá con ellos el proyecto completo.","minutos":10,"pasos":[{"slug":"comunidad-1.s7.p1","orden":1,"grupo":"comunidad-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La plaza","cuerpo":["La plaza del barrio tiene los canteros secos, basura acumulada en una esquina, dos bancos rotos y ningún árbol nuevo desde hace años. Un grupo de cinco vecinos quiere recuperarla. En la cuadra hay una escuela, un club de barrio, una ferretería y un centro de jubilados. El municipio tiene un vivero de nativas.","Algunos vecinos dicen que \"no tiene sentido, la van a romper de nuevo\"."]},"solucion":{}},{"slug":"comunidad-1.s7.p2","orden":2,"grupo":"comunidad-1.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el mejor primer paso?","opciones":[{"id":"o1","texto":"Hacer un diagnóstico con los vecinos y la escuela"},{"id":"o2","texto":"Plantar árboles el sábado sin hablar con nadie"},{"id":"o3","texto":"Pedirle al municipio que lo haga todo"},{"id":"o4","texto":"Poner rejas alrededor de la plaza"}]},"solucion":{"clave":["o1"],"explicacion":"Entender qué pasa y qué quiere la gente hace que el proyecto sea de todos, y que lo cuiden.","por_opcion":{"o3":"El municipio es un aliado clave, pero sin diagnóstico ni participación el proyecto es frágil."}}},{"slug":"comunidad-1.s7.p3","orden":3,"grupo":"comunidad-1.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el objetivo más adecuado para empezar?","opciones":[{"id":"o1","texto":"Limpiar la esquina y plantar 10 nativas"},{"id":"o2","texto":"Que el barrio sea el más lindo de la ciudad"},{"id":"o3","texto":"Que nadie vuelva a tirar basura nunca"},{"id":"o4","texto":"Cambiar la mentalidad de todos los vecinos"}]},"solucion":{"clave":["o1"],"explicacion":"Concreto, medible y alcanzable: así se arranca y se puede mostrar un logro.","por_opcion":{"o3":"Es deseable, pero no se puede medir ni garantizar al empezar."}}},{"slug":"comunidad-1.s7.p4","orden":4,"grupo":"comunidad-1.s7.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Asigná cada aliado a lo que puede aportar.","grupos":[{"id":"g1","nombre":"Plantines y permisos"},{"id":"g2","nombre":"Personas y difusión"},{"id":"g3","nombre":"Herramientas"}],"items":[{"id":"i1","texto":"Vivero municipal"},{"id":"i2","texto":"Escuela"},{"id":"i3","texto":"Ferretería"},{"id":"i4","texto":"Municipio"},{"id":"i5","texto":"Club de barrio"},{"id":"i6","texto":"Centro de jubilados"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g2"},"explicacion":"Cada aliado aporta una pieza. El mapa de aliados convierte un grupo de cinco en un barrio."}},{"slug":"comunidad-1.s7.p5","orden":5,"grupo":"comunidad-1.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que los vecinos cuiden la plaza después? Marcá todo.","opciones":[{"id":"o1","texto":"Que participen en decidir y en plantar"},{"id":"o2","texto":"Carteles con los nombres de quienes plantaron cada árbol"},{"id":"o3","texto":"Turnos de riego compartidos"},{"id":"o4","texto":"Contar los avances en el grupo del barrio"},{"id":"o5","texto":"Hacerlo en secreto para que sea una sorpresa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo que la gente ayudó a construir, lo cuida. La participación es la mejor protección."}},{"slug":"comunidad-1.s7.p6","orden":6,"grupo":"comunidad-1.s7.p6","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un vecino escribe el mensaje de convocatoria. Marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"Este sábado a las 10 recuperamos juntos la plaza."},{"id":"s2","texto":"Si no venís, después no te quejes de la basura."},{"id":"s3","texto":"Ya se sumaron la escuela y el club."},{"id":"s4","texto":"Total, seguro la rompen otra vez."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Invitar en positivo, mostrar que otros ya se sumaron y evitar la culpa.","por_opcion":{"s2":"Culpar aleja: mejor invitar en positivo.","s4":"El mensaje derrotista desanima antes de empezar."}}},{"slug":"comunidad-1.s7.p7","orden":7,"grupo":"comunidad-1.s7.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Plantaron 10 nativas y a los seis meses sobreviven 8. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"8 ÷ 10 × 100 = 80 %. Contarlo en el grupo del barrio muestra resultados y suma gente para la próxima etapa."}},{"slug":"comunidad-1.s7.p7.v2","orden":7,"grupo":"comunidad-1.s7.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Plantaron 20 nativas y a los seis meses sobreviven 17. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1.7,"explicacion":"17 ÷ 20 × 100 = 85 %. Contarlo en el grupo del barrio muestra resultados y suma gente para la próxima etapa."}},{"slug":"comunidad-1.s7.p7.v3","orden":7,"grupo":"comunidad-1.s7.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Plantaron 15 nativas y a los seis meses sobreviven 12. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"12 ÷ 15 × 100 = 80 %. Contarlo en el grupo del barrio muestra resultados y suma gente para la próxima etapa."}},{"slug":"comunidad-1.s7.p8","orden":8,"grupo":"comunidad-1.s7.p8","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el proyecto completo.","items":[{"id":"i1","texto":"Reunión con vecinos y escuela para el diagnóstico"},{"id":"i2","texto":"Acordar el objetivo: limpiar la esquina y plantar 10 nativas"},{"id":"i3","texto":"Conseguir plantines, permisos y herramientas"},{"id":"i4","texto":"Jornada de limpieza y plantación"},{"id":"i5","texto":"Turnos de riego y medición de la supervivencia"},{"id":"i6","texto":"Contar los resultados y planear la segunda etapa"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Del diagnóstico a la segunda etapa: un proyecto que puede crecer."}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"comunidad-2","rama":"comunidad","orden":2,"nivel":1,"titulo_es":"Derechos y participación ambiental","bajada_es":"Tenés derecho a un ambiente sano, a saber qué pasa con él y a participar en las decisiones. Qué dicen la Constitución y las leyes, y cómo usarlas.","objetivos_es":["Explicar el derecho a un ambiente sano del artículo 41 de la Constitución Nacional","Reconocer los principios de la Ley General del Ambiente","Ejercer el derecho de acceso a la información pública ambiental","Identificar las formas de participación ciudadana en decisiones ambientales","Relacionar la educación ambiental y los ODS con la acción local"],"repasa":["comunidad-1","tronco-3"],"requiere_tronco":1,"fuentes":["ley-25675-ambiente","ley-25831-info","escazu","ley-27621-eai","onu-ods","unesco-ods","acumar"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"comunidad-2.s1","orden":1,"tipo":"leccion","titulo_es":"El derecho a un ambiente sano","bajada_es":"Qué dice el artículo 41 de la Constitución, qué significa y qué deberes trae.","minutos":11,"pasos":[{"slug":"comunidad-2.s1.p1","orden":1,"grupo":"comunidad-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El artículo 41","cuerpo":["Desde la reforma de 1994, la Constitución Nacional reconoce en su artículo 41 que todos los habitantes gozan del derecho a un ambiente sano, equilibrado, apto para el desarrollo humano y para que las actividades productivas satisfagan las necesidades presentes sin comprometer las de las generaciones futuras. Y agrega que tienen el deber de preservarlo.","También establece que el daño ambiental genera, prioritariamente, la obligación de recomponer: es decir, de reparar el ambiente dañado, no solo de pagar."],"destacado":{"valor":"Art. 41","texto":"de la Constitución Nacional reconoce el derecho a un ambiente sano y el deber de preservarlo."}},"solucion":{}},{"slug":"comunidad-2.s1.p2","orden":2,"grupo":"comunidad-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué establece el artículo 41 de la Constitución? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"El derecho de todos a un ambiente sano"},{"id":"o2","texto":"El deber de preservarlo"},{"id":"o3","texto":"Que no se comprometa a las generaciones futuras"},{"id":"o4","texto":"Que el daño ambiental obliga prioritariamente a recomponer"},{"id":"o5","texto":"Que solo los dueños de tierras tienen derechos ambientales"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un derecho de todos, con deberes, que piensa en el futuro y prioriza reparar."}},{"slug":"comunidad-2.s1.p3","orden":3,"grupo":"comunidad-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Derechos y deberes","cuerpo":["El derecho a un ambiente sano no es solo algo que se reclama: viene con el deber de cuidarlo. Además, la Constitución obliga a las autoridades a proteger ese derecho, a usar racionalmente los recursos, a preservar el patrimonio natural y cultural y la diversidad biológica, y a informar y educar.","La Nación dicta los \"presupuestos mínimos\" de protección ambiental, que valen en todo el país, y las provincias pueden complementarlos con normas más exigentes."]},"solucion":{}},{"slug":"comunidad-2.s1.p4","orden":4,"grupo":"comunidad-2.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un derecho o un deber que surge del artículo 41?","grupos":[{"id":"g1","nombre":"Derecho"},{"id":"g2","nombre":"Deber"}],"items":[{"id":"i1","texto":"Vivir en un ambiente sano"},{"id":"i2","texto":"Preservar el ambiente"},{"id":"i3","texto":"Recibir información ambiental"},{"id":"i4","texto":"No comprometer a las generaciones futuras"},{"id":"i5","texto":"Que se recomponga un daño ambiental"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Derechos y deberes van juntos. Nadie tiene derecho a dañar el ambiente de todos."}},{"slug":"comunidad-2.s1.p5","orden":5,"grupo":"comunidad-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El derecho a un ambiente sano solo protege a las personas que viven hoy.","razones":[{"id":"r1","texto":"Porque menciona explícitamente a las generaciones futuras"},{"id":"r2","texto":"Porque la Constitución no habla del ambiente"},{"id":"r3","texto":"Porque solo protege a los adultos"}]},"solucion":{"valor":false,"explicacion":"El artículo 41 habla explícitamente de no comprometer las necesidades de las generaciones futuras.","clave":["r1"]}},{"slug":"comunidad-2.s1.p6","orden":6,"grupo":"comunidad-2.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una fábrica contamina un arroyo. Según el artículo 41, ¿qué corresponde en primer lugar?","opciones":[{"id":"o1","texto":"Recomponer el ambiente dañado"},{"id":"o2","texto":"Pagar una multa y seguir igual"},{"id":"o3","texto":"Mudar a los vecinos a otro barrio"},{"id":"o4","texto":"Nada, porque la fábrica da trabajo"}]},"solucion":{"clave":["o1"],"explicacion":"Recomponer es la prioridad: devolver el ambiente a su estado anterior en lo posible.","por_opcion":{"o3":"La obligación prioritaria es reparar el daño, no trasladar el problema."}}},{"slug":"comunidad-2.s1.p7","orden":7,"grupo":"comunidad-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Presupuestos mínimos","cuerpo":["Las leyes de presupuestos mínimos fijan una protección básica común para todo el país: por ejemplo, la Ley General del Ambiente, la de bosques nativos, la de glaciares, la de residuos domiciliarios. Las provincias y los municipios no pueden proteger menos, pero sí pueden proteger más."]},"solucion":{}},{"slug":"comunidad-2.s1.p8","orden":8,"grupo":"comunidad-2.s1.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ley de presupuestos mínimos con su tema.","izquierda":[{"id":"a1","texto":"Ley 25.675"},{"id":"a2","texto":"Ley 26.331"},{"id":"a3","texto":"Ley 26.639"},{"id":"a4","texto":"Ley 25.916"}],"derecha":[{"id":"b1","texto":"Ley General del Ambiente"},{"id":"b2","texto":"Bosques nativos"},{"id":"b3","texto":"Glaciares y ambiente periglacial"},{"id":"b4","texto":"Residuos domiciliarios"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Leyes que ya viste en otras ramas, unidas por la misma lógica: un piso común para todo el país."}},{"slug":"comunidad-2.s1.p9","orden":9,"grupo":"comunidad-2.s1.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo funcionan los presupuestos mínimos.","items":[{"id":"i1","texto":"La Nación dicta una ley de presupuestos mínimos"},{"id":"i2","texto":"Fija una protección básica para todo el país"},{"id":"i3","texto":"Una provincia puede dictar normas más exigentes"},{"id":"i4","texto":"Nunca puede proteger menos que el piso nacional"},{"id":"i5","texto":"Cada provincia puede ignorar la ley nacional"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un piso común y la posibilidad de subir la vara según cada lugar."}},{"slug":"comunidad-2.s1.p10","orden":10,"grupo":"comunidad-2.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Constitución reconoce el derecho a un ambiente sano desde 1994."},{"id":"s2","texto":"Ese derecho no trae ningún deber para los habitantes."},{"id":"s3","texto":"El daño ambiental obliga prioritariamente a recomponer."},{"id":"s4","texto":"Una provincia puede proteger menos que la ley nacional de presupuestos mínimos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer bien el marco legal es la base para ejercer los derechos.","por_opcion":{"s2":"El artículo 41 establece también el deber de preservar el ambiente.","s4":"Puede proteger más, pero nunca menos que el piso nacional."}}},{"slug":"comunidad-2.s1.p11","orden":11,"grupo":"comunidad-2.s1.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El artículo {{0}} de la Constitución reconoce el derecho a un ambiente sano; el daño ambiental obliga prioritariamente a {{1}}.","banco":[{"id":"w1","texto":"41"},{"id":"w2","texto":"recomponer"},{"id":"w3","texto":"14"},{"id":"w4","texto":"indemnizar"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Las dos ideas centrales del artículo 41, en una línea."}},{"slug":"comunidad-2.s1.p12","orden":12,"grupo":"comunidad-2.s1.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año se incorporó el derecho a un ambiente sano a la Constitución Nacional.","min":1853,"max":2024,"paso":1,"unidad":"año","escala":"lineal"},"solucion":{"valor":1994,"banda":"lineal","explicacion":"En la reforma de 1994, con el artículo 41. Desde entonces es un derecho de rango constitucional."}},{"slug":"comunidad-2.s1.p13","orden":13,"grupo":"comunidad-2.s1.p13","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas normas de mayor a menor jerarquía.","items":[{"id":"i1","texto":"Constitución Nacional (art. 41)"},{"id":"i2","texto":"Ley nacional de presupuestos mínimos"},{"id":"i3","texto":"Ley provincial ambiental"},{"id":"i4","texto":"Ordenanza municipal"}],"extremos":["Mayor jerarquía","Menor jerarquía"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada nivel respeta al de arriba y puede sumar protección para su territorio.","valores":{"i1":"la de mayor jerarquía","i2":"aplica en todo el país","i3":"complementa en la provincia","i4":"aplica en el municipio"}}}]},{"slug":"comunidad-2.s2","orden":2,"tipo":"leccion","titulo_es":"La Ley General del Ambiente","bajada_es":"Los principios de la Ley 25.675, la evaluación de impacto ambiental y la participación ciudadana.","minutos":11,"pasos":[{"slug":"comunidad-2.s2.p1","orden":1,"grupo":"comunidad-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una ley marco","cuerpo":["La Ley 25.675, General del Ambiente, sancionada en 2002, es la ley marco de la política ambiental argentina. Establece objetivos, principios, instrumentos de gestión (como la evaluación de impacto ambiental), la participación ciudadana, el acceso a la información y reglas sobre el daño ambiental."]},"solucion":{}},{"slug":"comunidad-2.s2.p2","orden":2,"grupo":"comunidad-2.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los principios","cuerpo":["La ley fija principios que guían la interpretación de las normas ambientales. Entre ellos: el principio preventivo (atender las causas de los problemas antes de que ocurran); el precautorio (cuando hay peligro de daño grave o irreversible, la falta de certeza científica no puede usarse como excusa para no actuar); la equidad intergeneracional (cuidar el ambiente para las generaciones futuras); la progresividad (metas graduales); la responsabilidad (quien daña, se hace cargo); y la solidaridad y la cooperación entre jurisdicciones."],"lista":["Preventivo","Precautorio","Equidad intergeneracional","Progresividad","Responsabilidad","Solidaridad y cooperación"]},"solucion":{}},{"slug":"comunidad-2.s2.p3","orden":3,"grupo":"comunidad-2.s2.p3","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada principio con su significado.","izquierda":[{"id":"a1","texto":"Preventivo"},{"id":"a2","texto":"Precautorio"},{"id":"a3","texto":"Equidad intergeneracional"},{"id":"a4","texto":"Responsabilidad"}],"derecha":[{"id":"b1","texto":"Atender las causas antes de que ocurra el daño"},{"id":"b2","texto":"La falta de certeza no justifica no actuar ante un daño grave"},{"id":"b3","texto":"Cuidar el ambiente para las próximas generaciones"},{"id":"b4","texto":"Quien causa un daño se hace cargo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro principios que se usan en fallos judiciales y decisiones de gobierno."}},{"slug":"comunidad-2.s2.p4","orden":4,"grupo":"comunidad-2.s2.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Hay indicios de que un químico podría causar un daño grave e irreversible, pero la ciencia todavía no tiene certeza. Según el principio precautorio, ¿qué corresponde?","opciones":[{"id":"o1","texto":"Tomar medidas de protección aunque falte certeza"},{"id":"o2","texto":"Esperar a tener certeza total antes de hacer nada"},{"id":"o3","texto":"Usarlo más para ver qué pasa"},{"id":"o4","texto":"Dejar que cada persona decida si lo usa"}]},"solucion":{"clave":["o1"],"explicacion":"La falta de certeza no puede ser excusa para no proteger ante un posible daño grave o irreversible.","por_opcion":{"o3":"Probar \"en el terreno\" un posible daño irreversible es justo lo que el principio busca evitar."}}},{"slug":"comunidad-2.s2.p5","orden":5,"grupo":"comunidad-2.s2.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Según el principio precautorio, si no hay certeza científica absoluta de un daño, no se puede hacer nada.","razones":[{"id":"r1","texto":"Porque el principio dice que la falta de certeza no justifica no actuar"},{"id":"r2","texto":"Porque la ley prohíbe actuar sin certeza"},{"id":"r3","texto":"Porque la ciencia siempre tiene certeza absoluta"}]},"solucion":{"valor":false,"explicacion":"Es al revés: cuando hay peligro de daño grave o irreversible, la falta de certeza no puede usarse como razón para no tomar medidas.","clave":["r1"]}},{"slug":"comunidad-2.s2.p6","orden":6,"grupo":"comunidad-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Evaluación de impacto ambiental","cuerpo":["La ley establece que toda obra o actividad que pueda degradar el ambiente o afectar la calidad de vida de la población de forma significativa debe pasar por un procedimiento de evaluación de impacto ambiental (EIA) antes de hacerse. En ese proceso se analizan los impactos, se proponen medidas para evitarlos o reducirlos y la autoridad decide si la aprueba.","La ley también prevé instancias de consulta o audiencias públicas, sobre todo en proyectos con impactos importantes."]},"solucion":{}},{"slug":"comunidad-2.s2.p7","orden":7,"grupo":"comunidad-2.s2.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas típicas de una evaluación de impacto ambiental.","items":[{"id":"i1","texto":"La empresa presenta el proyecto"},{"id":"i2","texto":"Se elabora un estudio de impacto ambiental"},{"id":"i3","texto":"Se abre una instancia de participación ciudadana"},{"id":"i4","texto":"La autoridad evalúa y decide"},{"id":"i5","texto":"Si se aprueba, se controla que se cumplan las condiciones"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Evaluar antes de construir, con participación y con control después."}},{"slug":"comunidad-2.s2.p8","orden":8,"grupo":"comunidad-2.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta obra probablemente necesita evaluación de impacto ambiental o no?","grupos":[{"id":"g1","nombre":"Probablemente sí"},{"id":"g2","nombre":"Probablemente no"}],"items":[{"id":"i1","texto":"Un relleno sanitario nuevo"},{"id":"i2","texto":"Pintar la fachada de una casa"},{"id":"i3","texto":"Una fábrica junto a un río"},{"id":"i4","texto":"Plantar un árbol en la vereda"},{"id":"i5","texto":"Un barrio sobre un humedal"},{"id":"i6","texto":"Cambiar las lámparas de una escuela"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La evaluación se exige a lo que puede degradar el ambiente de forma significativa."}},{"slug":"comunidad-2.s2.p9","orden":9,"grupo":"comunidad-2.s2.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué evaluar antes de construir es preventivo.","items":[{"id":"i1","texto":"Se evalúa el impacto antes de construir"},{"id":"i2","texto":"Se detectan riesgos para un humedal"},{"id":"i3","texto":"Se cambia el diseño o la ubicación del proyecto"},{"id":"i4","texto":"Se evita un daño que después costaría mucho reparar"},{"id":"i5","texto":"Evaluar después de construir es igual de efectivo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Prevenir es más barato y efectivo que reparar: el principio preventivo en acción."}},{"slug":"comunidad-2.s2.p10","orden":10,"grupo":"comunidad-2.s2.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué incluye la Ley General del Ambiente? Marcá todo.","opciones":[{"id":"o1","texto":"Principios de política ambiental"},{"id":"o2","texto":"La evaluación de impacto ambiental"},{"id":"o3","texto":"La participación ciudadana"},{"id":"o4","texto":"El acceso a la información ambiental"},{"id":"o5","texto":"La prohibición de toda actividad productiva"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Es una ley marco para compatibilizar el desarrollo con el cuidado del ambiente, no para prohibir producir."}},{"slug":"comunidad-2.s2.p11","orden":11,"grupo":"comunidad-2.s2.p11","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué principio de la Ley General del Ambiente aplica cada decisión?","grupos":[{"id":"g1","nombre":"Preventivo"},{"id":"g2","nombre":"Precautorio"},{"id":"g3","nombre":"Responsabilidad"}],"items":[{"id":"i1","texto":"Exigir filtros antes de habilitar una fábrica"},{"id":"i2","texto":"Suspender un químico con indicios de daño grave aunque falten estudios"},{"id":"i3","texto":"Obligar a quien contaminó a limpiar el arroyo"},{"id":"i4","texto":"Evaluar el impacto antes de construir"},{"id":"i5","texto":"Frenar un desmonte ante un posible daño irreversible sin certeza total"},{"id":"i6","texto":"Que la empresa pague la recomposición del suelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres principios distintos que muchas veces se aplican juntos."}},{"slug":"comunidad-2.s2.p12","orden":12,"grupo":"comunidad-2.s2.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año se sancionó la Ley General del Ambiente (25.675).","min":1950,"max":2024,"paso":1,"unidad":"año","escala":"lineal"},"solucion":{"valor":2002,"banda":"lineal","explicacion":"En 2002. Ocho años después de que la reforma constitucional incorporara el artículo 41."}},{"slug":"comunidad-2.s2.p13","orden":13,"grupo":"comunidad-2.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Ley 25.675 es la Ley General del Ambiente."},{"id":"s2","texto":"La evaluación de impacto ambiental se hace después de construir la obra."},{"id":"s3","texto":"La ley incluye el principio de equidad intergeneracional."},{"id":"s4","texto":"El principio precautorio exige certeza absoluta antes de proteger."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los principios de la ley se aplican en decisiones y fallos concretos.","por_opcion":{"s2":"Se hace antes, para prevenir daños.","s4":"Dice lo contrario: la falta de certeza no justifica no actuar ante un daño grave."}}},{"slug":"comunidad-2.s2.p14","orden":14,"grupo":"comunidad-2.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley {{0}} es la Ley General del Ambiente; su principio {{1}} dice que la falta de certeza no justifica no actuar ante un daño grave.","banco":[{"id":"w1","texto":"25.675"},{"id":"w2","texto":"precautorio"},{"id":"w3","texto":"26.331"},{"id":"w4","texto":"progresivo"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La ley marco y uno de sus principios más importantes."}}]},{"slug":"comunidad-2.s3","orden":3,"tipo":"leccion","titulo_es":"Tu derecho a saber","bajada_es":"Cómo pedir información pública ambiental con la Ley 25.831, y qué agrega el Acuerdo de Escazú.","minutos":11,"pasos":[{"slug":"comunidad-2.s3.p1","orden":1,"grupo":"comunidad-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Ley 25.831","cuerpo":["La Ley 25.831, de Régimen de Libre Acceso a la Información Pública Ambiental, garantiza que cualquier persona puede pedir información ambiental que tengan los organismos públicos y las empresas de servicios públicos. No hace falta explicar para qué se pide ni demostrar un interés especial, y el acceso es gratuito, salvo los costos de copia.","La autoridad tiene un plazo máximo de 30 días hábiles para responder. Solo puede negarse en casos específicos, por ejemplo, si la información afecta la defensa nacional o secretos comerciales protegidos, y debe fundamentar la negativa."],"destacado":{"valor":"30 días hábiles","texto":"es el plazo máximo para responder un pedido de información pública ambiental, según la Ley 25.831."}},"solucion":{}},{"slug":"comunidad-2.s3.p2","orden":2,"grupo":"comunidad-2.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué garantiza la Ley 25.831? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Que cualquier persona puede pedir información ambiental"},{"id":"o2","texto":"Que no hace falta explicar para qué se pide"},{"id":"o3","texto":"Que es gratuita, salvo costos de copia"},{"id":"o4","texto":"Un plazo máximo de 30 días hábiles para responder"},{"id":"o5","texto":"Que solo pueden pedirla los abogados"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un derecho amplio y simple: cualquiera puede pedir, sin justificar, y con un plazo definido."}},{"slug":"comunidad-2.s3.p3","orden":3,"grupo":"comunidad-2.s3.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para pedir información ambiental hay que demostrar que uno está afectado por el problema.","razones":[{"id":"r1","texto":"Porque la ley no exige acreditar interés"},{"id":"r2","texto":"Porque solo pueden pedir los afectados directos"},{"id":"r3","texto":"Porque la información ambiental es secreta"}]},"solucion":{"valor":false,"explicacion":"La ley establece que no hace falta acreditar ningún interés especial: cualquier persona puede pedir información ambiental.","clave":["r1"]}},{"slug":"comunidad-2.s3.p4","orden":4,"grupo":"comunidad-2.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo hacer un buen pedido","cuerpo":["Un buen pedido de información es claro y concreto: dice qué información se busca, de qué lugar y período, y en qué formato se prefiere recibir. Por ejemplo: \"Solicito los resultados de los análisis de calidad del agua del arroyo X realizados en los últimos dos años, en formato digital\".","Conviene guardar una copia con la fecha de presentación, para poder reclamar si no hay respuesta en el plazo."]},"solucion":{}},{"slug":"comunidad-2.s3.p5","orden":5,"grupo":"comunidad-2.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el pedido de información mejor formulado?","opciones":[{"id":"o1","texto":"Análisis del agua del arroyo X de 2023 y 2024, en digital"},{"id":"o2","texto":"Quiero saber todo lo que pasa con el ambiente del municipio"},{"id":"o3","texto":"¿Por qué el arroyo del barrio está tan sucio y quién tiene la culpa?"},{"id":"o4","texto":"Necesito que me digan si hay contaminación en algún lugar de la ciudad"}]},"solucion":{"clave":["o1"],"explicacion":"Qué, dónde, cuándo y en qué formato: así es más fácil responder y más difícil evadir.","por_opcion":{"o3":"Es una pregunta legítima, pero un pedido de información funciona mejor pidiendo documentos o datos concretos."}}},{"slug":"comunidad-2.s3.p6","orden":6,"grupo":"comunidad-2.s3.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para pedir información ambiental.","items":[{"id":"i1","texto":"Identificar qué información necesitás y quién la tiene"},{"id":"i2","texto":"Redactar un pedido claro y concreto"},{"id":"i3","texto":"Presentarlo y guardar copia con fecha"},{"id":"i4","texto":"Esperar la respuesta dentro de los 30 días hábiles"},{"id":"i5","texto":"Si no responden, reclamar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un procedimiento simple que cualquier persona o escuela puede usar."}},{"slug":"comunidad-2.s3.p7","orden":7,"grupo":"comunidad-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Acuerdo de Escazú","cuerpo":["El Acuerdo de Escazú es un tratado de América Latina y el Caribe sobre el acceso a la información, la participación pública y el acceso a la justicia en asuntos ambientales. Argentina lo aprobó por la Ley 27.566 en 2020, y entró en vigor en 2021.","Es el primer tratado del mundo que incluye disposiciones específicas para proteger a las personas defensoras de derechos humanos en asuntos ambientales, que en la región sufren amenazas y ataques."]},"solucion":{}},{"slug":"comunidad-2.s3.p8","orden":8,"grupo":"comunidad-2.s3.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada norma con lo que establece.","izquierda":[{"id":"a1","texto":"Ley 25.831"},{"id":"a2","texto":"Acuerdo de Escazú (Ley 27.566)"},{"id":"a3","texto":"Ley 25.675"},{"id":"a4","texto":"Artículo 41 de la Constitución"}],"derecha":[{"id":"b1","texto":"Acceso a la información pública ambiental"},{"id":"b2","texto":"Información, participación, justicia y protección de defensores"},{"id":"b3","texto":"Principios e instrumentos de la política ambiental"},{"id":"b4","texto":"Derecho a un ambiente sano"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un sistema de normas que se complementan."}},{"slug":"comunidad-2.s3.p9","orden":9,"grupo":"comunidad-2.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué derecho de acceso ejerce cada persona?","grupos":[{"id":"g1","nombre":"Acceso a la información"},{"id":"g2","nombre":"Participación"},{"id":"g3","nombre":"Acceso a la justicia"}],"items":[{"id":"i1","texto":"Pedir los análisis de agua de un arroyo"},{"id":"i2","texto":"Hablar en una audiencia pública"},{"id":"i3","texto":"Presentar un amparo ambiental"},{"id":"i4","texto":"Consultar el estudio de impacto de una obra"},{"id":"i5","texto":"Enviar observaciones a una consulta"},{"id":"i6","texto":"Denunciar un daño ambiental ante un juez"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Los tres pilares del Acuerdo de Escazú: saber, participar y reclamar."}},{"slug":"comunidad-2.s3.p10","orden":10,"grupo":"comunidad-2.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Presentaste un pedido el lunes 3 de marzo. Si no hay feriados, ¿cuántas semanas laborales de 5 días son los 30 días hábiles de plazo?","unidad":"semanas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, unos 42 días corridos si no hay feriados. Anotar la fecha límite ayuda a reclamar a tiempo."}},{"slug":"comunidad-2.s3.p10.v2","orden":10,"grupo":"comunidad-2.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Presentaste un pedido el martes 1 de abril. Si no hay feriados, ¿cuántas semanas laborales de 5 días son los 30 días hábiles de plazo?","unidad":"semanas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, unos 42 días corridos si no hay feriados. Anotar la fecha límite ayuda a reclamar a tiempo."}},{"slug":"comunidad-2.s3.p10.v3","orden":10,"grupo":"comunidad-2.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Presentaste un pedido el jueves 5 de junio. Si no hay feriados, ¿cuántas semanas laborales de 5 días son los 30 días hábiles de plazo?","unidad":"semanas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, unos 42 días corridos si no hay feriados. Anotar la fecha límite ayuda a reclamar a tiempo."}},{"slug":"comunidad-2.s3.p11","orden":11,"grupo":"comunidad-2.s3.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El acceso a la información pública ambiental es gratuito, salvo los costos de copia.","razones":[{"id":"r1","texto":"Porque la ley lo establece así"},{"id":"r2","texto":"Porque hay que pagar una tasa por cada pregunta"},{"id":"r3","texto":"Porque solo es gratis para empresas"}]},"solucion":{"valor":true,"explicacion":"Así lo establece la Ley 25.831: el derecho no puede depender de pagar, más allá de los costos de reproducción.","clave":["r1"]}},{"slug":"comunidad-2.s3.p12","orden":12,"grupo":"comunidad-2.s3.p12","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta negativa a dar información es legítima o no?","grupos":[{"id":"g1","nombre":"Puede ser legítima (si se fundamenta)"},{"id":"g2","nombre":"No es legítima"}],"items":[{"id":"i1","texto":"La información afecta la defensa nacional"},{"id":"i2","texto":"El funcionario no tiene ganas de buscarla"},{"id":"i3","texto":"Es un secreto comercial protegido por la ley"},{"id":"i4","texto":"La persona no explicó para qué la quiere"},{"id":"i5","texto":"Los datos muestran que hay contaminación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Las excepciones son pocas y deben fundamentarse. Que los datos sean incómodos no es una razón válida."}},{"slug":"comunidad-2.s3.p13","orden":13,"grupo":"comunidad-2.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Cualquier persona puede pedir información ambiental."},{"id":"s2","texto":"Si pedís información, tenés que explicar por qué la querés."},{"id":"s3","texto":"El plazo máximo de respuesta es de 30 días hábiles."},{"id":"s4","texto":"El Acuerdo de Escazú no tiene nada que ver con Argentina."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer tus derechos de acceso es el primer paso para usarlos.","por_opcion":{"s2":"La Ley 25.831 no exige justificar el pedido.","s4":"Argentina lo aprobó por la Ley 27.566 en 2020."}}},{"slug":"comunidad-2.s3.p14","orden":14,"grupo":"comunidad-2.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley {{0}} garantiza el acceso a la información ambiental, con un plazo de {{1}} días hábiles; el Acuerdo de {{2}} protege además a las personas defensoras del ambiente.","banco":[{"id":"w1","texto":"25.831"},{"id":"w2","texto":"30"},{"id":"w3","texto":"Escazú"},{"id":"w4","texto":"25.916"},{"id":"w5","texto":"90"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las normas que sostienen el derecho a saber y a defender el ambiente."}}]},{"slug":"comunidad-2.s4","orden":4,"tipo":"leccion","titulo_es":"Participar en las decisiones","bajada_es":"Audiencias públicas, concejos deliberantes, presupuestos participativos y amparos: las herramientas para intervenir.","minutos":11,"pasos":[{"slug":"comunidad-2.s4.p1","orden":1,"grupo":"comunidad-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchas puertas","cuerpo":["Hay muchas formas de participar en decisiones ambientales: las audiencias públicas y consultas sobre proyectos con impacto; las bancas o sesiones abiertas de los concejos deliberantes; los presupuestos participativos, donde los vecinos proponen y votan proyectos; los consejos consultivos; y, cuando un derecho ambiental se vulnera, la vía judicial."]},"solucion":{}},{"slug":"comunidad-2.s4.p2","orden":2,"grupo":"comunidad-2.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que permite.","izquierda":[{"id":"a1","texto":"Audiencia pública"},{"id":"a2","texto":"Presupuesto participativo"},{"id":"a3","texto":"Concejo deliberante"},{"id":"a4","texto":"Amparo ambiental"}],"derecha":[{"id":"b1","texto":"Opinar sobre un proyecto antes de que se decida"},{"id":"b2","texto":"Proponer y votar obras para el barrio"},{"id":"b3","texto":"Presentar proyectos de ordenanza o hablar en sesiones abiertas"},{"id":"b4","texto":"Pedir a un juez que frene un daño ambiental"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro puertas distintas. Elegir la adecuada depende del problema y del momento."}},{"slug":"comunidad-2.s4.p3","orden":3,"grupo":"comunidad-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La audiencia pública","cuerpo":["En una audiencia pública, cualquier persona interesada puede inscribirse y expresar su opinión sobre un proyecto antes de que la autoridad decida. Las opiniones no son vinculantes —la autoridad no está obligada a hacer lo que se dice—, pero sí debe considerarlas y explicar cómo las tuvo en cuenta.","Participar bien implica leer el proyecto, preparar argumentos con datos y proponer alternativas."]},"solucion":{}},{"slug":"comunidad-2.s4.p4","orden":4,"grupo":"comunidad-2.s4.p4","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En una audiencia pública, la autoridad está obligada a hacer lo que diga la mayoría de los participantes.","razones":[{"id":"r1","texto":"Porque las opiniones no son vinculantes, aunque deben considerarse"},{"id":"r2","texto":"Porque en las audiencias no se puede hablar"},{"id":"r3","texto":"Porque las audiencias se hacen después de decidir"}]},"solucion":{"valor":false,"explicacion":"Las opiniones no son vinculantes, pero la autoridad debe considerarlas y fundamentar su decisión. Por eso importa participar con buenos argumentos.","clave":["r1"]}},{"slug":"comunidad-2.s4.p5","orden":5,"grupo":"comunidad-2.s4.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo prepararse para hablar en una audiencia pública.","items":[{"id":"i1","texto":"Inscribirse en el plazo indicado"},{"id":"i2","texto":"Leer el proyecto y el estudio de impacto"},{"id":"i3","texto":"Buscar datos y preparar argumentos"},{"id":"i4","texto":"Proponer alternativas concretas"},{"id":"i5","texto":"Exponer con claridad en el tiempo asignado"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una buena participación se prepara: datos, argumentos y propuestas."}},{"slug":"comunidad-2.s4.p6","orden":6,"grupo":"comunidad-2.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El amparo ambiental","cuerpo":["El artículo 43 de la Constitución permite presentar una acción de amparo, un proceso judicial rápido, contra actos u omisiones que lesionen derechos como el de un ambiente sano. En los casos ambientales, puede presentarla la persona afectada, el Defensor del Pueblo y las asociaciones que protegen el ambiente.","Uno de los casos más conocidos es la causa Mendoza, por la contaminación del Riachuelo, en la que la Corte Suprema ordenó en 2008 recomponer la cuenca, como viste en la rama de Agua."]},"solucion":{}},{"slug":"comunidad-2.s4.p7","orden":7,"grupo":"comunidad-2.s4.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa empieza a rellenar un humedal sin evaluación de impacto ambiental. ¿Qué herramienta permite pedir a un juez que lo frene rápido?","opciones":[{"id":"o1","texto":"Una acción de amparo ambiental"},{"id":"o2","texto":"Un presupuesto participativo"},{"id":"o3","texto":"Una encuesta en redes sociales"},{"id":"o4","texto":"Esperar a las próximas elecciones"}]},"solucion":{"clave":["o1"],"explicacion":"El amparo es la vía judicial rápida para proteger un derecho que se está vulnerando.","por_opcion":{"o3":"Puede servir para difundir, pero no tiene efecto legal para frenar la obra."}}},{"slug":"comunidad-2.s4.p8","orden":8,"grupo":"comunidad-2.s4.p8","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué herramienta conviene para cada situación?","grupos":[{"id":"g1","nombre":"Presupuesto participativo"},{"id":"g2","nombre":"Audiencia pública"},{"id":"g3","nombre":"Amparo ambiental"}],"items":[{"id":"i1","texto":"Proponer una huerta comunitaria en la plaza"},{"id":"i2","texto":"Opinar sobre un relleno sanitario proyectado"},{"id":"i3","texto":"Frenar un relleno ilegal de un humedal"},{"id":"i4","texto":"Pedir bicicleteros en el centro del barrio"},{"id":"i5","texto":"Dar argumentos sobre una obra en la costa del río"},{"id":"i6","texto":"Exigir que se deje de volcar un efluente tóxico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada situación pide su herramienta: proponer, opinar o reclamar ante la justicia."}},{"slug":"comunidad-2.s4.p9","orden":9,"grupo":"comunidad-2.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una propuesta vecinal puede volverse ordenanza.","items":[{"id":"i1","texto":"Los vecinos detectan un problema y arman una propuesta"},{"id":"i2","texto":"Juntan firmas y apoyos"},{"id":"i3","texto":"Presentan la propuesta en el concejo deliberante"},{"id":"i4","texto":"Un concejal la toma y la presenta como proyecto"},{"id":"i5","texto":"Se debate y se vota"},{"id":"i6","texto":"La propuesta se aprueba sola al presentarla"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las ordenanzas también nacen en los barrios, cuando la propuesta está bien armada y tiene apoyo."}},{"slug":"comunidad-2.s4.p10","orden":10,"grupo":"comunidad-2.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más efectiva la participación ciudadana? Marcá todo.","opciones":[{"id":"o1","texto":"Informarse antes de opinar"},{"id":"o2","texto":"Presentar datos y argumentos"},{"id":"o3","texto":"Proponer alternativas concretas"},{"id":"o4","texto":"Sumar a otras organizaciones"},{"id":"o5","texto":"Insultar a los funcionarios"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Argumentos, propuestas y alianzas: la participación que cambia decisiones."}},{"slug":"comunidad-2.s4.p11","orden":11,"grupo":"comunidad-2.s4.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Quiénes pueden presentar un amparo ambiental según el artículo 43 de la Constitución? Marcá todos.","opciones":[{"id":"o1","texto":"La persona afectada"},{"id":"o2","texto":"El Defensor del Pueblo"},{"id":"o3","texto":"Asociaciones que protegen el ambiente"},{"id":"o4","texto":"Solo el intendente del municipio"},{"id":"o5","texto":"Solo las empresas del lugar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La Constitución abre la puerta a los afectados, al Defensor del Pueblo y a las asociaciones ambientales."}},{"slug":"comunidad-2.s4.p12","orden":12,"grupo":"comunidad-2.s4.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un presupuesto participativo, ¿qué propuesta suele tener más chances de ser elegida y concretada?","opciones":[{"id":"o1","texto":"Una concreta, con costo estimado y apoyos"},{"id":"o2","texto":"Una idea general de mejorar todo el barrio"},{"id":"o3","texto":"La más cara posible, para que se note"},{"id":"o4","texto":"Una presentada el último día sin detalles"}]},"solucion":{"clave":["o1"],"explicacion":"Las propuestas concretas, factibles y con apoyo vecinal son las que más avanzan.","por_opcion":{"o3":"Un costo muy alto suele dejarla fuera del presupuesto disponible."}}},{"slug":"comunidad-2.s4.p13","orden":13,"grupo":"comunidad-2.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje en un grupo vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Hay una audiencia pública sobre el nuevo relleno; inscribámonos."},{"id":"s2","texto":"No sirve ir, porque la audiencia no decide nada."},{"id":"s3","texto":"Podemos llevar datos sobre la napa y proponer otra ubicación."},{"id":"s4","texto":"Solo los abogados pueden presentar un amparo ambiental."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer las herramientas evita resignarse antes de tiempo.","por_opcion":{"s2":"Las opiniones deben ser consideradas y fundamentadas; además quedan registradas y pueden servir después.","s4":"Pueden presentarlo los afectados, el Defensor del Pueblo y asociaciones ambientales, con patrocinio letrado."}}},{"slug":"comunidad-2.s4.p14","orden":14,"grupo":"comunidad-2.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En una audiencia {{0}} cualquiera puede opinar sobre un proyecto; para frenar rápido un daño se puede presentar un {{1}} ambiental.","banco":[{"id":"w1","texto":"pública"},{"id":"w2","texto":"amparo"},{"id":"w3","texto":"privada"},{"id":"w4","texto":"reclamo"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos herramientas de participación, en una sola línea."}}]},{"slug":"comunidad-2.s5","orden":5,"tipo":"leccion","titulo_es":"Educar y conectar con el mundo","bajada_es":"La Ley de Educación Ambiental Integral y los Objetivos de Desarrollo Sostenible: del aula y el barrio a la agenda global.","minutos":9,"pasos":[{"slug":"comunidad-2.s5.p1","orden":1,"grupo":"comunidad-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Educación Ambiental Integral","cuerpo":["En 2021 se sancionó la Ley 27.621 de Educación Ambiental Integral, que establece que la educación ambiental es un derecho y debe estar presente en todos los niveles y modalidades de la educación, de forma transversal, y también en espacios no formales.","La educación ambiental integral no es solo aprender datos: busca comprender los sistemas, valorar la diversidad, pensar críticamente y participar."]},"solucion":{}},{"slug":"comunidad-2.s5.p2","orden":2,"grupo":"comunidad-2.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué busca la educación ambiental integral? Marcá todo.","opciones":[{"id":"o1","texto":"Comprender cómo funcionan los sistemas naturales y sociales"},{"id":"o2","texto":"Pensar críticamente"},{"id":"o3","texto":"Participar en la comunidad"},{"id":"o4","texto":"Valorar la diversidad biológica y cultural"},{"id":"o5","texto":"Memorizar datos sin relacionarlos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La educación ambiental integral forma para entender y actuar, no solo para repetir."}},{"slug":"comunidad-2.s5.p3","orden":3,"grupo":"comunidad-2.s5.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La Ley 27.621 establece que la educación ambiental debe estar solo en la materia de biología.","razones":[{"id":"r1","texto":"Porque establece un enfoque transversal en toda la educación"},{"id":"r2","texto":"Porque la ley prohíbe hablar de ambiente en otras materias"},{"id":"r3","texto":"Porque solo aplica a las universidades"}]},"solucion":{"valor":false,"explicacion":"Establece que debe ser transversal: estar presente en todos los niveles, modalidades y áreas, además de en espacios no formales.","clave":["r1"]}},{"slug":"comunidad-2.s5.p4","orden":4,"grupo":"comunidad-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los Objetivos de Desarrollo Sostenible","cuerpo":["En 2015, los países de las Naciones Unidas acordaron la Agenda 2030 con 17 Objetivos de Desarrollo Sostenible (ODS). Incluyen terminar con la pobreza y el hambre, salud, educación, igualdad de género, agua y saneamiento, energía asequible y no contaminante, ciudades sostenibles, producción y consumo responsables, acción por el clima, vida submarina y vida de ecosistemas terrestres, entre otros.","Los ODS muestran que lo ambiental, lo social y lo económico están conectados: no se puede resolver uno ignorando los otros."],"destacado":{"valor":"17 ODS","texto":"forman la Agenda 2030 acordada por los países de las Naciones Unidas en 2015."}},"solucion":{}},{"slug":"comunidad-2.s5.p5","orden":5,"grupo":"comunidad-2.s5.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ODS con un tema que ya viste en el árbol.","izquierda":[{"id":"a1","texto":"ODS 6: Agua limpia y saneamiento"},{"id":"a2","texto":"ODS 7: Energía asequible y no contaminante"},{"id":"a3","texto":"ODS 12: Producción y consumo responsables"},{"id":"a4","texto":"ODS 13: Acción por el clima"}],"derecha":[{"id":"b1","texto":"Rama de Agua"},{"id":"b2","texto":"Rama de Energía"},{"id":"b3","texto":"Ramas de Consumo y Residuos"},{"id":"b4","texto":"El tronco y todas las ramas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El árbol de la Academia y la Agenda 2030 hablan de lo mismo desde lugares distintos."}},{"slug":"comunidad-2.s5.p6","orden":6,"grupo":"comunidad-2.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un proyecto de barrio se conecta con los ODS.","items":[{"id":"i1","texto":"Una escuela arma una huerta con compost"},{"id":"i2","texto":"Reduce los residuos orgánicos que van al relleno"},{"id":"i3","texto":"Produce alimentos y enseña a cultivarlos"},{"id":"i4","texto":"Aporta a los ODS de consumo responsable, hambre cero y educación"},{"id":"i5","texto":"La huerta cumple sola toda la Agenda 2030"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo local suma a lo global. Los ODS sirven para ver esas conexiones."}},{"slug":"comunidad-2.s5.p7","orden":7,"grupo":"comunidad-2.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué ODS aporta más directamente cada acción?","grupos":[{"id":"g1","nombre":"ODS 6 (agua)"},{"id":"g2","nombre":"ODS 11 (ciudades)"},{"id":"g3","nombre":"ODS 15 (vida terrestre)"}],"items":[{"id":"i1","texto":"Reparar las pérdidas de agua de la escuela"},{"id":"i2","texto":"Sumar ciclovías y veredas seguras"},{"id":"i3","texto":"Plantar nativas"},{"id":"i4","texto":"Monitorear la calidad de un arroyo"},{"id":"i5","texto":"Recuperar una plaza abandonada"},{"id":"i6","texto":"Proteger un bosque nativo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Muchas acciones aportan a varios ODS a la vez: esa es la idea de su integración."}},{"slug":"comunidad-2.s5.p8","orden":8,"grupo":"comunidad-2.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué muestra que los 17 ODS se pensaron juntos?","opciones":[{"id":"o1","texto":"Que ambiente, sociedad y economía se conectan"},{"id":"o2","texto":"Que cada país elige un solo objetivo"},{"id":"o3","texto":"Que el ambiente importa más que la pobreza"},{"id":"o4","texto":"Que son 17 temas separados sin relación"}]},"solucion":{"clave":["o1"],"explicacion":"Por ejemplo, el acceso a agua segura mejora la salud, la educación y la igualdad de género al mismo tiempo.","por_opcion":{"o3":"Los ODS los ponen en el mismo nivel: se refuerzan entre sí."}}},{"slug":"comunidad-2.s5.p9","orden":9,"grupo":"comunidad-2.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Agenda 2030 se acordó en 2015. Si estamos en 2025, ¿cuántos años quedan para su meta de 2030?","unidad":"años","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"2030 − 2025 = 5 años. Pocos años para metas muy ambiciosas: por eso importa cada acción, desde lo local."}},{"slug":"comunidad-2.s5.p9.v2","orden":9,"grupo":"comunidad-2.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Agenda 2030 se acordó en 2015. Si estamos en 2026, ¿cuántos años quedan para su meta de 2030?","unidad":"años","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"2030 − 2026 = 4 años. Pocos años para metas muy ambiciosas: por eso importa cada acción, desde lo local."}},{"slug":"comunidad-2.s5.p9.v3","orden":9,"grupo":"comunidad-2.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Agenda 2030 se acordó en 2015. Si estamos en 2027, ¿cuántos años quedan para su meta de 2030?","unidad":"años","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"2030 − 2027 = 3 años. Pocos años para metas muy ambiciosas: por eso importa cada acción, desde lo local."}},{"slug":"comunidad-2.s5.p10","orden":10,"grupo":"comunidad-2.s5.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta presentación escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los ODS son 17 y forman la Agenda 2030."},{"id":"s2","texto":"Los ODS solo hablan del ambiente, no de la pobreza."},{"id":"s3","texto":"La Ley 27.621 hace de la educación ambiental un derecho."},{"id":"s4","texto":"La educación ambiental es solo para la escuela secundaria."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Educación ambiental y ODS: dos marcos que conectan el aula y el barrio con el mundo.","por_opcion":{"s2":"Incluyen pobreza, hambre, salud, educación, igualdad y más.","s4":"Debe estar en todos los niveles y también en espacios no formales."}}},{"slug":"comunidad-2.s5.p11","orden":11,"grupo":"comunidad-2.s5.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley {{0}} es de Educación Ambiental Integral; la Agenda 2030 tiene {{1}} Objetivos de Desarrollo Sostenible.","banco":[{"id":"w1","texto":"27.621"},{"id":"w2","texto":"17"},{"id":"w3","texto":"25.675"},{"id":"w4","texto":"10"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos marcos que conectan la educación con la acción global."}},{"slug":"comunidad-2.s5.p12","orden":12,"grupo":"comunidad-2.s5.p12","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos alcances del más local al más global.","items":[{"id":"i1","texto":"Proyecto de huerta de la escuela"},{"id":"i2","texto":"Ordenanza municipal de arbolado"},{"id":"i3","texto":"Ley nacional de educación ambiental"},{"id":"i4","texto":"Agenda 2030 de las Naciones Unidas"}],"extremos":["Más local","Más global"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Distintas escalas que se conectan: lo que se hace en el barrio suma a las metas globales.","valores":{"i1":"barrio","i2":"ciudad","i3":"país","i4":"mundo"}}}]},{"slug":"comunidad-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: derechos y participación ambiental","bajada_es":"Constitución, Ley General del Ambiente, acceso a la información, participación y educación, mezclados.","minutos":8,"pasos":[{"slug":"comunidad-2.s6.p1","orden":1,"grupo":"comunidad-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Derechos y participación ambiental». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"comunidad-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el pedido del arroyo","bajada_es":"Un curso quiere saber si el arroyo junto a la escuela está contaminado. Usá tus derechos para averiguarlo y actuar.","minutos":10,"pasos":[{"slug":"comunidad-2.s7.p1","orden":1,"grupo":"comunidad-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Un curso de secundaria nota que el arroyo junto a la escuela tiene espuma y mal olor desde hace meses. Aguas arriba hay un parque industrial. El municipio no publica datos del arroyo. Los estudiantes quieren saber qué pasa y hacer algo.","Un vecino les dice que \"eso es cosa de abogados\" y que no les van a responder."]},"solucion":{}},{"slug":"comunidad-2.s7.p2","orden":2,"grupo":"comunidad-2.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el primer paso más útil?","opciones":[{"id":"o1","texto":"Pedir los análisis del arroyo por la Ley 25.831"},{"id":"o2","texto":"Presentar un amparo sin tener ningún dato"},{"id":"o3","texto":"Publicar en redes que la fábrica contamina"},{"id":"o4","texto":"Esperar a que el municipio publique algo solo"}]},"solucion":{"clave":["o1"],"explicacion":"Primero saber: la Ley 25.831 permite pedir los datos sin justificar el interés.","por_opcion":{"o3":"Sin datos, puede ser injusto y no resolver nada."}}},{"slug":"comunidad-2.s7.p3","orden":3,"grupo":"comunidad-2.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué pedido está mejor formulado?","opciones":[{"id":"o1","texto":"Análisis del agua de los últimos 2 años y permisos de vuelco"},{"id":"o2","texto":"Queremos saber todo sobre la contaminación de toda la ciudad"},{"id":"o3","texto":"¿La fábrica del parque industrial contamina el arroyo o no?"},{"id":"o4","texto":"Que nos digan si podemos bañarnos en el arroyo este verano"}]},"solucion":{"clave":["o1"],"explicacion":"Concreto: qué documentos, de qué lugar y de qué período.","por_opcion":{"o3":"Conviene pedir documentos y datos concretos, no opiniones."}}},{"slug":"comunidad-2.s7.p4","orden":4,"grupo":"comunidad-2.s7.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si presentan el pedido y el plazo máximo es de 30 días hábiles, ¿cuántas semanas laborales de 5 días tienen que esperar como máximo?","unidad":"semanas","decimales":0,"contexto":"Plazo de 30 días hábiles de la Ley 25.831."},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, sin contar feriados. Anotar la fecha límite permite reclamar a tiempo."}},{"slug":"comunidad-2.s7.p5","orden":5,"grupo":"comunidad-2.s7.p5","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el plan del curso.","items":[{"id":"i1","texto":"Pedir información pública ambiental con un pedido concreto"},{"id":"i2","texto":"Mientras tanto, registrar con fotos y fechas lo que observan"},{"id":"i3","texto":"Analizar la respuesta con un docente o especialista"},{"id":"i4","texto":"Si hay irregularidades, presentarlas en el concejo o en una audiencia"},{"id":"i5","texto":"Si hay un daño grave y no se actúa, evaluar un amparo con asesoramiento"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Saber, documentar, analizar, participar y, si hace falta, reclamar judicialmente."}},{"slug":"comunidad-2.s7.p6","orden":6,"grupo":"comunidad-2.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las afirmaciones del vecino y de los estudiantes.","grupos":[{"id":"g1","nombre":"Correcta"},{"id":"g2","nombre":"Incorrecta"}],"items":[{"id":"i1","texto":"Cualquier persona puede pedir información ambiental"},{"id":"i2","texto":"Eso es cosa de abogados"},{"id":"i3","texto":"No hace falta explicar para qué la piden"},{"id":"i4","texto":"Si no responden, no se puede hacer nada"},{"id":"i5","texto":"El amparo ambiental puede presentarlo quien se ve afectado"},{"id":"i6","texto":"Los menores no tienen derecho a un ambiente sano"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El derecho a un ambiente sano y a la información es de todas las personas."}},{"slug":"comunidad-2.s7.p7","orden":7,"grupo":"comunidad-2.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el municipio no responde en 30 días hábiles, los estudiantes pueden reclamar.","razones":[{"id":"r1","texto":"Porque la ley fija un plazo que debe cumplirse"},{"id":"r2","texto":"Porque la ley no fija ningún plazo"},{"id":"r3","texto":"Porque el municipio puede no responder nunca"}]},"solucion":{"valor":true,"explicacion":"La ley fija ese plazo; si no se cumple o la negativa no está fundamentada, se puede reclamar por vía administrativa o judicial.","clave":["r1"]}},{"slug":"comunidad-2.s7.p8","orden":8,"grupo":"comunidad-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El curso escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pedimos los análisis del arroyo con la Ley 25.831."},{"id":"s2","texto":"Mientras esperamos, publicamos que la fábrica X es culpable."},{"id":"s3","texto":"Registramos con fotos y fechas la espuma y el olor."},{"id":"s4","texto":"Si no responden, abandonamos porque no se puede hacer nada."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Usar los derechos con método: datos primero, participación después y reclamo si hace falta.","por_opcion":{"s2":"Sin datos, es una inferencia presentada como hecho: primero hay que saber.","s4":"Se puede reclamar el incumplimiento del plazo."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"comunidad-3","rama":"comunidad","orden":3,"nivel":2,"titulo_es":"Justicia ambiental","bajada_es":"Quién respira el peor aire, quién vive junto al basural, quién emite más y quién sufre más el clima: la desigualdad en el ambiente y cómo construir soluciones justas.","objetivos_es":["Explicar las dimensiones distributiva, procedimental y de reconocimiento de la justicia ambiental","Analizar el caso de la cuenca Matanza-Riachuelo y la causa Mendoza","Interpretar datos sobre desigualdad en las emisiones y en la vulnerabilidad climática","Reconocer los derechos de las generaciones futuras en la ley y la jurisprudencia","Proponer soluciones ambientales que no agraven desigualdades"],"repasa":["comunidad-2","comunidad-1","aire-suelo-1","consumo-4"],"requiere_tronco":2,"fuentes":["acumar","acumar-causa-mendoza","oxfam-clima-2023","cij-clima-2025","ley-25675-ambiente","escazu","acuerdo-paris","oms-aire-exterior"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"comunidad-3.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es la justicia ambiental","bajada_es":"Daños y beneficios que no se reparten por igual, decisiones que no incluyen a todos y voces que no se escuchan.","minutos":11,"pasos":[{"slug":"comunidad-3.s1.p1","orden":1,"grupo":"comunidad-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una idea que nace en los barrios","cuerpo":["En 1982, en el condado de Warren, en Estados Unidos, vecinos de una comunidad mayormente afroamericana protestaron contra un relleno de residuos tóxicos que se instalaba cerca de sus casas. Esa lucha dio visibilidad a una pregunta: ¿por qué las industrias contaminantes, los basurales y los depósitos de residuos se instalan con más frecuencia cerca de barrios pobres o discriminados? Así se fue formando la idea de justicia ambiental."]},"solucion":{}},{"slug":"comunidad-3.s1.p2","orden":2,"grupo":"comunidad-3.s1.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres dimensiones","cuerpo":["La justicia ambiental tiene tres dimensiones. Distributiva: quién recibe los daños (contaminación, riesgos, residuos) y quién los beneficios (plazas, árboles, agua segura). Procedimental: quién participa en las decisiones y con qué información. Y de reconocimiento: quién es tenido en cuenta y respetado, con sus saberes, su cultura y su forma de vida."],"lista":["Distributiva · quién recibe daños y beneficios","Procedimental · quién participa en las decisiones","Reconocimiento · quién es tenido en cuenta y respetado"]},"solucion":{}},{"slug":"comunidad-3.s1.p3","orden":3,"grupo":"comunidad-3.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué dimensión de la justicia ambiental está en juego?","grupos":[{"id":"g1","nombre":"Distributiva"},{"id":"g2","nombre":"Procedimental"},{"id":"g3","nombre":"Reconocimiento"}],"items":[{"id":"i1","texto":"Un barrio tiene diez veces menos árboles que otro"},{"id":"i2","texto":"La audiencia pública se hace en horario laboral y lejos del barrio afectado"},{"id":"i3","texto":"No se consideran los saberes de una comunidad indígena sobre su territorio"},{"id":"i4","texto":"El basural se instala siempre junto a los barrios pobres"},{"id":"i5","texto":"La información del proyecto no se publica"},{"id":"i6","texto":"Se trata a los vecinos como si no entendieran el problema"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Una injusticia ambiental suele combinar las tres dimensiones a la vez."}},{"slug":"comunidad-3.s1.p4","orden":4,"grupo":"comunidad-3.s1.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una planta de tratamiento de residuos se instala junto a un barrio sin que nadie le consulte. ¿Qué dimensiones de la justicia ambiental se ven afectadas?","opciones":[{"id":"o1","texto":"La distributiva y la procedimental"},{"id":"o2","texto":"Solo la de reconocimiento, nada más"},{"id":"o3","texto":"Ninguna, porque la planta es necesaria"},{"id":"o4","texto":"Solo la económica"}]},"solucion":{"clave":["o1"],"explicacion":"Recibe el daño (distributiva) y no participó de la decisión (procedimental).","por_opcion":{"o3":"Que sea necesaria no justifica dónde ni cómo se decide."}}},{"slug":"comunidad-3.s1.p5","orden":5,"grupo":"comunidad-3.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Beneficios también desiguales","cuerpo":["La injusticia no está solo en los daños. También los beneficios ambientales se reparten de forma desigual: en muchas ciudades, los barrios de mayores ingresos tienen más arbolado, más plazas, mejor acceso al agua segura y a la red cloacal, y menos inundaciones. Lo viste con el verde urbano: la sombra de los árboles y el acceso a espacios verdes también son parte del ambiente."]},"solucion":{}},{"slug":"comunidad-3.s1.p6","orden":6,"grupo":"comunidad-3.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 12 m² de espacio verde por habitante y otro 2 m². ¿Cuántas veces más espacio verde por habitante tiene el primero?","unidad":"veces","decimales":0,"contexto":"12 m² frente a 2 m² por habitante."},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"12 ÷ 2 = 6 veces. Una diferencia así afecta la salud, el calor y la calidad de vida de cada barrio."}},{"slug":"comunidad-3.s1.p6.v2","orden":6,"grupo":"comunidad-3.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 9 m² de espacio verde por habitante y otro 1,5 m². ¿Cuántas veces más espacio verde por habitante tiene el primero?","unidad":"veces","decimales":0,"contexto":"9 m² frente a 1.5 m² por habitante."},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"9 ÷ 1,5 = 6 veces. Una diferencia así afecta la salud, el calor y la calidad de vida de cada barrio."}},{"slug":"comunidad-3.s1.p6.v3","orden":6,"grupo":"comunidad-3.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 15 m² de espacio verde por habitante y otro 3 m². ¿Cuántas veces más espacio verde por habitante tiene el primero?","unidad":"veces","decimales":0,"contexto":"15 m² frente a 3 m² por habitante."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"15 ÷ 3 = 5 veces. Una diferencia así afecta la salud, el calor y la calidad de vida de cada barrio."}},{"slug":"comunidad-3.s1.p7","orden":7,"grupo":"comunidad-3.s1.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se refuerza una injusticia ambiental.","items":[{"id":"i1","texto":"Un barrio tiene menos poder político y económico"},{"id":"i2","texto":"Se instalan allí actividades contaminantes"},{"id":"i3","texto":"Bajan los precios de las viviendas"},{"id":"i4","texto":"Llegan familias con menos recursos para mudarse"},{"id":"i5","texto":"El barrio queda con aún menos poder para oponerse"},{"id":"i6","texto":"El barrio gana poder por tener más industrias"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las desigualdades sociales y ambientales se alimentan entre sí."}},{"slug":"comunidad-3.s1.p8","orden":8,"grupo":"comunidad-3.s1.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La contaminación afecta a todas las personas por igual, sin importar dónde viven.","razones":[{"id":"r1","texto":"Porque la exposición depende de dónde se vive y de los recursos"},{"id":"r2","texto":"Porque la contaminación no existe"},{"id":"r3","texto":"Porque solo afecta a los barrios ricos"}]},"solucion":{"valor":false,"explicacion":"Quienes viven junto a industrias, avenidas, basurales o ríos contaminados reciben mucha más exposición. Y suelen tener menos recursos para protegerse o mudarse.","clave":["r1"]}},{"slug":"comunidad-3.s1.p9","orden":9,"grupo":"comunidad-3.s1.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada dimensión con la pregunta que plantea.","izquierda":[{"id":"a1","texto":"Distributiva"},{"id":"a2","texto":"Procedimental"},{"id":"a3","texto":"Reconocimiento"}],"derecha":[{"id":"b1","texto":"¿Quién recibe los daños y quién los beneficios?"},{"id":"b2","texto":"¿Quién participa en las decisiones?"},{"id":"b3","texto":"¿Quién es escuchado y respetado?"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Tres preguntas para analizar cualquier conflicto ambiental."}},{"slug":"comunidad-3.s1.p10","orden":10,"grupo":"comunidad-3.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué situaciones son ejemplos de injusticia ambiental? Marcá todas.","opciones":[{"id":"o1","texto":"El agua segura llega a unos barrios y a otros no"},{"id":"o2","texto":"Una audiencia pública se hace sin traducción para una comunidad indígena"},{"id":"o3","texto":"Los barrios sin árboles sufren más las olas de calor"},{"id":"o4","texto":"Todos los barrios tienen las mismas plazas y el mismo aire"},{"id":"o5","texto":"La información del proyecto se publica y se explica a tiempo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La justicia ambiental mira el reparto, el proceso y el respeto."}},{"slug":"comunidad-3.s1.p11","orden":11,"grupo":"comunidad-3.s1.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas formas de decidir dónde ubicar una planta de residuos, de la más justa a la menos justa.","items":[{"id":"i1","texto":"Evaluar todas las opciones con datos y participación de todos los barrios"},{"id":"i2","texto":"Evaluar opciones con datos técnicos, sin participación"},{"id":"i3","texto":"Elegir el terreno más barato sin mirar quién vive cerca"},{"id":"i4","texto":"Elegir el barrio con menos capacidad de protestar"}],"extremos":["Más justa","Menos justa"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La justicia está en el criterio y en el proceso, no solo en el resultado.","valores":{"i1":"la más justa","i2":"incompleta","i3":"injusta","i4":"la más injusta"}}},{"slug":"comunidad-3.s1.p12","orden":12,"grupo":"comunidad-3.s1.p12","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un barrio acepta una industria contaminante a cambio de empleo, ya no hay ninguna injusticia ambiental.","razones":[{"id":"r1","texto":"Porque aceptar por necesidad no borra la desigualdad"},{"id":"r2","texto":"Porque el empleo siempre es malo"},{"id":"r3","texto":"Porque las industrias nunca contaminan"}]},"solucion":{"valor":false,"explicacion":"Aceptar bajo necesidad económica, sin información completa ni alternativas, no borra la desigualdad. La justicia pide información, alternativas y controles reales.","clave":["r1"]}},{"slug":"comunidad-3.s1.p13","orden":13,"grupo":"comunidad-3.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La justicia ambiental mira quién recibe los daños y los beneficios."},{"id":"s2","texto":"Si una decisión es técnicamente buena, no importa quién participó."},{"id":"s3","texto":"Los espacios verdes también se reparten de forma desigual."},{"id":"s4","texto":"Las injusticias ambientales se corrigen solas con el tiempo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La justicia ambiental no es un tema aparte: atraviesa todas las decisiones ambientales.","por_opcion":{"s2":"La dimensión procedimental importa: participar es un derecho.","s4":"Suelen reforzarse si nadie actúa."}}},{"slug":"comunidad-3.s1.p14","orden":14,"grupo":"comunidad-3.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Quién recibe los daños y los beneficios es la dimensión {{0}}; quién participa en las decisiones es la {{1}}; y quién es escuchado y respetado es la de {{2}}.","banco":[{"id":"w1","texto":"distributiva"},{"id":"w2","texto":"procedimental"},{"id":"w3","texto":"reconocimiento"},{"id":"w4","texto":"económica"},{"id":"w5","texto":"técnica"},{"id":"w6","texto":"ventas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres dimensiones de la justicia ambiental."}}]},{"slug":"comunidad-3.s2","orden":2,"tipo":"leccion","titulo_es":"Junto al río más contaminado","bajada_es":"La cuenca Matanza-Riachuelo, la causa Mendoza y lo que se logró y falta lograr.","minutos":11,"pasos":[{"slug":"comunidad-3.s2.p1","orden":1,"grupo":"comunidad-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cuenca","cuerpo":["La cuenca Matanza-Riachuelo atraviesa parte de la Ciudad de Buenos Aires y varios municipios del conurbano bonaerense, donde viven millones de personas. Durante más de un siglo recibió desechos de curtiembres, frigoríficos, industrias químicas y cloacas sin tratar, y en sus orillas se formaron asentamientos y basurales. Muchas de las familias más pobres de la región viven justamente en las zonas más expuestas."]},"solucion":{}},{"slug":"comunidad-3.s2.p2","orden":2,"grupo":"comunidad-3.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La causa Mendoza","cuerpo":["En 2004, un grupo de vecinos, encabezado por Beatriz Mendoza, demandó al Estado nacional, a la provincia de Buenos Aires, a la Ciudad y a empresas por los daños causados por la contaminación de la cuenca. En 2006 se creó por ley la Autoridad de Cuenca Matanza Riachuelo (ACUMAR). En 2008, la Corte Suprema dictó un fallo histórico: ordenó un plan de saneamiento con tres objetivos —mejorar la calidad de vida de la población, recomponer el ambiente y prevenir daños futuros— y fijó un sistema de control del cumplimiento."]},"solucion":{}},{"slug":"comunidad-3.s2.p3","orden":3,"grupo":"comunidad-3.s2.p3","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los hechos de la causa Mendoza.","items":[{"id":"i1","texto":"Vecinos de la cuenca presentan una demanda por la contaminación"},{"id":"i2","texto":"Se crea por ley la Autoridad de Cuenca Matanza Riachuelo"},{"id":"i3","texto":"La Corte Suprema ordena un plan de saneamiento"},{"id":"i4","texto":"Se ejecutan y controlan obras y relocalizaciones"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una demanda de vecinos llegó a la Corte y cambió la política ambiental de la región."}},{"slug":"comunidad-3.s2.p4","orden":4,"grupo":"comunidad-3.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada actor con su papel en la causa.","izquierda":[{"id":"a1","texto":"Vecinos de la cuenca"},{"id":"a2","texto":"Corte Suprema"},{"id":"a3","texto":"ACUMAR"},{"id":"a4","texto":"Empresas de la cuenca"}],"derecha":[{"id":"b1","texto":"Presentaron la demanda"},{"id":"b2","texto":"Ordenó el plan de saneamiento"},{"id":"b3","texto":"Coordina el saneamiento de la cuenca"},{"id":"b4","texto":"Deben adecuar sus vertidos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El caso muestra cómo distintos actores tienen responsabilidades distintas."}},{"slug":"comunidad-3.s2.p5","orden":5,"grupo":"comunidad-3.s2.p5","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué objetivos fijó la Corte para el plan de saneamiento? Marcá todos.","opciones":[{"id":"o1","texto":"Mejorar la calidad de vida de la población"},{"id":"o2","texto":"Recomponer el ambiente"},{"id":"o3","texto":"Prevenir daños futuros"},{"id":"o4","texto":"Trasladar todas las industrias a otro país"},{"id":"o5","texto":"Construir un nuevo puerto en el Riachuelo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los tres objetivos combinan salud, ambiente y prevención."}},{"slug":"comunidad-3.s2.p6","orden":6,"grupo":"comunidad-3.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Avances y deudas","cuerpo":["Desde el fallo hubo avances: se sacaron muchos cascos de barcos hundidos, se limpiaron márgenes, se cerraron basurales, se controlaron industrias, se relocalizaron familias que vivían en el borde del río y se construyeron grandes obras cloacales. Pero el río sigue contaminado, y muchas relocalizaciones y obras avanzaron más lento de lo previsto. El caso muestra que la justicia puede ordenar, pero sanear una cuenca lleva décadas y requiere continuidad."]},"solucion":{}},{"slug":"comunidad-3.s2.p7","orden":7,"grupo":"comunidad-3.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un avance o una deuda pendiente en la cuenca?","grupos":[{"id":"g1","nombre":"Avance"},{"id":"g2","nombre":"Deuda pendiente"}],"items":[{"id":"i1","texto":"Retiro de cascos de barcos hundidos"},{"id":"i2","texto":"El agua del río sigue contaminada"},{"id":"i3","texto":"Cierre de basurales a cielo abierto"},{"id":"i4","texto":"Relocalizaciones que avanzaron más lento de lo previsto"},{"id":"i5","texto":"Control de vertidos industriales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Un balance honesto reconoce lo logrado y lo que falta."}},{"slug":"comunidad-3.s2.p8","orden":8,"grupo":"comunidad-3.s2.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la contaminación del Riachuelo es una injusticia ambiental.","items":[{"id":"i1","texto":"Las industrias y cloacas contaminaron el río durante décadas"},{"id":"i2","texto":"Las tierras junto al río perdieron valor"},{"id":"i3","texto":"Allí se asentaron familias con menos recursos"},{"id":"i4","texto":"Esas familias quedaron más expuestas a la contaminación"},{"id":"i5","texto":"La salud de quienes menos tienen es la más afectada"},{"id":"i6","texto":"Las familias ricas se mudaron al borde del río"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Contaminación y pobreza se superponen en el territorio."}},{"slug":"comunidad-3.s2.p9","orden":9,"grupo":"comunidad-3.s2.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un fallo judicial alcanza para sanear un río en pocos años.","razones":[{"id":"r1","texto":"Porque sanear una cuenca requiere décadas de obras y control"},{"id":"r2","texto":"Porque los fallos judiciales no tienen efecto"},{"id":"r3","texto":"Porque el río se limpia solo en un año"}]},"solucion":{"valor":false,"explicacion":"El fallo fijó obligaciones y controles, pero sanear una cuenca requiere obras, recursos, control y continuidad durante décadas.","clave":["r1"]}},{"slug":"comunidad-3.s2.p10","orden":10,"grupo":"comunidad-3.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en 16 años se completó el 40 % de un plan de obras, y el ritmo se mantiene, ¿cuántos años más harían falta para completarlo? Redondeá al entero.","unidad":"años","decimales":0,"contexto":"40 % hecho en 16 años."},"solucion":{"valor":24,"tolerancia":1,"explicacion":"16 ÷ 40 × 60 ≈ 24 años más. Datos de ejemplo: muestran por qué el ritmo y la continuidad importan tanto."}},{"slug":"comunidad-3.s2.p10.v2","orden":10,"grupo":"comunidad-3.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en 10 años se completó el 25 % de un plan de obras, y el ritmo se mantiene, ¿cuántos años más harían falta para completarlo? Redondeá al entero.","unidad":"años","decimales":0,"contexto":"25 % hecho en 10 años."},"solucion":{"valor":30,"tolerancia":1,"explicacion":"10 ÷ 25 × 75 ≈ 30 años más. Datos de ejemplo: muestran por qué el ritmo y la continuidad importan tanto."}},{"slug":"comunidad-3.s2.p10.v3","orden":10,"grupo":"comunidad-3.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en 20 años se completó el 60 % de un plan de obras, y el ritmo se mantiene, ¿cuántos años más harían falta para completarlo? Redondeá al entero.","unidad":"años","decimales":0,"contexto":"60 % hecho en 20 años."},"solucion":{"valor":13,"tolerancia":1,"explicacion":"20 ÷ 60 × 40 ≈ 13 años más. Datos de ejemplo: muestran por qué el ritmo y la continuidad importan tanto."}},{"slug":"comunidad-3.s2.p11","orden":11,"grupo":"comunidad-3.s2.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año la Corte Suprema dictó el fallo que ordenó sanear la cuenca Matanza-Riachuelo.","min":1980,"max":2025,"paso":1,"unidad":"","escala":"lineal"},"solucion":{"valor":2008,"banda":"lineal","explicacion":"En 2008. La demanda había empezado en 2004 y ACUMAR se creó en 2006."}},{"slug":"comunidad-3.s2.p12","orden":12,"grupo":"comunidad-3.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué fue importante que la Corte fijara un sistema de control del cumplimiento?","opciones":[{"id":"o1","texto":"Para verificar que las órdenes se cumplan en el tiempo"},{"id":"o2","texto":"Para que el fallo pudiera cambiarse cada semana"},{"id":"o3","texto":"Para que las empresas no tuvieran que hacer nada"},{"id":"o4","texto":"Para cerrar la causa lo antes posible"}]},"solucion":{"clave":["o1"],"explicacion":"Un fallo sin seguimiento puede quedar en el papel. El control sostiene el cumplimiento durante años.","por_opcion":{"o3":"Al contrario: el control apunta a que todos cumplan."}}},{"slug":"comunidad-3.s2.p13","orden":13,"grupo":"comunidad-3.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La causa Mendoza empezó con una demanda de vecinos de la cuenca."},{"id":"s2","texto":"La Corte Suprema declaró que el río ya estaba limpio."},{"id":"s3","texto":"ACUMAR se creó por ley en 2006."},{"id":"s4","texto":"Las familias más expuestas eran las de mayores ingresos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El caso Riachuelo es uno de los más importantes del derecho ambiental argentino.","por_opcion":{"s2":"Ordenó un plan de saneamiento porque estaba contaminado.","s4":"Las más expuestas eran, en general, las de menores ingresos."}}},{"slug":"comunidad-3.s2.p14","orden":14,"grupo":"comunidad-3.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La demanda por la contaminación del Riachuelo se conoce como causa {{0}}; en 2008 la Corte {{1}} ordenó un plan de saneamiento; y el organismo que coordina el saneamiento es {{2}}.","banco":[{"id":"w1","texto":"Mendoza"},{"id":"w2","texto":"Suprema"},{"id":"w3","texto":"ACUMAR"},{"id":"w4","texto":"Riachuelo"},{"id":"w5","texto":"Interamericana"},{"id":"w6","texto":"INTA"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave del caso Matanza-Riachuelo."}}]},{"slug":"comunidad-3.s3","orden":3,"tipo":"leccion","titulo_es":"Clima y desigualdad","bajada_es":"Quién emite más y quién sufre más: la desigualdad en el cambio climático, entre personas y entre países.","minutos":11,"pasos":[{"slug":"comunidad-3.s3.p1","orden":1,"grupo":"comunidad-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién emite","cuerpo":["Según un estudio de Oxfam y el Instituto de Ambiente de Estocolmo, en 2019 el 10 % más rico de la población mundial fue responsable de la mitad de las emisiones de CO₂ asociadas al consumo. El 1 % más rico, de alrededor del 16 %: tanto como el 66 % más pobre. Y la mitad más pobre de la humanidad, unas 3.900 millones de personas, de apenas alrededor del 8 %."],"datos":{"tipo":"barras","titulo":"Parte de las emisiones de consumo en 2019, por grupo de ingresos","unidad":"%","filas":[{"etiqueta":"10 % más rico","valor":50},{"etiqueta":"1 % más rico","valor":16},{"etiqueta":"50 % más pobre","valor":8}],"nota":"Oxfam y SEI, Climate Equality (2023). El 1 % más rico está incluido dentro del 10 %."}},"solucion":{}},{"slug":"comunidad-3.s3.p2","orden":2,"grupo":"comunidad-3.s3.p2","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos grupos por su parte de las emisiones mundiales de consumo en 2019, de mayor a menor.","items":[{"id":"i1","texto":"10 % más rico"},{"id":"i2","texto":"1 % más rico"},{"id":"i3","texto":"50 % más pobre"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"La décima parte más rica emite más de seis veces lo que emite la mitad más pobre.","valores":{"i1":"≈ 50 %","i2":"≈ 16 %","i3":"≈ 8 %"}}},{"slug":"comunidad-3.s3.p3","orden":3,"grupo":"comunidad-3.s3.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el 10 % más rico emite el 50 % y el 50 % más pobre el 8 %, ¿cuántas veces más emite en promedio una persona del primer grupo que una del segundo? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"10 % emite 50 %; 50 % emite 8 %."},"solucion":{"valor":31.3,"tolerancia":0.1,"explicacion":"Por persona: 50 ÷ 10 = 5 contra 8 ÷ 50 = 0,16. Cociente: 31,3 veces."}},{"slug":"comunidad-3.s3.p3.v2","orden":3,"grupo":"comunidad-3.s3.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El 1 % más rico emite el 16 % de las emisiones y el 50 % más pobre el 8 %. ¿Cuántas veces más emite por persona el primer grupo? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"1 % emite 16 %; 50 % emite 8 %."},"solucion":{"valor":100,"tolerancia":0.1,"explicacion":"Por persona: 16 ÷ 1 = 16 contra 8 ÷ 50 = 0,16. Cociente: 100 veces."}},{"slug":"comunidad-3.s3.p3.v3","orden":3,"grupo":"comunidad-3.s3.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por persona, ¿cuántas veces más emite alguien del 10 % más rico (que emite el 50 %) que alguien del 50 % más pobre (que emite el 8 %)? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"10 % emite 50 %; 50 % emite 8 %."},"solucion":{"valor":31.3,"tolerancia":0.1,"explicacion":"Por persona: 50 ÷ 10 = 5 contra 8 ÷ 50 = 0,16. Cociente: 31,3 veces."}},{"slug":"comunidad-3.s3.p4","orden":4,"grupo":"comunidad-3.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién sufre","cuerpo":["La otra cara de la desigualdad es la vulnerabilidad. Las personas y los países con menos recursos suelen estar más expuestos a olas de calor, inundaciones y sequías, y tienen menos medios para protegerse y recuperarse: viviendas precarias, trabajos al aire libre, menos acceso a salud, a seguros o a aire acondicionado. Quienes menos contribuyeron al problema suelen sufrir más sus consecuencias."]},"solucion":{}},{"slug":"comunidad-3.s3.p5","orden":5,"grupo":"comunidad-3.s3.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una ola de calor golpea más a un barrio pobre.","items":[{"id":"i1","texto":"Las viviendas son precarias y con techos de chapa"},{"id":"i2","texto":"Hay pocos árboles y mucho cemento"},{"id":"i3","texto":"Las casas acumulan calor y no se enfrían de noche"},{"id":"i4","texto":"Hay menos acceso a ventiladores, agua fresca o atención médica"},{"id":"i5","texto":"Aumentan los problemas de salud en ese barrio"},{"id":"i6","texto":"Los techos de chapa enfrían las casas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Exposición, sensibilidad y falta de recursos se combinan en la vulnerabilidad."}},{"slug":"comunidad-3.s3.p6","orden":6,"grupo":"comunidad-3.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Entre países","cuerpo":["También hay desigualdad entre países. Los países que se industrializaron primero acumularon la mayor parte de las emisiones históricas, mientras que muchos países de ingresos bajos, que emitieron muy poco, están entre los más afectados. En las negociaciones climáticas se reconoce el principio de \"responsabilidades comunes pero diferenciadas\", y en 2022 se acordó crear un fondo para responder a pérdidas y daños en los países más vulnerables."]},"solucion":{}},{"slug":"comunidad-3.s3.p7","orden":7,"grupo":"comunidad-3.s3.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su significado.","izquierda":[{"id":"a1","texto":"Responsabilidades comunes pero diferenciadas"},{"id":"a2","texto":"Emisiones históricas"},{"id":"a3","texto":"Pérdidas y daños"},{"id":"a4","texto":"Vulnerabilidad"}],"derecha":[{"id":"b1","texto":"Todos deben actuar, pero no todos igual"},{"id":"b2","texto":"Todo lo emitido desde la industrialización"},{"id":"b3","texto":"Impactos climáticos que ya no se pueden evitar"},{"id":"b4","texto":"Qué tan expuesto y preparado está alguien frente a un impacto"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos que ordenan cualquier discusión sobre justicia climática."}},{"slug":"comunidad-3.s3.p8","orden":8,"grupo":"comunidad-3.s3.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los países que menos emitieron son los que menos sufren el cambio climático.","razones":[{"id":"r1","texto":"Porque muchos países de baja emisión son muy vulnerables"},{"id":"r2","texto":"Porque el clima solo cambia en los países ricos"},{"id":"r3","texto":"Porque emitir poco protege del calentamiento"}]},"solucion":{"valor":false,"explicacion":"Muchos de los países que menos emitieron están entre los más expuestos y con menos recursos para adaptarse.","clave":["r1"]}},{"slug":"comunidad-3.s3.p9","orden":9,"grupo":"comunidad-3.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa el principio de \"responsabilidades comunes pero diferenciadas\"?","opciones":[{"id":"o1","texto":"Todos deben actuar, según su responsabilidad y capacidad"},{"id":"o2","texto":"Solo los países pobres deben reducir emisiones"},{"id":"o3","texto":"Ningún país tiene responsabilidad"},{"id":"o4","texto":"Todos deben reducir exactamente lo mismo"}]},"solucion":{"clave":["o1"],"explicacion":"Es la base de la justicia climática entre países.","por_opcion":{"o3":"Todos la tienen; lo que cambia es cuánta y cómo."}}},{"slug":"comunidad-3.s3.p10","orden":10,"grupo":"comunidad-3.s3.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una cuestión de responsabilidad o de vulnerabilidad?","grupos":[{"id":"g1","nombre":"Responsabilidad"},{"id":"g2","nombre":"Vulnerabilidad"}],"items":[{"id":"i1","texto":"Cuánto emitió un país en su historia"},{"id":"i2","texto":"Viviendas en zonas inundables"},{"id":"i3","texto":"Cuánto emite en promedio una persona de altos ingresos"},{"id":"i4","texto":"Falta de sistemas de alerta"},{"id":"i5","texto":"Trabajo al aire libre sin protección del calor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"La justicia climática mira las dos columnas: quién causó y quién sufre."}},{"slug":"comunidad-3.s3.p11","orden":11,"grupo":"comunidad-3.s3.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más vulnerable a una familia frente a una inundación? Marcá todo.","opciones":[{"id":"o1","texto":"Vivir en una zona baja junto a un arroyo"},{"id":"o2","texto":"Tener una vivienda precaria"},{"id":"o3","texto":"No recibir alertas tempranas"},{"id":"o4","texto":"No tener ahorros para reparar daños"},{"id":"o5","texto":"Vivir en una zona alta con buenos desagües"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Exposición, fragilidad y falta de recursos se suman en la vulnerabilidad."}},{"slug":"comunidad-3.s3.p12","orden":12,"grupo":"comunidad-3.s3.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el 1 % más rico emite tanto, lo que haga el resto de la población no importa.","razones":[{"id":"r1","texto":"Porque todas las emisiones suman, aunque la responsabilidad sea distinta"},{"id":"r2","texto":"Porque el 1 % más rico no emite nada"},{"id":"r3","texto":"Porque solo importan las emisiones de los países"}]},"solucion":{"valor":false,"explicacion":"La responsabilidad es mayor donde se emite más, pero las emisiones del resto también suman. La justicia climática reparte esfuerzos según responsabilidad y capacidad, no exime a nadie.","clave":["r1"]}},{"slug":"comunidad-3.s3.p13","orden":13,"grupo":"comunidad-3.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El 10 % más rico emitió la mitad de las emisiones de consumo en 2019."},{"id":"s2","texto":"Todas las personas del mundo emiten más o menos lo mismo."},{"id":"s3","texto":"En 2022 se acordó crear un fondo para pérdidas y daños."},{"id":"s4","texto":"Los más pobres son los que más contribuyeron al cambio climático."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos de desigualdad cambian la conversación sobre quién tiene que hacer qué.","por_opcion":{"s2":"Hay enormes diferencias según el ingreso.","s4":"La mitad más pobre emitió alrededor del 8 %."}}},{"slug":"comunidad-3.s3.p14","orden":14,"grupo":"comunidad-3.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Según Oxfam, el 10 % más rico emitió alrededor del {{0}} % de las emisiones de consumo en 2019; la mitad más pobre, cerca del {{1}} %; y el fondo acordado en 2022 es para pérdidas y {{2}}.","banco":[{"id":"w1","texto":"50"},{"id":"w2","texto":"8"},{"id":"w3","texto":"daños"},{"id":"w4","texto":"10"},{"id":"w5","texto":"40"},{"id":"w6","texto":"ganancias"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave de la desigualdad climática."}}]},{"slug":"comunidad-3.s4","orden":4,"tipo":"leccion","titulo_es":"Las generaciones que vienen","bajada_es":"La justicia con quienes todavía no nacieron o no votan: la Constitución, los tribunales y las juventudes.","minutos":11,"pasos":[{"slug":"comunidad-3.s4.p1","orden":1,"grupo":"comunidad-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una promesa constitucional","cuerpo":["El artículo 41 de la Constitución Nacional establece el derecho a un ambiente sano para que las actividades productivas satisfagan las necesidades presentes \"sin comprometer las de las generaciones futuras\". Es la idea de equidad intergeneracional: las decisiones de hoy no deberían dejar a quienes vienen un planeta más pobre, más riesgoso o con menos opciones."]},"solucion":{}},{"slug":"comunidad-3.s4.p2","orden":2,"grupo":"comunidad-3.s4.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa la equidad intergeneracional?","opciones":[{"id":"o1","texto":"No comprometer las necesidades de las generaciones futuras"},{"id":"o2","texto":"Que las personas mayores decidan por los jóvenes"},{"id":"o3","texto":"Que cada generación use todo lo que pueda"},{"id":"o4","texto":"Que las leyes cambien cada generación"}]},"solucion":{"clave":["o1"],"explicacion":"Es un principio que la Constitución argentina incluye explícitamente.","por_opcion":{"o3":"Es lo contrario: cuidar lo que se deja a quienes vienen."}}},{"slug":"comunidad-3.s4.p3","orden":3,"grupo":"comunidad-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los tribunales y el clima","cuerpo":["En los últimos años, tribunales de distintos países tomaron decisiones sobre el clima y las generaciones futuras. En 2018, la Corte Suprema de Colombia, ante una demanda de jóvenes, reconoció a la Amazonia colombiana como sujeto de derechos y ordenó un plan contra la deforestación. En 2025, la Corte Internacional de Justicia emitió una opinión consultiva que afirma que los Estados tienen obligaciones jurídicas de proteger el sistema climático, y que incumplirlas puede generar responsabilidad internacional."]},"solucion":{}},{"slug":"comunidad-3.s4.p4","orden":4,"grupo":"comunidad-3.s4.p4","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada decisión con su contenido.","izquierda":[{"id":"a1","texto":"Corte Suprema de Colombia, 2018"},{"id":"a2","texto":"Corte Internacional de Justicia, 2025"},{"id":"a3","texto":"Corte Suprema argentina, 2008"},{"id":"a4","texto":"Constitución argentina, artículo 41"}],"derecha":[{"id":"b1","texto":"Reconoció a la Amazonia como sujeto de derechos"},{"id":"b2","texto":"Los Estados tienen obligaciones de proteger el clima"},{"id":"b3","texto":"Ordenó sanear la cuenca Matanza-Riachuelo"},{"id":"b4","texto":"Derecho a un ambiente sano y generaciones futuras"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El derecho ambiental se construye con leyes, constituciones y decisiones judiciales."}},{"slug":"comunidad-3.s4.p5","orden":5,"grupo":"comunidad-3.s4.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una opinión consultiva de la Corte Internacional de Justicia es un fallo contra un país específico.","razones":[{"id":"r1","texto":"Porque interpreta el derecho sin condenar a un país concreto"},{"id":"r2","texto":"Porque la Corte no puede opinar sobre el clima"},{"id":"r3","texto":"Porque es una ley que votan los países"}]},"solucion":{"valor":false,"explicacion":"Es una opinión sobre qué dice el derecho internacional, pedida en este caso por la Asamblea General de la ONU. No es una condena a un país, pero orienta cómo se interpretan las obligaciones de todos.","clave":["r1"]}},{"slug":"comunidad-3.s4.p6","orden":6,"grupo":"comunidad-3.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las juventudes","cuerpo":["Muchos de los reclamos climáticos de los últimos años fueron impulsados por jóvenes: huelgas escolares, demandas judiciales, participación en cumbres. Tiene sentido: son quienes van a vivir más tiempo con las consecuencias de las decisiones de hoy, y muchas veces todavía no pueden votar. La participación de las juventudes es una forma de dar voz a las generaciones futuras."]},"solucion":{}},{"slug":"comunidad-3.s4.p7","orden":7,"grupo":"comunidad-3.s4.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿De qué formas pueden participar los jóvenes en las decisiones ambientales? Marcá todas.","opciones":[{"id":"o1","texto":"Pedir información pública ambiental"},{"id":"o2","texto":"Participar en audiencias públicas y consejos juveniles"},{"id":"o3","texto":"Organizar proyectos en la escuela y el barrio"},{"id":"o4","texto":"Impulsar acciones judiciales con apoyo adecuado"},{"id":"o5","texto":"Ninguna, porque no pueden votar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo viste en la unidad de derechos: hay muchas herramientas de participación, y no todas requieren votar."}},{"slug":"comunidad-3.s4.p8","orden":8,"grupo":"comunidad-3.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona que nació en 2012, ¿cuántos años tendrá en 2100?","unidad":"años","decimales":0,"contexto":"Nacimiento 2012; año 2100."},"solucion":{"valor":88,"tolerancia":1.76,"explicacion":"2100 − 2012 = 88 años. Muchas personas que hoy son chicos vivirán el clima de fines de siglo que definen las decisiones de estas décadas."}},{"slug":"comunidad-3.s4.p8.v2","orden":8,"grupo":"comunidad-3.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona que nació en 2010, ¿cuántos años tendrá en 2090?","unidad":"años","decimales":0,"contexto":"Nacimiento 2010; año 2090."},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"2090 − 2010 = 80 años. Muchas personas que hoy son chicos vivirán el clima de fines de siglo que definen las decisiones de estas décadas."}},{"slug":"comunidad-3.s4.p8.v3","orden":8,"grupo":"comunidad-3.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona que nació en 2015, ¿cuántos años tendrá en 2100?","unidad":"años","decimales":0,"contexto":"Nacimiento 2015; año 2100."},"solucion":{"valor":85,"tolerancia":1.7,"explicacion":"2100 − 2015 = 85 años. Muchas personas que hoy son chicos vivirán el clima de fines de siglo que definen las decisiones de estas décadas."}},{"slug":"comunidad-3.s4.p9","orden":9,"grupo":"comunidad-3.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el clima es una cuestión entre generaciones.","items":[{"id":"i1","texto":"Las emisiones de hoy se acumulan en la atmósfera"},{"id":"i2","texto":"Ese CO₂ sigue calentando durante siglos"},{"id":"i3","texto":"Los impactos crecen hacia fines de siglo"},{"id":"i4","texto":"Los más afectados serán quienes hoy son chicos o no nacieron"},{"id":"i5","texto":"El CO₂ desaparece al año siguiente"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo viste con el efecto invernadero: lo que se emite hoy pesa durante mucho tiempo."}},{"slug":"comunidad-3.s4.p10","orden":10,"grupo":"comunidad-3.s4.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión tiene en cuenta a las generaciones futuras o no?","grupos":[{"id":"g1","nombre":"Las tiene en cuenta"},{"id":"g2","nombre":"No las tiene en cuenta"}],"items":[{"id":"i1","texto":"Proteger un acuífero aunque hoy sobre agua"},{"id":"i2","texto":"Agotar un recurso porque hoy es rentable"},{"id":"i3","texto":"Planificar la ciudad pensando en el clima de 2050"},{"id":"i4","texto":"Rellenar humedales sin pensar en las crecidas futuras"},{"id":"i5","texto":"Crear un consejo juvenil consultivo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Pensar en quienes vienen es parte de cualquier decisión ambiental responsable."}},{"slug":"comunidad-3.s4.p11","orden":11,"grupo":"comunidad-3.s4.p11","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos hitos en el tiempo, del más antiguo al más reciente.","items":[{"id":"i1","texto":"Reforma constitucional que incorpora el artículo 41"},{"id":"i2","texto":"Fallo de la Corte Suprema en la causa Mendoza"},{"id":"i3","texto":"Fallo de la Corte colombiana sobre la Amazonia"},{"id":"i4","texto":"Opinión consultiva de la Corte Internacional de Justicia sobre el clima"}],"extremos":["Más antiguo","Más reciente"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"1994, 2008, 2018 y 2025: el reconocimiento de los derechos ambientales avanza con el tiempo."}},{"slug":"comunidad-3.s4.p12","orden":12,"grupo":"comunidad-3.s4.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué tiene sentido que los jóvenes participen más en las decisiones climáticas?","opciones":[{"id":"o1","texto":"Porque vivirán más tiempo con sus consecuencias"},{"id":"o2","texto":"Porque saben más que todos los adultos"},{"id":"o3","texto":"Porque así los adultos ya no tienen que decidir"},{"id":"o4","texto":"Porque las decisiones climáticas no afectan a los adultos"}]},"solucion":{"clave":["o1"],"explicacion":"Quienes cargarán con las consecuencias por más tiempo merecen voz en las decisiones.","por_opcion":{"o3":"Se trata de sumar voces, no de reemplazar."}}},{"slug":"comunidad-3.s4.p13","orden":13,"grupo":"comunidad-3.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El artículo 41 menciona a las generaciones futuras."},{"id":"s2","texto":"Las generaciones futuras no tienen ninguna protección legal."},{"id":"s3","texto":"En 2018, la Corte colombiana reconoció derechos a la Amazonia."},{"id":"s4","texto":"Como los jóvenes no votan, su opinión no cuenta en temas ambientales."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La justicia con las generaciones futuras es un principio legal, no solo una idea.","por_opcion":{"s2":"La Constitución y distintos tribunales las reconocen.","s4":"Tienen muchas formas de participar y sus derechos están en juego."}}},{"slug":"comunidad-3.s4.p14","orden":14,"grupo":"comunidad-3.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La idea de no comprometer las necesidades de quienes vienen es la equidad {{0}}; la Constitución la incluye en su artículo {{1}}; y en 2025 la Corte Internacional de {{2}} se pronunció sobre el clima.","banco":[{"id":"w1","texto":"intergeneracional"},{"id":"w2","texto":"41"},{"id":"w3","texto":"Justicia"},{"id":"w4","texto":"generacional"},{"id":"w5","texto":"14"},{"id":"w6","texto":"Cuentas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la justicia con las generaciones futuras."}}]},{"slug":"comunidad-3.s5","orden":5,"tipo":"leccion","titulo_es":"Soluciones justas","bajada_es":"Transición justa, verde sin expulsión, participación y tarifas: cómo cuidar el ambiente sin profundizar desigualdades.","minutos":12,"pasos":[{"slug":"comunidad-3.s5.p1","orden":1,"grupo":"comunidad-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Transición justa","cuerpo":["Cambiar hacia una economía con menos emisiones implica que algunas actividades se achiquen y otras crezcan. Una transición justa busca que las personas que trabajan en los sectores que se reducen —como el carbón o algunas industrias— no queden abandonadas: capacitación, nuevos empleos en la región, protección social y participación de trabajadores y comunidades en el diseño de la transición. El Acuerdo de París menciona la transición justa de la fuerza laboral."]},"solucion":{}},{"slug":"comunidad-3.s5.p2","orden":2,"grupo":"comunidad-3.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué incluye una transición justa? Marcá todo.","opciones":[{"id":"o1","texto":"Capacitación para nuevos empleos"},{"id":"o2","texto":"Inversiones en la región afectada"},{"id":"o3","texto":"Participación de trabajadores y comunidades"},{"id":"o4","texto":"Protección social durante el cambio"},{"id":"o5","texto":"Cerrar las actividades de un día para el otro sin aviso"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La transición es más rápida y más estable cuando nadie queda afuera."}},{"slug":"comunidad-3.s5.p3","orden":3,"grupo":"comunidad-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Verde sin expulsión","cuerpo":["Mejorar el ambiente de un barrio —una plaza nueva, un arroyo saneado, más árboles— puede tener un efecto inesperado: si el barrio se vuelve más atractivo, suben los alquileres y los precios, y las familias que vivían allí terminan yéndose. Se lo llama gentrificación verde. Para evitarlo, las mejoras pueden acompañarse con políticas de vivienda, alquileres protegidos o participación de los vecinos en el diseño."]},"solucion":{}},{"slug":"comunidad-3.s5.p4","orden":4,"grupo":"comunidad-3.s5.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la gentrificación verde.","items":[{"id":"i1","texto":"Se construye un gran parque en un barrio popular"},{"id":"i2","texto":"El barrio se vuelve más atractivo"},{"id":"i3","texto":"Suben los alquileres y los precios de las viviendas"},{"id":"i4","texto":"Familias que vivían allí no pueden pagar y se van"},{"id":"i5","texto":"Los beneficios del parque los disfrutan otras personas"},{"id":"i6","texto":"Bajan los alquileres porque hay más verde"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una mejora ambiental sin políticas sociales puede terminar desplazando a quienes debía beneficiar."}},{"slug":"comunidad-3.s5.p5","orden":5,"grupo":"comunidad-3.s5.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué puede evitar que una mejora ambiental expulse a los vecinos de un barrio?","opciones":[{"id":"o1","texto":"Acompañarla con políticas de vivienda y participación"},{"id":"o2","texto":"No hacer ninguna mejora en los barrios populares"},{"id":"o3","texto":"Subir los impuestos solo a los vecinos actuales"},{"id":"o4","texto":"Hacer la mejora sin avisar a nadie"}]},"solucion":{"clave":["o1"],"explicacion":"La respuesta no es dejar de mejorar, sino mejorar con los vecinos y protegiendo su permanencia.","por_opcion":{"o3":"Aceleraría la expulsión en lugar de evitarla."}}},{"slug":"comunidad-3.s5.p6","orden":6,"grupo":"comunidad-3.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Priorizar a quien más lo necesita","cuerpo":["Una forma de aplicar la justicia ambiental es priorizar las inversiones donde las carencias son mayores: primero las cloacas, el agua segura y el arbolado en los barrios que no los tienen. Para eso sirven los mapas que cruzan datos ambientales y sociales: contaminación, espacios verdes, inundaciones, ingresos y acceso a servicios."]},"solucion":{}},{"slug":"comunidad-3.s5.p7","orden":7,"grupo":"comunidad-3.s5.p7","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas inversiones de una ciudad según cuánto reducen la injusticia ambiental, de mayor a menor.","items":[{"id":"i1","texto":"Cloacas y agua segura en barrios que no las tienen"},{"id":"i2","texto":"Arbolado en barrios con poca sombra"},{"id":"i3","texto":"Renovar una plaza en un barrio con muchas plazas"},{"id":"i4","texto":"Fuentes decorativas en el centro comercial"}],"extremos":["Mayor reducción","Menor reducción"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La misma plata puede reducir o ampliar las desigualdades según dónde se invierta.","valores":{"i1":"la mayor","i2":"grande","i3":"poca","i4":"mínima"}}},{"slug":"comunidad-3.s5.p8","orden":8,"grupo":"comunidad-3.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 20.000 habitantes y el 40 % no tiene cloacas. ¿Cuántas personas se beneficiarían si se completara la red?","unidad":"personas","decimales":0,"contexto":"20000 habitantes; 40 % sin cloacas."},"solucion":{"valor":8000,"tolerancia":160,"explicacion":"20.000 × 40 % = 8.000 personas. Datos como este ayudan a priorizar obras con criterio de justicia."}},{"slug":"comunidad-3.s5.p8.v2","orden":8,"grupo":"comunidad-3.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 50.000 habitantes y el 25 % no tiene cloacas. ¿Cuántas personas se beneficiarían si se completara la red?","unidad":"personas","decimales":0,"contexto":"50000 habitantes; 25 % sin cloacas."},"solucion":{"valor":12500,"tolerancia":250,"explicacion":"50.000 × 25 % = 12.500 personas. Datos como este ayudan a priorizar obras con criterio de justicia."}},{"slug":"comunidad-3.s5.p8.v3","orden":8,"grupo":"comunidad-3.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 12.000 habitantes y el 60 % no tiene cloacas. ¿Cuántas personas se beneficiarían si se completara la red?","unidad":"personas","decimales":0,"contexto":"12000 habitantes; 60 % sin cloacas."},"solucion":{"valor":7200,"tolerancia":144,"explicacion":"12.000 × 60 % = 7.200 personas. Datos como este ayudan a priorizar obras con criterio de justicia."}},{"slug":"comunidad-3.s5.p9","orden":9,"grupo":"comunidad-3.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Participar de verdad","cuerpo":["La dimensión procedimental se trabaja con participación real: información clara y a tiempo, audiencias en horarios y lugares accesibles, traducción cuando hace falta, y respuestas a lo que plantean los vecinos. El Acuerdo de Escazú, que Argentina aprobó, busca garantizar el acceso a la información, la participación y la justicia en asuntos ambientales, con atención especial a las personas y grupos en situación de vulnerabilidad."]},"solucion":{}},{"slug":"comunidad-3.s5.p10","orden":10,"grupo":"comunidad-3.s5.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta forma de participación es accesible o no?","grupos":[{"id":"g1","nombre":"Accesible"},{"id":"g2","nombre":"No accesible"}],"items":[{"id":"i1","texto":"Audiencia en el barrio afectado, un sábado"},{"id":"i2","texto":"Audiencia un martes a las 10 en otra ciudad"},{"id":"i3","texto":"Materiales en lenguaje claro y en la lengua de la comunidad"},{"id":"i4","texto":"Un expediente técnico sin resumen"},{"id":"i5","texto":"Respuesta escrita a cada propuesta vecinal"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Que exista una instancia de participación no alcanza: tiene que ser posible participar."}},{"slug":"comunidad-3.s5.p11","orden":11,"grupo":"comunidad-3.s5.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una política ambiental puede ser justa aunque la paguen solo los hogares de menores ingresos.","razones":[{"id":"r1","texto":"Porque profundizaría la desigualdad"},{"id":"r2","texto":"Porque los hogares pobres nunca pagan impuestos"},{"id":"r3","texto":"Porque la justicia no tiene relación con quién paga"}]},"solucion":{"valor":false,"explicacion":"Si los costos recaen sobre quienes tienen menos, la política profundiza la desigualdad. Lo viste con los impuestos y subsidios: el diseño decide quién paga.","clave":["r1"]}},{"slug":"comunidad-3.s5.p12","orden":12,"grupo":"comunidad-3.s5.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada medida con la condición que la hace justa.","izquierda":[{"id":"a1","texto":"Cierre de una mina de carbón"},{"id":"a2","texto":"Parque nuevo en un barrio popular"},{"id":"a3","texto":"Impuesto a la energía"},{"id":"a4","texto":"Audiencia pública"}],"derecha":[{"id":"b1","texto":"Plan de empleo y capacitación en la región"},{"id":"b2","texto":"Políticas para que los vecinos se queden"},{"id":"b3","texto":"Compensación a hogares de bajos ingresos"},{"id":"b4","texto":"Horario y lugar accesibles para los afectados"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada medida ambiental tiene una condición que la hace justa: detectarla es parte del diseño."}},{"slug":"comunidad-3.s5.p13","orden":13,"grupo":"comunidad-3.s5.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se cierra un basural donde trabajaban 120 recuperadores. La nueva planta de reciclaje con una cooperativa incorpora al 75 %. ¿Cuántas personas quedan sin trabajo en el nuevo sistema?","unidad":"personas","decimales":0,"contexto":"120 recuperadores; 75 % incorporados."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"120 × 75 % = 90 incorporados; quedan 30. Una transición justa busca que ese número llegue a cero."}},{"slug":"comunidad-3.s5.p13.v2","orden":13,"grupo":"comunidad-3.s5.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se cierra un basural donde trabajaban 80 recuperadores. La nueva planta de reciclaje con una cooperativa incorpora al 60 %. ¿Cuántas personas quedan sin trabajo en el nuevo sistema?","unidad":"personas","decimales":0,"contexto":"80 recuperadores; 60 % incorporados."},"solucion":{"valor":32,"tolerancia":0.64,"explicacion":"80 × 60 % = 48 incorporados; quedan 32. Una transición justa busca que ese número llegue a cero."}},{"slug":"comunidad-3.s5.p13.v3","orden":13,"grupo":"comunidad-3.s5.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se cierra un basural donde trabajaban 200 recuperadores. La nueva planta de reciclaje con una cooperativa incorpora al 90 %. ¿Cuántas personas quedan sin trabajo en el nuevo sistema?","unidad":"personas","decimales":0,"contexto":"200 recuperadores; 90 % incorporados."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"200 × 90 % = 180 incorporados; quedan 20. Una transición justa busca que ese número llegue a cero."}},{"slug":"comunidad-3.s5.p14","orden":14,"grupo":"comunidad-3.s5.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan municipal y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Priorizaremos cloacas en los barrios sin conexión."},{"id":"s2","texto":"Haremos la audiencia pública un martes a las 10 en el centro."},{"id":"s3","texto":"El nuevo parque incluirá políticas para que los vecinos no sean desplazados."},{"id":"s4","texto":"Los trabajadores del basural que cerramos no necesitan ningún plan."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La justicia ambiental se juega en los detalles de cada plan.","por_opcion":{"s2":"Conviene hacerla en horarios y lugares accesibles para los afectados.","s4":"Una transición justa incluye a quienes pierden su fuente de ingresos."}}},{"slug":"comunidad-3.s5.p15","orden":15,"grupo":"comunidad-3.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Que nadie quede abandonado al cambiar la economía es una transición {{0}}; cuando una mejora verde expulsa a los vecinos se habla de gentrificación {{1}}; y el acuerdo regional sobre información, participación y justicia es el de {{2}}.","banco":[{"id":"w1","texto":"justa"},{"id":"w2","texto":"verde"},{"id":"w3","texto":"Escazú"},{"id":"w4","texto":"rápida"},{"id":"w5","texto":"gris"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para diseñar soluciones ambientales justas."}}]},{"slug":"comunidad-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: justicia ambiental","bajada_es":"Dimensiones, el caso Riachuelo, desigualdad climática, generaciones futuras y soluciones justas, mezclados.","minutos":8,"pasos":[{"slug":"comunidad-3.s6.p1","orden":1,"grupo":"comunidad-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Justicia ambiental». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"comunidad-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el mapa de la ciudad","bajada_es":"Una ciudad cruzó datos ambientales y sociales de cuatro barrios. Con el mapa, decidí dónde invertir primero.","minutos":10,"pasos":[{"slug":"comunidad-3.s7.p1","orden":1,"grupo":"comunidad-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["La ciudad tiene presupuesto para una gran inversión ambiental este año y quiere usar criterios de justicia ambiental. Cruzó, para cada barrio, el ingreso medio de los hogares, los metros cuadrados de espacio verde por habitante, el porcentaje de viviendas sin conexión a cloacas y la frecuencia con que se inunda."],"datos":{"tipo":"tabla","titulo":"Indicadores por barrio (datos ficticios)","columnas":["Barrio","Ingreso medio","Verde por habitante","Sin cloacas","Se inunda"],"filas":[["Norte","alto","14 m²","0 %","nunca"],["Centro","medio","6 m²","5 %","rara vez"],["Arroyo","bajo","1 m²","55 %","cada año"],["Vía","bajo","3 m²","30 %","a veces"]],"nota":"Datos ficticios para el ejercicio."}},"solucion":{}},{"slug":"comunidad-3.s7.p2","orden":2,"grupo":"comunidad-3.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas veces más espacio verde por habitante tiene el barrio Norte que el barrio Arroyo?","unidad":"veces","decimales":0,"contexto":"Norte 14 m²; Arroyo 1 m² por habitante."},"solucion":{"valor":14,"tolerancia":0.5,"explicacion":"14 ÷ 1 = 14 veces. Una brecha enorme en sombra, recreación y regulación del calor."}},{"slug":"comunidad-3.s7.p3","orden":3,"grupo":"comunidad-3.s7.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los barrios según su prioridad para la inversión, de mayor a menor.","items":[{"id":"i1","texto":"Arroyo"},{"id":"i2","texto":"Vía"},{"id":"i3","texto":"Centro"},{"id":"i4","texto":"Norte"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Priorizar donde se acumulan las carencias es aplicar la dimensión distributiva.","valores":{"i1":"bajo ingreso, sin cloacas, se inunda cada año","i2":"bajo ingreso, 30 % sin cloacas","i3":"ingreso medio, algunas carencias","i4":"sin carencias graves"}}},{"slug":"comunidad-3.s7.p4","orden":4,"grupo":"comunidad-3.s7.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir la inversión en el barrio Arroyo? Marcá todo.","opciones":[{"id":"o1","texto":"Red cloacal"},{"id":"o2","texto":"Obras y espacios verdes que absorban agua de lluvia"},{"id":"o3","texto":"Participación de los vecinos en el diseño"},{"id":"o4","texto":"Medidas para que los vecinos no sean desplazados"},{"id":"o5","texto":"Una fuente decorativa en la entrada del barrio"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cloacas, verde que ayude con las inundaciones, participación y protección contra la expulsión."}},{"slug":"comunidad-3.s7.p5","orden":5,"grupo":"comunidad-3.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un concejal propone invertir en el barrio Norte \"porque ahí se ve más\". ¿Qué criterio de justicia contradice?","opciones":[{"id":"o1","texto":"El distributivo: invierte donde menos falta"},{"id":"o2","texto":"El de reconocimiento, porque ignora la cultura"},{"id":"o3","texto":"Ninguno, porque todos los barrios son iguales"},{"id":"o4","texto":"El procedimental, porque hubo audiencia"}]},"solucion":{"clave":["o1"],"explicacion":"Invertir donde menos falta aumenta las brechas en lugar de reducirlas.","por_opcion":{"o3":"Los datos muestran que no lo son."}}},{"slug":"comunidad-3.s7.p6","orden":6,"grupo":"comunidad-3.s7.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el proceso para decidir la inversión con justicia.","items":[{"id":"i1","texto":"Cruzar datos ambientales y sociales de cada barrio"},{"id":"i2","texto":"Identificar dónde se acumulan las carencias"},{"id":"i3","texto":"Hacer audiencias accesibles en esos barrios"},{"id":"i4","texto":"Diseñar las obras con los vecinos"},{"id":"i5","texto":"Medir los resultados y publicarlos"},{"id":"i6","texto":"Decidir en una oficina y avisar cuando empiezan las obras"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Datos, prioridad, participación, diseño conjunto y rendición de cuentas."}},{"slug":"comunidad-3.s7.p7","orden":7,"grupo":"comunidad-3.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Mirar solo el ingreso de cada barrio alcanza para decidir la inversión ambiental.","razones":[{"id":"r1","texto":"Porque hace falta cruzarlo con datos ambientales"},{"id":"r2","texto":"Porque el ingreso no tiene ninguna relación"},{"id":"r3","texto":"Porque todos los barrios pobres tienen las mismas carencias"}]},"solucion":{"valor":false,"explicacion":"El ingreso ayuda, pero hay que cruzarlo con indicadores ambientales: cloacas, verde, inundaciones, contaminación. Dos barrios de ingreso parecido pueden tener carencias muy distintas.","clave":["r1"]}},{"slug":"comunidad-3.s7.p8","orden":8,"grupo":"comunidad-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La ciudad redacta su decisión. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Priorizamos el barrio Arroyo por su acumulación de carencias."},{"id":"s2","texto":"Las obras se diseñarán sin consultar para no demorar."},{"id":"s3","texto":"Publicaremos los indicadores cada año para medir avances."},{"id":"s4","texto":"No hace falta prever nada sobre alquileres: el verde siempre beneficia a los mismos vecinos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una decisión justa usa datos, prioriza, participa y cuida a quienes viven allí.","por_opcion":{"s2":"La participación mejora el diseño y es un derecho.","s4":"Sin políticas de vivienda, puede haber gentrificación verde."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"comunidad-4","rama":"comunidad","orden":4,"nivel":2,"titulo_es":"Conflictos ambientales","bajada_es":"Minas, fábricas, represas y humedales: por qué surgen los conflictos ambientales, qué enseñan los casos argentinos y cómo se pueden transformar en acuerdos.","objetivos_es":["Definir un conflicto ambiental y reconocer sus tipos","Analizar los casos de Esquel y de las papeleras sobre el río Uruguay","Mapear actores, posiciones e intereses en un conflicto","Conocer las herramientas institucionales y la protección de las personas defensoras","Proponer procesos para transformar un conflicto en acuerdos"],"repasa":["comunidad-2","comunidad-3","comunidad-1","tronco-3"],"requiere_tronco":2,"fuentes":["ejatlas","ejatlas-esquel","cij-papeleras-2010","escazu","ley-25675-ambiente","ley-25831-info","global-witness-defensores","ley-24071-oit-169"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"comunidad-4.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es un conflicto ambiental","bajada_es":"Desacuerdos sobre el uso, el acceso y los impactos de la naturaleza: por qué aparecen y qué señalan.","minutos":11,"pasos":[{"slug":"comunidad-4.s1.p1","orden":1,"grupo":"comunidad-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una disputa sobre el ambiente","cuerpo":["Un conflicto ambiental es una disputa entre actores —vecinos, empresas, gobiernos, comunidades, organizaciones— sobre el acceso, el uso o los impactos de un bien natural: el agua, la tierra, el aire, un bosque, un río. Aparecen cuando alguien siente que una actividad amenaza su salud, su forma de vida o sus derechos, y cuando los canales para resolver el desacuerdo no alcanzan.","El Atlas de Justicia Ambiental, un proyecto académico, documenta miles de conflictos ambientales en todo el mundo, muchos de ellos en América Latina."]},"solucion":{}},{"slug":"comunidad-4.s1.p2","orden":2,"grupo":"comunidad-4.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de conflicto ambiental es cada caso?","grupos":[{"id":"g1","nombre":"Por extracción de recursos"},{"id":"g2","nombre":"Por contaminación"},{"id":"g3","nombre":"Por infraestructura o uso del suelo"}],"items":[{"id":"i1","texto":"Una mina a cielo abierto cerca de un pueblo"},{"id":"i2","texto":"Una fábrica que vierte efluentes a un río"},{"id":"i3","texto":"Una represa que inundaría tierras de una comunidad"},{"id":"i4","texto":"Un pozo petrolero en un área de pastoreo"},{"id":"i5","texto":"Un basural que quema residuos junto a un barrio"},{"id":"i6","texto":"Un barrio cerrado que rellena un humedal"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Los conflictos se agrupan por la actividad que los origina, aunque muchos combinan varios tipos."}},{"slug":"comunidad-4.s1.p3","orden":3,"grupo":"comunidad-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todo conflicto es malo","cuerpo":["Un conflicto puede ser doloroso, pero también cumple una función: hace visible un problema que antes no se discutía, abre preguntas sobre quién decide y puede mejorar las reglas. Muchas leyes ambientales nacieron después de conflictos. El problema no es que haya desacuerdos, sino que se resuelvan con violencia, con engaños o dejando a una parte sin voz."]},"solucion":{}},{"slug":"comunidad-4.s1.p4","orden":4,"grupo":"comunidad-4.s1.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Todo conflicto ambiental es un fracaso que conviene evitar a cualquier costo.","razones":[{"id":"r1","texto":"Porque pueden revelar problemas y mejorar las reglas"},{"id":"r2","texto":"Porque los conflictos siempre terminan bien"},{"id":"r3","texto":"Porque en democracia no hay desacuerdos"}]},"solucion":{"valor":false,"explicacion":"Los conflictos pueden revelar problemas reales y mejorar las reglas. Lo que conviene evitar es la violencia y la exclusión, no el desacuerdo en sí.","clave":["r1"]}},{"slug":"comunidad-4.s1.p5","orden":5,"grupo":"comunidad-4.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Etapas","cuerpo":["Los conflictos suelen pasar por etapas. Empiezan latentes: hay un problema, pero no se discute en público. Se vuelven manifiestos cuando alguien reclama. Pueden escalar, con más tensión, acusaciones y medidas de fuerza. Y en algún momento llegan a una salida: un acuerdo, una decisión judicial, el abandono del proyecto, o un conflicto que queda abierto por años."]},"solucion":{}},{"slug":"comunidad-4.s1.p6","orden":6,"grupo":"comunidad-4.s1.p6","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas típicas de un conflicto ambiental.","items":[{"id":"i1","texto":"Latente: hay un problema, pero no se discute"},{"id":"i2","texto":"Manifiesto: alguien reclama públicamente"},{"id":"i3","texto":"Escalada: crecen la tensión y las medidas de fuerza"},{"id":"i4","texto":"Salida: acuerdo, decisión judicial o cambio del proyecto"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Detectar un conflicto en su etapa latente permite abordarlo antes de que escale."}},{"slug":"comunidad-4.s1.p7","orden":7,"grupo":"comunidad-4.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo escala un conflicto.","items":[{"id":"i1","texto":"Una empresa anuncia un proyecto sin informar sus impactos"},{"id":"i2","texto":"Los vecinos piden información y no la reciben"},{"id":"i3","texto":"Crece la desconfianza y se organizan protestas"},{"id":"i4","texto":"La empresa y el gobierno responden con descalificaciones"},{"id":"i5","texto":"El conflicto escala y se vuelve más difícil de resolver"},{"id":"i6","texto":"La falta de información genera confianza"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La falta de información y de escucha es una de las principales causas de escalada."}},{"slug":"comunidad-4.s1.p8","orden":8,"grupo":"comunidad-4.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué suele hacer escalar un conflicto ambiental? Marcá todo.","opciones":[{"id":"o1","texto":"Ocultar información sobre los impactos"},{"id":"o2","texto":"Descalificar a quienes reclaman"},{"id":"o3","texto":"Tomar decisiones sin consultar"},{"id":"o4","texto":"Publicar los estudios completos a tiempo"},{"id":"o5","texto":"Escuchar las preocupaciones de las comunidades"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Lo que escala un conflicto es, casi siempre, lo contrario de lo que lo transforma."}},{"slug":"comunidad-4.s1.p9","orden":9,"grupo":"comunidad-4.s1.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Conflicto ambiental"},{"id":"a2","texto":"Conflicto latente"},{"id":"a3","texto":"Escalada"},{"id":"a4","texto":"Atlas de Justicia Ambiental"}],"derecha":[{"id":"b1","texto":"Disputa sobre el uso o los impactos de un bien natural"},{"id":"b2","texto":"Problema que existe pero no se discute"},{"id":"b3","texto":"Aumento de la tensión y las medidas de fuerza"},{"id":"b4","texto":"Registro de conflictos ambientales del mundo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario básico para analizar un conflicto ambiental."}},{"slug":"comunidad-4.s1.p10","orden":10,"grupo":"comunidad-4.s1.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene detectar un conflicto cuando todavía es latente?","opciones":[{"id":"o1","texto":"Porque es más fácil abordarlo antes de que escale"},{"id":"o2","texto":"Porque en esa etapa nadie tiene derechos"},{"id":"o3","texto":"Porque así se puede ocultar mejor"},{"id":"o4","texto":"Porque los conflictos latentes desaparecen solos"}]},"solucion":{"clave":["o1"],"explicacion":"Como con la salud, la prevención y la detección temprana ahorran mucho daño.","por_opcion":{"o3":"Ocultarlo suele hacerlo escalar después."}}},{"slug":"comunidad-4.s1.p11","orden":11,"grupo":"comunidad-4.s1.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un basural contamina un arroyo desde hace años, pero nadie lo discute en público. ¿En qué etapa está el conflicto?","opciones":[{"id":"o1","texto":"Latente"},{"id":"o2","texto":"Escalada"},{"id":"o3","texto":"Resuelto"},{"id":"o4","texto":"Manifiesto"}]},"solucion":{"clave":["o1"],"explicacion":"Un conflicto latente es un problema real que todavía no encontró voz pública.","por_opcion":{"o3":"El problema sigue: que nadie lo discuta no significa que se resolvió."}}},{"slug":"comunidad-4.s1.p12","orden":12,"grupo":"comunidad-4.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los conflictos ambientales pueden hacer visible un problema real."},{"id":"s2","texto":"Si la gente protesta, es porque alguien la manipula."},{"id":"s3","texto":"Muchas leyes ambientales surgieron después de conflictos."},{"id":"s4","texto":"Ocultar información ayuda a calmar los conflictos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Mirar los conflictos con respeto es el primer paso para transformarlos.","por_opcion":{"s2":"Descalificar así ignora preocupaciones reales y escala el conflicto.","s4":"La falta de información es una causa frecuente de escalada."}}},{"slug":"comunidad-4.s1.p13","orden":13,"grupo":"comunidad-4.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una disputa sobre el uso o los impactos de un bien natural es un conflicto {{0}}; cuando todavía no se discute en público es {{1}}; y cuando crece la tensión se habla de {{2}}.","banco":[{"id":"w1","texto":"ambiental"},{"id":"w2","texto":"latente"},{"id":"w3","texto":"escalada"},{"id":"w4","texto":"comercial"},{"id":"w5","texto":"resuelto"},{"id":"w6","texto":"pausa"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para entender cómo evolucionan los conflictos."}},{"slug":"comunidad-4.s1.p14","orden":14,"grupo":"comunidad-4.s1.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas respuestas de una empresa ante un reclamo, de la que más calma a la que más escala.","items":[{"id":"i1","texto":"Publicar los estudios y abrir un espacio de diálogo"},{"id":"i2","texto":"Responder por escrito con información parcial"},{"id":"i3","texto":"Ignorar el reclamo"},{"id":"i4","texto":"Acusar a los vecinos de estar manipulados"}],"extremos":["Más calma","Más escala"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La transparencia y el respeto bajan la tensión; el desprecio la multiplica.","valores":{"i1":"desescala","i2":"neutra","i3":"escala","i4":"escala mucho"}}}]},{"slug":"comunidad-4.s2","orden":2,"tipo":"leccion","titulo_es":"Dos casos argentinos","bajada_es":"El plebiscito de Esquel y el conflicto por las papeleras sobre el río Uruguay: qué pasó y qué enseñan.","minutos":10,"pasos":[{"slug":"comunidad-4.s2.p1","orden":1,"grupo":"comunidad-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Esquel, 2003","cuerpo":["A comienzos de los 2000, una empresa minera proyectaba explotar oro cerca de Esquel, en Chubut, con una mina a cielo abierto que usaría cianuro para separar el metal. Vecinos se organizaron en una asamblea, pidieron información y reclamaron ser consultados. En marzo de 2003 se realizó un plebiscito municipal: con alta participación, alrededor del 81 % votó en contra del proyecto. Ese mismo año, Chubut sancionó una ley que prohíbe la minería metalífera a cielo abierto y el uso de cianuro."],"destacado":{"valor":"≈ 81 %","texto":"de los votantes de Esquel rechazó el proyecto minero en el plebiscito de marzo de 2003."}},"solucion":{}},{"slug":"comunidad-4.s2.p2","orden":2,"grupo":"comunidad-4.s2.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los hechos del caso Esquel.","items":[{"id":"i1","texto":"Una empresa proyecta una mina de oro con cianuro cerca de la ciudad"},{"id":"i2","texto":"Los vecinos se organizan en una asamblea"},{"id":"i3","texto":"Se realiza un plebiscito municipal"},{"id":"i4","texto":"Alrededor del 81 % vota en contra"},{"id":"i5","texto":"La provincia sanciona una ley que prohíbe ese tipo de minería"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un caso que mostró el peso de la participación local en las decisiones ambientales."}},{"slug":"comunidad-4.s2.p3","orden":3,"grupo":"comunidad-4.s2.p3","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué herramienta de participación fue central en el caso Esquel?","opciones":[{"id":"o1","texto":"Un plebiscito municipal"},{"id":"o2","texto":"Una encuesta privada de la empresa"},{"id":"o3","texto":"Un fallo de la Corte Internacional de Justicia"},{"id":"o4","texto":"Un decreto del gobierno nacional"}]},"solucion":{"clave":["o1"],"explicacion":"La consulta directa a la población le dio fuerza política al reclamo vecinal.","por_opcion":{"o3":"Ese fue el caso de las papeleras, no el de Esquel."}}},{"slug":"comunidad-4.s2.p4","orden":4,"grupo":"comunidad-4.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las papeleras, 2005–2010","cuerpo":["En 2005, Uruguay autorizó la construcción de una gran planta de celulosa sobre el río Uruguay, frente a la ciudad argentina de Gualeguaychú. Vecinos de Gualeguaychú temían la contaminación del río y del aire, y durante años bloquearon el puente internacional. Argentina llevó el caso a la Corte Internacional de Justicia, en La Haya, porque ambos países comparten el río bajo un estatuto de 1975.","En 2010, la Corte decidió que Uruguay había incumplido su obligación de informar y consultar a Argentina antes de autorizar la planta, pero que no se había probado que la planta violara sus obligaciones de proteger el río. No ordenó desmantelarla. Después, ambos países acordaron un monitoreo conjunto del río."]},"solucion":{}},{"slug":"comunidad-4.s2.p5","orden":5,"grupo":"comunidad-4.s2.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Según el fallo de 2010, ¿qué decidió la Corte Internacional de Justicia?","grupos":[{"id":"g1","nombre":"Lo que decidió"},{"id":"g2","nombre":"Lo que no decidió"}],"items":[{"id":"i1","texto":"Uruguay incumplió su obligación de informar a Argentina"},{"id":"i2","texto":"Que la planta debía cerrarse de inmediato"},{"id":"i3","texto":"No se probó que la planta violara la protección del río"},{"id":"i4","texto":"Que Argentina debía pagar una multa a Uruguay"},{"id":"i5","texto":"No ordenó desmantelar la planta"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Un fallo matizado: una obligación incumplida, otra no probada, y una salida basada en el monitoreo conjunto."}},{"slug":"comunidad-4.s2.p6","orden":6,"grupo":"comunidad-4.s2.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada caso con su herramienta principal.","izquierda":[{"id":"a1","texto":"Esquel"},{"id":"a2","texto":"Papeleras"},{"id":"a3","texto":"Riachuelo"},{"id":"a4","texto":"Salida de las papeleras"}],"derecha":[{"id":"b1","texto":"Plebiscito municipal"},{"id":"b2","texto":"Corte Internacional de Justicia"},{"id":"b3","texto":"Fallo de la Corte Suprema argentina"},{"id":"b4","texto":"Monitoreo conjunto del río"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada conflicto encontró caminos institucionales distintos."}},{"slug":"comunidad-4.s2.p7","orden":7,"grupo":"comunidad-4.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En el caso de las papeleras, la Corte Internacional de Justicia ordenó cerrar la planta.","razones":[{"id":"r1","texto":"Porque no se probó el daño y no ordenó desmantelarla"},{"id":"r2","texto":"Porque la Corte no tuvo ningún papel"},{"id":"r3","texto":"Porque la planta nunca se construyó"}]},"solucion":{"valor":false,"explicacion":"Decidió que Uruguay incumplió la obligación de informar, pero no que la planta violara la protección del río, y no ordenó cerrarla.","clave":["r1"]}},{"slug":"comunidad-4.s2.p8","orden":8,"grupo":"comunidad-4.s2.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué lecciones dejan estos casos? Marcá todas.","opciones":[{"id":"o1","texto":"La información y la consulta previas pueden evitar conflictos largos"},{"id":"o2","texto":"Las instituciones pueden canalizar desacuerdos"},{"id":"o3","texto":"El monitoreo conjunto puede construir confianza"},{"id":"o4","texto":"Los vecinos no tienen ninguna influencia"},{"id":"o5","texto":"Los conflictos se resuelven solos si se los ignora"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Ambos casos muestran la importancia de informar, consultar y construir confianza."}},{"slug":"comunidad-4.s2.p9","orden":9,"grupo":"comunidad-4.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un plebiscito votan 20.000 personas y el 81 % vota en contra de un proyecto, ¿cuántas personas votaron en contra?","unidad":"personas","decimales":0,"contexto":"20000 votantes; 81 % en contra."},"solucion":{"valor":16200,"tolerancia":324,"explicacion":"20.000 × 81 % = 16.200 personas. Datos de ejemplo con el porcentaje de Esquel."}},{"slug":"comunidad-4.s2.p9.v2","orden":9,"grupo":"comunidad-4.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un plebiscito votan 15.000 personas y el 81 % vota en contra de un proyecto, ¿cuántas personas votaron en contra?","unidad":"personas","decimales":0,"contexto":"15000 votantes; 81 % en contra."},"solucion":{"valor":12150,"tolerancia":243,"explicacion":"15.000 × 81 % = 12.150 personas. Datos de ejemplo con el porcentaje de Esquel."}},{"slug":"comunidad-4.s2.p9.v3","orden":9,"grupo":"comunidad-4.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un plebiscito votan 25.000 personas y el 81 % vota en contra de un proyecto, ¿cuántas personas votaron en contra?","unidad":"personas","decimales":0,"contexto":"25000 votantes; 81 % en contra."},"solucion":{"valor":20250,"tolerancia":405,"explicacion":"25.000 × 81 % = 20.250 personas. Datos de ejemplo con el porcentaje de Esquel."}},{"slug":"comunidad-4.s2.p10","orden":10,"grupo":"comunidad-4.s2.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El plebiscito de Esquel fue organizado por la empresa minera para aprobar su proyecto.","razones":[{"id":"r1","texto":"Porque fue municipal, impulsado tras la movilización vecinal"},{"id":"r2","texto":"Porque en Esquel nunca hubo plebiscito"},{"id":"r3","texto":"Porque el resultado fue a favor de la mina"}]},"solucion":{"valor":false,"explicacion":"Fue un plebiscito municipal impulsado tras la movilización vecinal, y su resultado fue el rechazo del proyecto.","clave":["r1"]}},{"slug":"comunidad-4.s2.p11","orden":11,"grupo":"comunidad-4.s2.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En Esquel, cerca del 81 % votó en contra del proyecto minero."},{"id":"s2","texto":"El conflicto de las papeleras terminó con la planta desmantelada."},{"id":"s3","texto":"Argentina y Uruguay comparten el río Uruguay bajo un estatuto de 1975."},{"id":"s4","texto":"En Esquel, el proyecto usaba agua destilada para separar el oro."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Contar bien los casos es clave para aprender de ellos.","por_opcion":{"s2":"La Corte no ordenó desmantelarla; se acordó un monitoreo conjunto.","s4":"El proyecto preveía usar cianuro, que fue uno de los temas centrales."}}},{"slug":"comunidad-4.s2.p12","orden":12,"grupo":"comunidad-4.s2.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En Esquel, en 2003, la población votó en un {{0}}; el conflicto de las papeleras llegó a la Corte Internacional de {{1}}; y la salida acordada fue un {{2}} conjunto del río.","banco":[{"id":"w1","texto":"plebiscito"},{"id":"w2","texto":"Justicia"},{"id":"w3","texto":"monitoreo"},{"id":"w4","texto":"concurso"},{"id":"w5","texto":"Cuentas"},{"id":"w6","texto":"bloqueo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave de dos casos argentinos."}},{"slug":"comunidad-4.s2.p13","orden":13,"grupo":"comunidad-4.s2.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En el caso de las papeleras, ¿qué obligación incumplió Uruguay según la Corte?","opciones":[{"id":"o1","texto":"Informar a Argentina antes de autorizar"},{"id":"o2","texto":"Pagarle a Argentina por el agua del río"},{"id":"o3","texto":"Cerrar la planta en época de lluvias"},{"id":"o4","texto":"Prohibir el turismo en Gualeguaychú"}]},"solucion":{"clave":["o1"],"explicacion":"Las obligaciones de procedimiento, como informar y consultar, también son obligaciones jurídicas.","por_opcion":{"o3":"La Corte no impuso cierres estacionales."}}}]},{"slug":"comunidad-4.s3","orden":3,"tipo":"leccion","titulo_es":"Mapear actores e intereses","bajada_es":"Quién participa, qué pide, qué necesita y cuánto poder tiene: herramientas para entender un conflicto antes de actuar.","minutos":11,"pasos":[{"slug":"comunidad-4.s3.p1","orden":1,"grupo":"comunidad-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Actores","cuerpo":["En todo conflicto hay actores: personas, grupos u organizaciones con algo en juego. Pueden ser vecinos, comunidades indígenas, empresas, trabajadores, gobiernos municipales, provinciales o nacionales, organizaciones ambientales, universidades, medios de comunicación, jueces. Un primer paso para entender un conflicto es hacer una lista de todos los actores, no solo de los más visibles."]},"solucion":{}},{"slug":"comunidad-4.s3.p2","orden":2,"grupo":"comunidad-4.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de actor es cada uno?","grupos":[{"id":"g1","nombre":"Actor estatal"},{"id":"g2","nombre":"Actor privado"},{"id":"g3","nombre":"Actor social"}],"items":[{"id":"i1","texto":"Municipio"},{"id":"i2","texto":"Empresa que propone el proyecto"},{"id":"i3","texto":"Asamblea de vecinos"},{"id":"i4","texto":"Secretaría de ambiente provincial"},{"id":"i5","texto":"Cámara de comercio local"},{"id":"i6","texto":"Comunidad indígena"},{"id":"i7","texto":"Juzgado"},{"id":"i8","texto":"Organización ambiental"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g3"},"explicacion":"Mapear actores es el primer paso para entender quién está en juego y quién falta."}},{"slug":"comunidad-4.s3.p3","orden":3,"grupo":"comunidad-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Posiciones e intereses","cuerpo":["Una posición es lo que un actor dice que quiere: \"no a la planta\", \"sí a la planta\". Un interés es lo que necesita de fondo: agua limpia, salud, trabajo, ingresos, respeto. Las posiciones suelen chocar, pero los intereses a veces se pueden satisfacer al mismo tiempo. Buscar los intereses detrás de las posiciones abre opciones que parecían imposibles."]},"solucion":{}},{"slug":"comunidad-4.s3.p4","orden":4,"grupo":"comunidad-4.s3.p4","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada posición con un interés que puede haber detrás.","izquierda":[{"id":"a1","texto":"\"No queremos la planta\""},{"id":"a2","texto":"\"Queremos la planta ya\""},{"id":"a3","texto":"\"El proyecto no se modifica\""},{"id":"a4","texto":"\"Que decida la provincia\""}],"derecha":[{"id":"b1","texto":"Proteger la salud y el agua del barrio"},{"id":"b2","texto":"Conseguir empleo en la zona"},{"id":"b3","texto":"Recuperar la inversión en plazo"},{"id":"b4","texto":"Evitar un conflicto político local"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Detrás de posiciones opuestas puede haber intereses compatibles."}},{"slug":"comunidad-4.s3.p5","orden":5,"grupo":"comunidad-4.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Vecinos dicen \"no a la planta\" y trabajadores dicen \"sí a la planta\". ¿Qué opción aprovecha sus intereses?","opciones":[{"id":"o1","texto":"Condiciones que protejan el agua y generen empleo"},{"id":"o2","texto":"Elegir a un grupo y descartar al otro por completo"},{"id":"o3","texto":"Postergar la decisión para siempre"},{"id":"o4","texto":"Hacer una votación sin información"}]},"solucion":{"clave":["o1"],"explicacion":"Trabajar sobre intereses permite buscar soluciones que ninguna posición inicial planteaba.","por_opcion":{"o3":"Deja los dos intereses sin respuesta y el conflicto abierto."}}},{"slug":"comunidad-4.s3.p6","orden":6,"grupo":"comunidad-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Poder e interés","cuerpo":["Una herramienta útil es ubicar a cada actor en un mapa de dos ejes: cuánto poder tiene para influir en la decisión y cuánto interés o cuánto le afecta. Los que tienen mucho poder y mucho interés son centrales. Pero también importan los que tienen mucho interés y poco poder —por ejemplo, una comunidad pequeña muy afectada—: una buena gestión del conflicto busca que su voz pese."]},"solucion":{}},{"slug":"comunidad-4.s3.p7","orden":7,"grupo":"comunidad-4.s3.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Ubicá a cada actor en el mapa, según poder e interés.","grupos":[{"id":"g1","nombre":"Mucho poder, mucho interés"},{"id":"g2","nombre":"Poco poder, mucho interés"},{"id":"g3","nombre":"Mucho poder, poco interés"}],"items":[{"id":"i1","texto":"Empresa que invierte en el proyecto"},{"id":"i2","texto":"Familias que viven junto al sitio"},{"id":"i3","texto":"Un ministerio nacional que no participa"},{"id":"i4","texto":"Gobierno provincial que autoriza"},{"id":"i5","texto":"Pastores que usan el agua del lugar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2"},"explicacion":"Los actores con mucho interés y poco poder suelen ser los que más necesitan canales de participación."}},{"slug":"comunidad-4.s3.p8","orden":8,"grupo":"comunidad-4.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá los pasos para mapear un conflicto.","items":[{"id":"i1","texto":"Listar todos los actores involucrados"},{"id":"i2","texto":"Identificar la posición de cada uno"},{"id":"i3","texto":"Buscar los intereses detrás de cada posición"},{"id":"i4","texto":"Ubicarlos según su poder e interés"},{"id":"i5","texto":"Detectar quién falta en la conversación"},{"id":"i6","texto":"Escuchar solo al actor con más poder"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un buen mapa muestra también a los ausentes."}},{"slug":"comunidad-4.s3.p9","orden":9,"grupo":"comunidad-4.s3.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En un conflicto, lo importante es escuchar a los actores con más poder, porque son los que deciden.","razones":[{"id":"r1","texto":"Porque excluir a los afectados agrava el conflicto"},{"id":"r2","texto":"Porque los actores poderosos no tienen intereses"},{"id":"r3","texto":"Porque los afectados nunca tienen razón"}]},"solucion":{"valor":false,"explicacion":"Escuchar solo a los poderosos deja afuera a quienes más se ven afectados, lo que suele agravar el conflicto y producir injusticias.","clave":["r1"]}},{"slug":"comunidad-4.s3.p10","orden":10,"grupo":"comunidad-4.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mapa de actores hay 12 actores, y 3 de ellos nunca fueron invitados a ninguna reunión. ¿Qué porcentaje de los actores quedó afuera? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"3 de 12 actores sin invitar."},"solucion":{"valor":25,"tolerancia":1,"explicacion":"3 ÷ 12 × 100 ≈ 25 %. Un proceso que deja afuera a una parte de los actores difícilmente construya acuerdos duraderos."}},{"slug":"comunidad-4.s3.p10.v2","orden":10,"grupo":"comunidad-4.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mapa de actores hay 10 actores, y 4 de ellos nunca fueron invitados a ninguna reunión. ¿Qué porcentaje de los actores quedó afuera? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"4 de 10 actores sin invitar."},"solucion":{"valor":40,"tolerancia":1,"explicacion":"4 ÷ 10 × 100 ≈ 40 %. Un proceso que deja afuera a una parte de los actores difícilmente construya acuerdos duraderos."}},{"slug":"comunidad-4.s3.p10.v3","orden":10,"grupo":"comunidad-4.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mapa de actores hay 15 actores, y 5 de ellos nunca fueron invitados a ninguna reunión. ¿Qué porcentaje de los actores quedó afuera? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"5 de 15 actores sin invitar."},"solucion":{"valor":33,"tolerancia":1,"explicacion":"5 ÷ 15 × 100 ≈ 33 %. Un proceso que deja afuera a una parte de los actores difícilmente construya acuerdos duraderos."}},{"slug":"comunidad-4.s3.p11","orden":11,"grupo":"comunidad-4.s3.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una posición y un interés son lo mismo.","razones":[{"id":"r1","texto":"Porque la posición es lo que se pide y el interés lo que se necesita"},{"id":"r2","texto":"Porque los actores no tienen intereses"},{"id":"r3","texto":"Porque las posiciones nunca chocan"}]},"solucion":{"valor":false,"explicacion":"La posición es lo que alguien pide (\"no a la planta\"); el interés es lo que necesita de fondo (agua limpia, salud). Distinguirlos abre opciones.","clave":["r1"]}},{"slug":"comunidad-4.s3.p12","orden":12,"grupo":"comunidad-4.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este análisis de un conflicto y marcá los errores.","segmentos":[{"id":"s1","texto":"Listamos a vecinos, empresa, municipio y trabajadores."},{"id":"s2","texto":"No incluimos a la comunidad indígena porque tiene poco poder."},{"id":"s3","texto":"Buscamos los intereses detrás de cada posición."},{"id":"s4","texto":"Como las posiciones son opuestas, no hay ninguna solución posible."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un mapa incompleto lleva a soluciones incompletas.","por_opcion":{"s2":"Tiene mucho interés y derechos: hay que incluirla.","s4":"Los intereses pueden ser compatibles aunque las posiciones choquen."}}},{"slug":"comunidad-4.s3.p13","orden":13,"grupo":"comunidad-4.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que un actor dice que quiere es su {{0}}; lo que necesita de fondo es su {{1}}; y un mapa de actores los ubica según su interés y su {{2}}.","banco":[{"id":"w1","texto":"posición"},{"id":"w2","texto":"interés"},{"id":"w3","texto":"poder"},{"id":"w4","texto":"opinión"},{"id":"w5","texto":"capricho"},{"id":"w6","texto":"edad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para mapear un conflicto antes de actuar."}},{"slug":"comunidad-4.s3.p14","orden":14,"grupo":"comunidad-4.s3.p14","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas ayudan a encontrar el interés detrás de una posición? Marcá todas.","opciones":[{"id":"o1","texto":"¿Por qué es importante esto para vos?"},{"id":"o2","texto":"¿Qué te preocupa que pase?"},{"id":"o3","texto":"¿Qué necesitarías para sentirte tranquilo?"},{"id":"o4","texto":"¿Por qué estás equivocado?"},{"id":"o5","texto":"¿Quién te dijo que pensaras eso?"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las preguntas abiertas y respetuosas revelan intereses; las acusatorias los esconden."}}]},{"slug":"comunidad-4.s4","orden":4,"tipo":"leccion","titulo_es":"Herramientas y garantías","bajada_es":"Evaluación de impacto, audiencias, información pública, amparo, consulta previa y la protección de quienes defienden el ambiente.","minutos":10,"pasos":[{"slug":"comunidad-4.s4.p1","orden":1,"grupo":"comunidad-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Herramientas institucionales","cuerpo":["Argentina tiene varias herramientas para canalizar conflictos ambientales. La Ley General del Ambiente exige evaluación de impacto ambiental antes de obras que puedan degradar el ambiente y prevé instancias de participación, como audiencias públicas. La Ley 25.831 garantiza el acceso a la información pública ambiental. El amparo ambiental permite pedir a un juez que frene un daño. Y el Convenio 169 de la OIT obliga a consultar a los pueblos indígenas."]},"solucion":{}},{"slug":"comunidad-4.s4.p2","orden":2,"grupo":"comunidad-4.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con para qué sirve.","izquierda":[{"id":"a1","texto":"Evaluación de impacto ambiental"},{"id":"a2","texto":"Audiencia pública"},{"id":"a3","texto":"Pedido de información pública"},{"id":"a4","texto":"Amparo ambiental"},{"id":"a5","texto":"Consulta previa"}],"derecha":[{"id":"b1","texto":"Analizar los efectos antes de aprobar una obra"},{"id":"b2","texto":"Escuchar a la comunidad antes de decidir"},{"id":"b3","texto":"Conocer datos que tiene el Estado"},{"id":"b4","texto":"Pedir a un juez que frene un daño"},{"id":"b5","texto":"Dialogar con pueblos indígenas antes de decidir"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada herramienta tiene su momento y su función."}},{"slug":"comunidad-4.s4.p3","orden":3,"grupo":"comunidad-4.s4.p3","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cuándo se usa cada herramienta, en un proyecto típico.","items":[{"id":"i1","texto":"Pedir información pública sobre el proyecto"},{"id":"i2","texto":"Participar en la evaluación de impacto y la audiencia"},{"id":"i3","texto":"Controlar el cumplimiento de las condiciones"},{"id":"i4","texto":"Recurrir a la justicia si hay un daño o un incumplimiento"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las herramientas preventivas van antes; las judiciales, cuando lo anterior no alcanzó."}},{"slug":"comunidad-4.s4.p4","orden":4,"grupo":"comunidad-4.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quienes defienden el ambiente","cuerpo":["Defender el ambiente puede ser peligroso. La organización Global Witness registra cada año asesinatos de personas defensoras de la tierra y del ambiente: más de 2.000 desde 2012, la mayoría en América Latina, y al menos 124 en 2025. Además hay amenazas, criminalización y acoso. El Acuerdo de Escazú, que Argentina aprobó, es el primer tratado del mundo con disposiciones específicas para proteger a las personas defensoras de derechos humanos en asuntos ambientales."]},"solucion":{}},{"slug":"comunidad-4.s4.p5","orden":5,"grupo":"comunidad-4.s4.p5","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas personas defensoras de la tierra y el ambiente fueron asesinadas en el mundo desde 2012, según Global Witness.","min":10,"max":100000,"paso":1,"unidad":"personas","escala":"log"},"solucion":{"valor":2000,"banda":"log","explicacion":"Más de 2.000 desde 2012, la mayoría en América Latina. Por eso la protección de las personas defensoras es parte de la justicia ambiental."}},{"slug":"comunidad-4.s4.p6","orden":6,"grupo":"comunidad-4.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El Acuerdo de Escazú incluye disposiciones para proteger a quienes defienden el ambiente.","razones":[{"id":"r1","texto":"Porque incluye disposiciones específicas sobre personas defensoras"},{"id":"r2","texto":"Porque Escazú solo trata sobre comercio"},{"id":"r3","texto":"Porque Argentina no lo aprobó"}]},"solucion":{"valor":true,"explicacion":"Es el primer tratado del mundo que lo hace de forma específica, junto con garantizar el acceso a la información, la participación y la justicia ambiental.","clave":["r1"]}},{"slug":"comunidad-4.s4.p7","orden":7,"grupo":"comunidad-4.s4.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué situaciones ponen en riesgo a las personas defensoras del ambiente? Marcá todas.","opciones":[{"id":"o1","texto":"Amenazas por denunciar un desmonte ilegal"},{"id":"o2","texto":"Causas judiciales infundadas por protestar pacíficamente"},{"id":"o3","texto":"Campañas de desprestigio en redes"},{"id":"o4","texto":"Recibir información pública que pidieron"},{"id":"o5","texto":"Participar en una audiencia pública"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Proteger a quienes defienden el ambiente es condición para que las otras herramientas funcionen."}},{"slug":"comunidad-4.s4.p8","orden":8,"grupo":"comunidad-4.s4.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una herramienta preventiva o una de reparación?","grupos":[{"id":"g1","nombre":"Preventiva"},{"id":"g2","nombre":"De reparación o corrección"}],"items":[{"id":"i1","texto":"Evaluación de impacto ambiental"},{"id":"i2","texto":"Amparo por un daño en curso"},{"id":"i3","texto":"Consulta previa"},{"id":"i4","texto":"Juicio para recomponer un río contaminado"},{"id":"i5","texto":"Audiencia pública"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Prevenir es más barato y justo que reparar; por eso las herramientas preventivas son centrales."}},{"slug":"comunidad-4.s4.p9","orden":9,"grupo":"comunidad-4.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio aprueba un proyecto sin evaluación de impacto ni audiencia. ¿Qué pueden hacer los vecinos?","opciones":[{"id":"o1","texto":"Pedir información y presentar un amparo"},{"id":"o2","texto":"Nada, porque la decisión ya está tomada"},{"id":"o3","texto":"Destruir la obra por su cuenta"},{"id":"o4","texto":"Esperar a que el daño ocurra para reclamar"}]},"solucion":{"clave":["o1"],"explicacion":"Los caminos institucionales existen para usarse, y la justicia puede frenar decisiones que no cumplen la ley.","por_opcion":{"o3":"Es ilegal y violento; hay caminos institucionales."}}},{"slug":"comunidad-4.s4.p10","orden":10,"grupo":"comunidad-4.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Ley 25.831 fija un plazo de hasta 30 días hábiles para responder un pedido de información ambiental. Si el organismo ya tardó 25 días hábiles, ¿cuántos le quedan dentro del plazo?","unidad":"días hábiles","decimales":0,"contexto":"Plazo de 30 días hábiles; ya pasaron 25."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"30 − 25 = 5 días hábiles. Si vence el plazo sin respuesta, se puede reclamar por vía administrativa o judicial."}},{"slug":"comunidad-4.s4.p10.v2","orden":10,"grupo":"comunidad-4.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Ley 25.831 fija un plazo de hasta 30 días hábiles para responder un pedido de información ambiental. Si el organismo ya tardó 20 días hábiles, ¿cuántos le quedan dentro del plazo?","unidad":"días hábiles","decimales":0,"contexto":"Plazo de 30 días hábiles; ya pasaron 20."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"30 − 20 = 10 días hábiles. Si vence el plazo sin respuesta, se puede reclamar por vía administrativa o judicial."}},{"slug":"comunidad-4.s4.p10.v3","orden":10,"grupo":"comunidad-4.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Ley 25.831 fija un plazo de hasta 30 días hábiles para responder un pedido de información ambiental. Si el organismo ya tardó 30 días hábiles, ¿cuántos le quedan dentro del plazo?","unidad":"días hábiles","decimales":0,"contexto":"Plazo de 30 días hábiles; ya pasaron 30."},"solucion":{"valor":0,"tolerancia":0.5,"explicacion":"30 − 30 = 0 días hábiles. Si vence el plazo sin respuesta, se puede reclamar por vía administrativa o judicial."}},{"slug":"comunidad-4.s4.p11","orden":11,"grupo":"comunidad-4.s4.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué herramienta te permite conocer los datos de monitoreo del agua que tiene la secretaría de ambiente?","opciones":[{"id":"o1","texto":"Un pedido de información pública ambiental"},{"id":"o2","texto":"Un plebiscito municipal sobre el agua"},{"id":"o3","texto":"Un amparo por daño inminente"},{"id":"o4","texto":"Una encuesta en redes sociales"}]},"solucion":{"clave":["o1"],"explicacion":"La Ley 25.831 garantiza el acceso a la información ambiental que tiene el Estado.","por_opcion":{"o3":"Sirve para frenar un daño; para obtener datos, primero se piden."}}},{"slug":"comunidad-4.s4.p12","orden":12,"grupo":"comunidad-4.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este volante y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Tenemos derecho a pedir información pública ambiental."},{"id":"s2","texto":"El amparo ambiental solo lo pueden usar las empresas."},{"id":"s3","texto":"La evaluación de impacto debe hacerse antes de aprobar una obra."},{"id":"s4","texto":"Defender el ambiente nunca implica riesgos personales."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer los derechos y los riesgos es parte de participar con responsabilidad.","por_opcion":{"s2":"Pueden usarlo personas y organizaciones afectadas.","s4":"Muchas personas defensoras sufren amenazas y violencia."}}},{"slug":"comunidad-4.s4.p13","orden":13,"grupo":"comunidad-4.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Analizar los efectos de una obra antes de aprobarla es una evaluación de {{0}} ambiental; pedirle a un juez que frene un daño es un {{1}}; y el tratado regional que protege a las personas defensoras es el Acuerdo de {{2}}.","banco":[{"id":"w1","texto":"impacto"},{"id":"w2","texto":"amparo"},{"id":"w3","texto":"Escazú"},{"id":"w4","texto":"precio"},{"id":"w5","texto":"contrato"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres herramientas clave para canalizar conflictos ambientales."}}]},{"slug":"comunidad-4.s5","orden":5,"tipo":"leccion","titulo_es":"Transformar el conflicto","bajada_es":"Diálogo, confianza, monitoreo conjunto y acuerdos: cómo se pasa de la confrontación a soluciones que duren.","minutos":12,"pasos":[{"slug":"comunidad-4.s5.p1","orden":1,"grupo":"comunidad-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Transformar, no solo resolver","cuerpo":["Resolver un conflicto a veces se entiende como \"que termine\". Transformarlo es más ambicioso: cambiar las relaciones y las reglas que lo produjeron, para que la próxima vez haya información, participación y confianza. Un acuerdo que deja resentimiento y desconfianza suele reabrirse; uno construido con todas las partes tiene más chances de durar."]},"solucion":{}},{"slug":"comunidad-4.s5.p2","orden":2,"grupo":"comunidad-4.s5.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué diferencia hay entre resolver y transformar un conflicto?","opciones":[{"id":"o1","texto":"Transformar cambia las reglas que lo causaron"},{"id":"o2","texto":"Resolver siempre es más lento que transformar"},{"id":"o3","texto":"Transformar significa que una parte gane"},{"id":"o4","texto":"No hay ninguna diferencia entre las dos"}]},"solucion":{"clave":["o1"],"explicacion":"Transformar apunta a que el conflicto no se repita con las mismas causas.","por_opcion":{"o3":"No: busca cambiar las condiciones, no un ganador."}}},{"slug":"comunidad-4.s5.p3","orden":3,"grupo":"comunidad-4.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Construir confianza","cuerpo":["La confianza se construye con hechos: información completa y a tiempo, compromisos que se cumplen, reglas claras sobre cómo se decide, y monitoreo que todos pueden ver. El monitoreo participativo —en el que la comunidad, la empresa y el Estado miden juntos el agua o el aire, con laboratorios independientes y datos públicos— es una herramienta poderosa: cambia la discusión de \"a quién le creemos\" a \"qué muestran los datos\"."]},"solucion":{}},{"slug":"comunidad-4.s5.p4","orden":4,"grupo":"comunidad-4.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el monitoreo participativo construye confianza.","items":[{"id":"i1","texto":"Comunidad, empresa y Estado acuerdan qué medir"},{"id":"i2","texto":"Un laboratorio independiente toma las muestras"},{"id":"i3","texto":"Los resultados se publican para todos"},{"id":"i4","texto":"Si hay un problema, se actúa con reglas pactadas"},{"id":"i5","texto":"La discusión se basa en datos compartidos"},{"id":"i6","texto":"Cada parte mide por su cuenta y oculta los resultados"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los datos compartidos no eliminan los desacuerdos, pero los vuelven discutibles con evidencia."}},{"slug":"comunidad-4.s5.p5","orden":5,"grupo":"comunidad-4.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Diálogo y mediación","cuerpo":["En una mesa de diálogo, los actores se sientan a buscar acuerdos con reglas claras: quién participa, cómo se toman decisiones, qué información se comparte. A veces ayuda una persona mediadora, neutral, que facilita la conversación. El diálogo funciona mejor cuando hay equilibrio: si una parte tiene toda la información y el poder, la mesa puede usarse para legitimar una decisión ya tomada."]},"solucion":{}},{"slug":"comunidad-4.s5.p6","orden":6,"grupo":"comunidad-4.s5.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué condiciones hacen que una mesa de diálogo sea genuina? Marcá todas.","opciones":[{"id":"o1","texto":"Todas las partes afectadas están invitadas"},{"id":"o2","texto":"La información se comparte antes de las reuniones"},{"id":"o3","texto":"Las reglas para decidir son claras y acordadas"},{"id":"o4","texto":"Los acuerdos se publican y se controlan"},{"id":"o5","texto":"La decisión ya está tomada antes de empezar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una mesa de diálogo sin condiciones reales es un trámite, no una transformación."}},{"slug":"comunidad-4.s5.p7","orden":7,"grupo":"comunidad-4.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El \"no\" también es una respuesta","cuerpo":["Transformar un conflicto no significa que todos los proyectos tengan que aprobarse con condiciones. A veces, después de estudiar y dialogar, la conclusión legítima es que un proyecto no debe hacerse en ese lugar, o que debe cambiar mucho. Aceptar que el \"no\" es una salida posible es parte de un proceso honesto: si el resultado está decidido de antemano, no es un diálogo."]},"solucion":{}},{"slug":"comunidad-4.s5.p8","orden":8,"grupo":"comunidad-4.s5.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un proceso de diálogo genuino siempre debe terminar con la aprobación del proyecto.","razones":[{"id":"r1","texto":"Porque el rechazo también es una salida legítima"},{"id":"r2","texto":"Porque el diálogo nunca aprueba proyectos"},{"id":"r3","texto":"Porque las comunidades deciden todo solas"}]},"solucion":{"valor":false,"explicacion":"Si el resultado está definido de antemano, no es diálogo. Un proceso honesto puede terminar en aprobación con condiciones, en cambios grandes o en el rechazo del proyecto.","clave":["r1"]}},{"slug":"comunidad-4.s5.p9","orden":9,"grupo":"comunidad-4.s5.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción ayuda a transformar el conflicto o lo agrava?","grupos":[{"id":"g1","nombre":"Ayuda"},{"id":"g2","nombre":"Agrava"}],"items":[{"id":"i1","texto":"Monitoreo participativo con datos públicos"},{"id":"i2","texto":"Firmar un acuerdo con una sola parte"},{"id":"i3","texto":"Mediación con reglas acordadas"},{"id":"i4","texto":"Cambiar las reglas a mitad del proceso"},{"id":"i5","texto":"Cumplir los compromisos a tiempo"},{"id":"i6","texto":"Descalificar a quienes reclaman"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo que construye confianza transforma; lo que la destruye, agrava."}},{"slug":"comunidad-4.s5.p10","orden":10,"grupo":"comunidad-4.s5.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas salidas de un conflicto de la más duradera a la menos duradera.","items":[{"id":"i1","texto":"Acuerdo con todas las partes, monitoreo conjunto y controles"},{"id":"i2","texto":"Decisión judicial que ordena condiciones"},{"id":"i3","texto":"Acuerdo firmado solo con una parte"},{"id":"i4","texto":"Imponer la decisión por la fuerza"}],"extremos":["Más duradera","Menos duradera"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los acuerdos que incluyen a todos y se controlan tienden a durar más.","valores":{"i1":"la más duradera","i2":"duradera si se controla","i3":"frágil","i4":"la menos duradera"}}},{"slug":"comunidad-4.s5.p11","orden":11,"grupo":"comunidad-4.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un acuerdo, la empresa asumió 20 compromisos y cumplió 17 en el plazo. ¿Qué porcentaje cumplió?","unidad":"%","decimales":0,"contexto":"17 de 20 compromisos cumplidos."},"solucion":{"valor":85,"tolerancia":1,"explicacion":"17 ÷ 20 × 100 = 85 %. Publicar este tipo de indicador es parte de construir confianza."}},{"slug":"comunidad-4.s5.p11.v2","orden":11,"grupo":"comunidad-4.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un acuerdo, la empresa asumió 12 compromisos y cumplió 9 en el plazo. ¿Qué porcentaje cumplió?","unidad":"%","decimales":0,"contexto":"9 de 12 compromisos cumplidos."},"solucion":{"valor":75,"tolerancia":1,"explicacion":"9 ÷ 12 × 100 = 75 %. Publicar este tipo de indicador es parte de construir confianza."}},{"slug":"comunidad-4.s5.p11.v3","orden":11,"grupo":"comunidad-4.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un acuerdo, la empresa asumió 30 compromisos y cumplió 27 en el plazo. ¿Qué porcentaje cumplió?","unidad":"%","decimales":0,"contexto":"27 de 30 compromisos cumplidos."},"solucion":{"valor":90,"tolerancia":1,"explicacion":"27 ÷ 30 × 100 = 90 %. Publicar este tipo de indicador es parte de construir confianza."}},{"slug":"comunidad-4.s5.p12","orden":12,"grupo":"comunidad-4.s5.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con su aporte.","izquierda":[{"id":"a1","texto":"Monitoreo participativo"},{"id":"a2","texto":"Mediación"},{"id":"a3","texto":"Reglas acordadas"},{"id":"a4","texto":"Informes de cumplimiento"}],"derecha":[{"id":"b1","texto":"Datos que todas las partes aceptan"},{"id":"b2","texto":"Una persona neutral facilita el diálogo"},{"id":"b3","texto":"Todos saben cómo se decide"},{"id":"b4","texto":"Se ve si los compromisos se cumplen"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada herramienta aporta una pieza de la confianza."}},{"slug":"comunidad-4.s5.p13","orden":13,"grupo":"comunidad-4.s5.p13","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de una mesa de diálogo genuina.","items":[{"id":"i1","texto":"Acordar quiénes participan, incluidos los más afectados"},{"id":"i2","texto":"Acordar las reglas y compartir la información"},{"id":"i3","texto":"Discutir opciones que atiendan los intereses de todos"},{"id":"i4","texto":"Firmar acuerdos con plazos y responsables"},{"id":"i5","texto":"Controlar y publicar el cumplimiento"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Participantes, reglas, opciones, acuerdos y control: sin alguno, la mesa pierde legitimidad."}},{"slug":"comunidad-4.s5.p14","orden":14,"grupo":"comunidad-4.s5.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este acuerdo y marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"Habrá monitoreo del río con un laboratorio independiente."},{"id":"s2","texto":"Los resultados del monitoreo serán confidenciales."},{"id":"s3","texto":"Se reunirá una mesa con todas las partes cada tres meses."},{"id":"s4","texto":"La empresa podrá cambiar las reglas del acuerdo cuando quiera."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen acuerdo es transparente, estable y controlable.","por_opcion":{"s2":"Sin datos públicos no se construye confianza.","s4":"Las reglas deben acordarse y respetarse."}}},{"slug":"comunidad-4.s5.p15","orden":15,"grupo":"comunidad-4.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cambiar las relaciones y reglas que causan un conflicto es {{0}}; medir juntos con datos públicos es monitoreo {{1}}; y una persona neutral que facilita el diálogo cumple el rol de {{2}}.","banco":[{"id":"w1","texto":"transformarlo"},{"id":"w2","texto":"participativo"},{"id":"w3","texto":"mediación"},{"id":"w4","texto":"ignorarlo"},{"id":"w5","texto":"secreto"},{"id":"w6","texto":"sanción"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para transformar conflictos ambientales."}}]},{"slug":"comunidad-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: conflictos ambientales","bajada_es":"Tipos y etapas, casos argentinos, mapa de actores, herramientas y transformación, mezclados.","minutos":8,"pasos":[{"slug":"comunidad-4.s6.p1","orden":1,"grupo":"comunidad-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Conflictos ambientales». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"comunidad-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la planta junto al río","bajada_es":"Una empresa propone una planta industrial junto al río de un pueblo. El conflicto está empezando. Diseñá un proceso para que no escale.","minutos":10,"pasos":[{"slug":"comunidad-4.s7.p1","orden":1,"grupo":"comunidad-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Una empresa anunció una planta procesadora a 2 km del pueblo, junto al río del que toman agua 8.000 habitantes y varias familias de pescadores. Promete 150 empleos. Los vecinos se enteraron por el diario, no vieron ningún estudio y empiezan a organizarse. El municipio quiere la inversión. Una comunidad indígena que vive río abajo no fue mencionada. La empresa dice que \"no hay nada que discutir porque todo es legal\"."]},"solucion":{}},{"slug":"comunidad-4.s7.p2","orden":2,"grupo":"comunidad-4.s7.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Ubicá a cada actor según su poder e interés.","grupos":[{"id":"g1","nombre":"Mucho poder, mucho interés"},{"id":"g2","nombre":"Poco poder, mucho interés"}],"items":[{"id":"i1","texto":"La empresa"},{"id":"i2","texto":"Los vecinos que toman agua del río"},{"id":"i3","texto":"El municipio"},{"id":"i4","texto":"Las familias de pescadores"},{"id":"i5","texto":"La comunidad indígena río abajo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Los actores más afectados son los que tienen menos poder: el proceso tiene que darles voz."}},{"slug":"comunidad-4.s7.p3","orden":3,"grupo":"comunidad-4.s7.p3","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué errores están haciendo escalar el conflicto? Marcá todos.","opciones":[{"id":"o1","texto":"Los vecinos se enteraron por el diario"},{"id":"o2","texto":"No se publicó ningún estudio"},{"id":"o3","texto":"No se mencionó a la comunidad indígena"},{"id":"o4","texto":"La empresa dice que no hay nada que discutir"},{"id":"o5","texto":"La empresa anunció empleos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Falta de información, exclusión y desprecio: la receta clásica de la escalada."}},{"slug":"comunidad-4.s7.p4","orden":4,"grupo":"comunidad-4.s7.p4","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená un proceso para transformar el conflicto.","items":[{"id":"i1","texto":"Publicar el proyecto y su evaluación de impacto completa"},{"id":"i2","texto":"Hacer audiencias accesibles y la consulta previa a la comunidad indígena"},{"id":"i3","texto":"Acordar monitoreo independiente del río si el proyecto avanza"},{"id":"i4","texto":"Decidir con condiciones claras, o no aprobar si los riesgos son altos"},{"id":"i5","texto":"Publicar informes de cumplimiento periódicos"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Información, participación, datos compartidos, decisión honesta y control."}},{"slug":"comunidad-4.s7.p5","orden":5,"grupo":"comunidad-4.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La empresa dice \"no hay nada que discutir porque todo es legal\". ¿Qué problema tiene esa postura?","opciones":[{"id":"o1","texto":"Ignora el derecho de los vecinos a participar"},{"id":"o2","texto":"Que las empresas nunca cumplen la ley"},{"id":"o3","texto":"Que la ley no se aplica a las empresas"},{"id":"o4","texto":"Que la planta es demasiado chica"}]},"solucion":{"clave":["o1"],"explicacion":"Cumplir la ley incluye informar y permitir participar; y aun así, escuchar es clave para evitar la escalada.","por_opcion":{"o3":"Se aplica; y justamente incluye evaluación de impacto y participación."}}},{"slug":"comunidad-4.s7.p6","orden":6,"grupo":"comunidad-4.s7.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la planta ofrece 150 empleos y la condición acordada es que el 60 % sean de la zona, ¿cuántos puestos serían para personas locales?","unidad":"puestos","decimales":0,"contexto":"150 empleos; 60 % locales."},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"150 × 0,6 = 90 puestos para personas de la zona. Una condición concreta y medible."}},{"slug":"comunidad-4.s7.p7","orden":7,"grupo":"comunidad-4.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el municipio quiere la inversión, no hace falta consultar a la comunidad indígena río abajo.","razones":[{"id":"r1","texto":"Porque la consulta es un derecho que no depende del municipio"},{"id":"r2","texto":"Porque las comunidades indígenas no usan el río"},{"id":"r3","texto":"Porque el Convenio 169 no rige en Argentina"}]},"solucion":{"valor":false,"explicacion":"La consulta previa es un derecho reconocido por el Convenio 169, y el municipio no puede decidir por la comunidad. Además, excluirla agravaría el conflicto.","clave":["r1"]}},{"slug":"comunidad-4.s7.p8","orden":8,"grupo":"comunidad-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el plan del proceso. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Publicaremos la evaluación de impacto completa antes de la audiencia."},{"id":"s2","texto":"La audiencia será un martes a las 9 en la capital provincial."},{"id":"s3","texto":"Consultaremos a la comunidad indígena antes de decidir."},{"id":"s4","texto":"Los resultados del monitoreo los verá solo la empresa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proceso cuida los detalles: lugar, horario, información y transparencia.","por_opcion":{"s2":"Conviene hacerla en el pueblo, en un horario accesible.","s4":"Deben ser públicos para construir confianza."}}}]}]}$ac$::jsonb);
